window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["ROM"]={"book":"ROM","editions":{"dan-1819":[[1,1,"Paulus, Jesu Christi Tjener, kaldet til Apostel, beskikket til at forkynde Guds Evangelium,","Paulus, Jesu Christi Tjener, kaldet til Apostel, beskikket til at forkynde Guds Evangelium,"],[1,2,"hvilket han forud havde lovet ved sine Propheter i de hellige Skrifter,","hvilket han forud havde lovet ved sine Propheter i de hellige Skrifter,"],[1,3,"om sin Søn, født af Davids Sæd efter Kjødet,","om sin Søn, født af Davids Sæd efter Kjødet,"],[1,4,"krafteligen beviist at være Guds Søn efter Hellighedens Aand ved Opstandelsen fra de Døde: om Jesus Christus, vor Herre,","krafteligen beviist at være Guds Søn efter Hellighedens Aand ved Opstandelsen fra de Døde: om Jesus Christus, vor Herre,"],[1,5,"ved hvem vi have faaet Naade og Apostelembedet til at oprette Troens Lydighed iblandt alle Hedninger formedelst hans Navn,","ved hvem vi have faaet Naade og Apostelembedet til at oprette Troens Lydighed iblandt alle Hedninger formedelst hans Navn,"],[1,6,"blandt hvilke ogsaa I ere Jesu Christi Kaldte:","blandt hvilke ogsaa I ere Jesu Christi Kaldte:"],[1,7,"Eder alle, som ere i Rom, Guds Elskelige, kaldte Hellige, være Naade og Fred, fra Gud vor Fader og den Herre Jesus Christus!","Eder alle, som ere i Rom, Guds Elskelige, kaldte Hellige, være Naade og Fred, fra Gud vor Fader og den Herre Jesus Christus!"],[1,8,"Først takker jeg min Gud ved Jesus Christus for Eder alle, at Eders Tro omtales i den ganske Verden.","Først takker jeg min Gud ved Jesus Christus for Eder alle, at Eders Tro omtales i den ganske Verden."],[1,9,"Thi Gud er mit Vidne, hvem jeg i min Aand tjener udi hans Søns Evangelium, hvorledes jeg uden Afladelse tænker paa Eder,","Thi Gud er mit Vidne, hvem jeg i min Aand tjener udi hans Søns Evangelium, hvorledes jeg uden Afladelse tænker paa Eder,"],[1,10,"altid begjerende i mine Bønner, at jeg dog engang maatte faae Held til efter Guds Villie, at komme til Eder.","altid begjerende i mine Bønner, at jeg dog engang maatte faae Held til efter Guds Villie, at komme til Eder."],[1,11,"Thi mig forlænges efter at see Eder, at jeg kunde meddele Eder nogen aandelig Naadegave, saa I maatte styrkes,","Thi mig forlænges efter at see Eder, at jeg kunde meddele Eder nogen aandelig Naadegave, saa I maatte styrkes,"],[1,12,"det er, at vi hos Eder maatte opmuntres tilsammen ved fælles Tro, baade Eders og min.","det er, at vi hos Eder maatte opmuntres tilsammen ved fælles Tro, baade Eders og min."],[1,13,"Jeg vil ikke, Brødre! at I skulle være uvidende om, at jeg haver ofte sat mig for at komme til Eder, (men jeg haver hidindtil været forhindret), paa det jeg maatte have nogen Frugt ogsaa iblandt Eder, ligesom og iblandt de andre Hedninger.","Jeg vil ikke, Brødre! at I skulle være uvidende om, at jeg haver ofte sat mig for at komme til Eder, (men jeg haver hidindtil været forhindret), paa det jeg maatte have nogen Frugt ogsaa iblandt Eder, ligesom og iblandt de andre Hedninger."],[1,14,"Baade Græker og Barbarer , baade Vise og Uvise er jeg en Skyldner.","Baade Græker og Barbarer , baade Vise og Uvise er jeg en Skyldner."],[1,15,"Saaledes er jeg og, hvad mig angaaer, redebon at prædike Evangelium ogsaa for Eder, som ere i Rom.","Saaledes er jeg og, hvad mig angaaer, redebon at prædike Evangelium ogsaa for Eder, som ere i Rom."],[1,16,"Jeg skammer mig ikke ved Christi Evangelium; thi det er en Guds Kraft til Saliggjørelse for hver den, som troer, baade for Jøde først og for Græker.","Jeg skammer mig ikke ved Christi Evangelium; thi det er en Guds Kraft til Saliggjørelse for hver den, som troer, baade for Jøde først og for Græker."],[1,17,"Thi derudi aabenbares Guds Retfærdighed ved Troen for Troen , som skrevet staaer: den Retfærdige ved Troen skal leve.","Thi derudi aabenbares Guds Retfærdighed ved Troen for Troen , som skrevet staaer: den Retfærdige ved Troen skal leve."],[1,18,"Men Guds Vrede aabenbares af Himmelen over al de Menneskers Ugudelighed og Uretfærdighed, som forholde Sandheden ved Uretfærdighed.","Men Guds Vrede aabenbares af Himmelen over al de Menneskers Ugudelighed og Uretfærdighed, som forholde Sandheden ved Uretfærdighed."],[1,19,"Thi det, som man kan vide om Gud, er dem aabenbart; thi Gud haver aabenbaret dem det.","Thi det, som man kan vide om Gud, er dem aabenbart; thi Gud haver aabenbaret dem det."],[1,20,"Thi hans usynlige Væsen, hans evige Kraft og Guddommelighed beskues fra Verdens Skabelse af og forstaaes af hans Gjerninger, saa at de have ingen Undskyldning.","Thi hans usynlige Væsen, hans evige Kraft og Guddommelighed beskues fra Verdens Skabelse af og forstaaes af hans Gjerninger, saa at de have ingen Undskyldning."],[1,21,"Thi enddog de kjendte Gud, saa ærede eller takkede de ham dog ikke som Gud, men bleve forfængelige i deres Tanker, og deres uforstandige Hjerte blev formørket.","Thi enddog de kjendte Gud, saa ærede eller takkede de ham dog ikke som Gud, men bleve forfængelige i deres Tanker, og deres uforstandige Hjerte blev formørket."],[1,22,"Der de sagde sig at være vise, bleve de Daarer,","Der de sagde sig at være vise, bleve de Daarer,"],[1,23,"og forvendte den uforkrænkelige Guds Herlighed til Lighed med et forkrænkeligt Menneskes og Fugles og fiirføddede Dyrs og Ormes Billede.","og forvendte den uforkrænkelige Guds Herlighed til Lighed med et forkrænkeligt Menneskes og Fugles og fiirføddede Dyrs og Ormes Billede."],[1,24,"Derfor haver og Gud givet dem hen i deres Hjertes Begjeringer til Ureenhed, saa at de indbyrdes vanærede deres Legemer.","Derfor haver og Gud givet dem hen i deres Hjertes Begjeringer til Ureenhed, saa at de indbyrdes vanærede deres Legemer."],[1,25,"De forvendte Guds Sandhed til Løgn og dyrkede og tjente Skabningen over Skaberen, som er velsignet i Evighed! Amen.","De forvendte Guds Sandhed til Løgn og dyrkede og tjente Skabningen over Skaberen, som er velsignet i Evighed! Amen."],[1,26,"Desaarsag haver Gud givet dem hen i skjændige Lyster; thi baade deres Kvinder forvendte den naturlige Brug til den unaturlige,","Desaarsag haver Gud givet dem hen i skjændige Lyster; thi baade deres Kvinder forvendte den naturlige Brug til den unaturlige,"],[1,27,"og desligeste ogsaa Mændene: de forlode Kvindens naturlige Brug og optændtes i deres Lyster til hverandre, saa at Mænd med Mænd øvede Uteerlighed og fik deres Vildfarelses Løn, som det burde sig, paa dem selv.","og desligeste ogsaa Mændene: de forlode Kvindens naturlige Brug og optændtes i deres Lyster til hverandre, saa at Mænd med Mænd øvede Uteerlighed og fik deres Vildfarelses Løn, som det burde sig, paa dem selv."],[1,28,"Og ligesom de ikke holdt for godt at have Guds Kundskab, saa gav Gud dem hen i et Sind, som duer intet, at gjøre det Usømmelige,","Og ligesom de ikke holdt for godt at have Guds Kundskab, saa gav Gud dem hen i et Sind, som duer intet, at gjøre det Usømmelige,"],[1,29,"opfyldte med al Uretfærdighed, Horeri, Skalkhed, Gjerrighed, Ondskab; fulde af Avind, Blodtørst, Trætte, Svig, Vanart;","opfyldte med al Uretfærdighed, Horeri, Skalkhed, Gjerrighed, Ondskab; fulde af Avind, Blodtørst, Trætte, Svig, Vanart;"],[1,30,"Øretudere, Bagvaskere, Guds-Hadere, Forhaanere, hovmodige, opblæste, Udaads Opfindere, Forældre ulydige,","Øretudere, Bagvaskere, Guds-Hadere, Forhaanere, hovmodige, opblæste, Udaads Opfindere, Forældre ulydige,"],[1,31,"uforstandige, troløse, ukjærlige, uforligelige, ubarmhjertige;","uforstandige, troløse, ukjærlige, uforligelige, ubarmhjertige;"],[1,32,"hvilke, enddog de kjende Guds retfærdige Dom, at de, som gjøre saadanne Ting, ere skyldige at døe, dog ikke alene gjøre det, men bifalde ogsaa dem, som det gjøre.","hvilke, enddog de kjende Guds retfærdige Dom, at de, som gjøre saadanne Ting, ere skyldige at døe, dog ikke alene gjøre det, men bifalde ogsaa dem, som det gjøre."],[2,1,"Derfor er du uden Undskyldning, o Menneske! hvo du er, som dømmer ; thi idet du dømmer en Anden, fordømmer du dig selv; thi du, som dømmer, gjør selv det Samme.","Derfor er du uden Undskyldning, o Menneske! hvo du er, som dømmer ; thi idet du dømmer en Anden, fordømmer du dig selv; thi du, som dømmer, gjør selv det Samme."],[2,2,"Vi vide jo, at Guds Dom er efter Sandhed over dem, som gjøre Saadant.","Vi vide jo, at Guds Dom er efter Sandhed over dem, som gjøre Saadant."],[2,3,"Men tænker du dette, o Menneske! du som dømmer dem, der gjøre Saadant, og gjør selv det Samme, at du skal undflye Guds Dom?","Men tænker du dette, o Menneske! du som dømmer dem, der gjøre Saadant, og gjør selv det Samme, at du skal undflye Guds Dom?"],[2,4,"Eller foragter du hans Godheds og Taalmodigheds og Langmodigheds Rigdom, og veed ikke, at Guds Godhed leder dig til Omvendelse?","Eller foragter du hans Godheds og Taalmodigheds og Langmodigheds Rigdom, og veed ikke, at Guds Godhed leder dig til Omvendelse?"],[2,5,"Men efter din Haardhed og dit ubodfærdige Hjerte Samler du dig selv Vrede, paa Vredens og Guds retfærdige Doms Aabenbarelses Dag.","Men efter din Haardhed og dit ubodfærdige Hjerte Samler du dig selv Vrede, paa Vredens og Guds retfærdige Doms Aabenbarelses Dag."],[2,6,"Thi han skal betale hver efter hans Gjerninger:","Thi han skal betale hver efter hans Gjerninger:"],[2,7,"dem, som ved Bestandighed i god Gjerning søge Ære og Hæder og Uforkrænkelighed, et evigt Liv;","dem, som ved Bestandighed i god Gjerning søge Ære og Hæder og Uforkrænkelighed, et evigt Liv;"],[2,8,"men dem, som ere gjenstridige, og ikke lyde Sandhed, men adlyde Uretfærdighed, skal vorde Ugunst og Vrede.","men dem, som ere gjenstridige, og ikke lyde Sandhed, men adlyde Uretfærdighed, skal vorde Ugunst og Vrede."],[2,9,"Trængsel og Angest skal være over hvert Menneskes Sjæl, som gjør det Onde, baade en Jødes først og en Grækers;","Trængsel og Angest skal være over hvert Menneskes Sjæl, som gjør det Onde, baade en Jødes først og en Grækers;"],[2,10,"men Ære og Hæder og Fred skal vorde hver den, som gjør det Gode, baade en Jøde først og en Græker.","men Ære og Hæder og Fred skal vorde hver den, som gjør det Gode, baade en Jøde først og en Græker."],[2,11,"Thi der er ingen Persons Anseelse hos Gud.","Thi der er ingen Persons Anseelse hos Gud."],[2,12,"Hvilkesomhelst have syndet uden Loven, de straffes og uden Loven , og hvilkesomhelst have syndet under Loven, de skulle dømmes ved Loven;","Hvilkesomhelst have syndet uden Loven, de straffes og uden Loven , og hvilkesomhelst have syndet under Loven, de skulle dømmes ved Loven;"],[2,13,"(thi ikke Lovens Hørere ere retfærdige for Gud, men Lovens Gjørere skulle retfærdiggjøres.","(thi ikke Lovens Hørere ere retfærdige for Gud, men Lovens Gjørere skulle retfærdiggjøres."],[2,14,"Thi efterdi Hedningerne, som ikke have Loven, gjøre af Naturen Lovens Gjerninger, da ere de, enddog de ikke have Loven, dem selv en Lov;","Thi efterdi Hedningerne, som ikke have Loven, gjøre af Naturen Lovens Gjerninger, da ere de, enddog de ikke have Loven, dem selv en Lov;"],[2,15,"de vise Lovens Gjerning skreven i deres Hjerter, idet deres Samvittighed vidner med dem, og Tankerne indbyrdes anklage eller og forsvare hverandre;)","de vise Lovens Gjerning skreven i deres Hjerter, idet deres Samvittighed vidner med dem, og Tankerne indbyrdes anklage eller og forsvare hverandre;)"],[2,16,"paa den Dag, naar Gud skal dømme Menneskenes skjulte Idrætter efter mit Evangelium, ved Jesus Christus.","paa den Dag, naar Gud skal dømme Menneskenes skjulte Idrætter efter mit Evangelium, ved Jesus Christus."],[2,17,"See, du kalder dig en Jøde og forlader dig tryggeligen paa Loven og roser dig i Gud,","See, du kalder dig en Jøde og forlader dig tryggeligen paa Loven og roser dig i Gud,"],[2,18,"og veed hans Villie og prøver Tingenes Forskjel, underviist af Loven,","og veed hans Villie og prøver Tingenes Forskjel, underviist af Loven,"],[2,19,"og fordrister dig til at være de Blindes Veileder, deres Lys, som ere i Mørke,","og fordrister dig til at være de Blindes Veileder, deres Lys, som ere i Mørke,"],[2,20,"Uforstandiges Tugtemester, Eenfoldiges Lærer, som har Reglen for Kundskab og Sandhed i Loven.","Uforstandiges Tugtemester, Eenfoldiges Lærer, som har Reglen for Kundskab og Sandhed i Loven."],[2,21,"Du derfor, som lærer Andre, du lærer ikke dig selv! Du, som prædiker, at man ikke skal stjæle, du stjæler!","Du derfor, som lærer Andre, du lærer ikke dig selv! Du, som prædiker, at man ikke skal stjæle, du stjæler!"],[2,22,"Du, som siger, at man ikke skal bedrive Hoer, du bedriver Hoer! Du, som haver Vederstyggelighed til Afguder, du raner det Hellige!","Du, som siger, at man ikke skal bedrive Hoer, du bedriver Hoer! Du, som haver Vederstyggelighed til Afguder, du raner det Hellige!"],[2,23,"Du, som roser dig af Loven, du vanærer Gud ved Lovens Overtrædelse!","Du, som roser dig af Loven, du vanærer Gud ved Lovens Overtrædelse!"],[2,24,"Thi for Eder Skyld bespottes Guds Navn iblandt Hedningerne, som skrevet er.","Thi for Eder Skyld bespottes Guds Navn iblandt Hedningerne, som skrevet er."],[2,25,"Vel er Omskærelsen nyttig, om du holder Loven; men er du Lovens Overtræder, da er din Omskærelse bleven en Forhud.","Vel er Omskærelsen nyttig, om du holder Loven; men er du Lovens Overtræder, da er din Omskærelse bleven en Forhud."],[2,26,"Dersom nu Forhuden holder Lovens Bud, mon da ikke hans Forhud regnes som Omskærelse?","Dersom nu Forhuden holder Lovens Bud, mon da ikke hans Forhud regnes som Omskærelse?"],[2,27,"Og den legemlige Forhud, som opfylder Loven, skal dømme dig, som med Bogstav og Omskærelse er Lovens Overtræder.","Og den legemlige Forhud, som opfylder Loven, skal dømme dig, som med Bogstav og Omskærelse er Lovens Overtræder."],[2,28,"Thi ikke den, som udvortes er Jøde, er derfor Jøde; ei heller er den Omskærelse, som skeer udvortes i Kjødet, derfor Omskærelse;","Thi ikke den, som udvortes er Jøde, er derfor Jøde; ei heller er den Omskærelse, som skeer udvortes i Kjødet, derfor Omskærelse;"],[2,29,"men den, som indvortes er Jøde, og Hjertets Omskærelse i Aanden, ikke efter Bogstaven: en Saadan har Roes, ikke af Mennesker, men af Gud.","men den, som indvortes er Jøde, og Hjertets Omskærelse i Aanden, ikke efter Bogstaven: en Saadan har Roes, ikke af Mennesker, men af Gud."],[3,1,"Hvad er da Jødernes Fortrin? eller hvad gavner Omskærelsen?","Hvad er da Jødernes Fortrin? eller hvad gavner Omskærelsen?"],[3,2,"Meget i alle Maader; fornemmeligen, at Guds Ord ere dem betroede.","Meget i alle Maader; fornemmeligen, at Guds Ord ere dem betroede."],[3,3,"Thi hvad? dersom og Nogle vare vantroe, mon deres Vantro gjøre Guds Trofasthed til Intet?","Thi hvad? dersom og Nogle vare vantroe, mon deres Vantro gjøre Guds Trofasthed til Intet?"],[3,4,"Det være langt fra! Gud maa være sanddru, om endog hvert Menneske er Løgner, som skrevet er: at du maa befindes retfærdig i dine Ord og vinde, naar du dømmes.","Det være langt fra! Gud maa være sanddru, om endog hvert Menneske er Løgner, som skrevet er: at du maa befindes retfærdig i dine Ord og vinde, naar du dømmes."],[3,5,"Men dersom vor Uretfærdighed beviser Guds Retfærdighed, hvad skulle vi da sige? mon Gud være uretfærdig, idet han fører Vreden over os? (Jeg taler efter menneskelig Viis).","Men dersom vor Uretfærdighed beviser Guds Retfærdighed, hvad skulle vi da sige? mon Gud være uretfærdig, idet han fører Vreden over os? (Jeg taler efter menneskelig Viis)."],[3,6,"Det være langt fra! Hvorledes kunde Gud da dømme Verden?","Det være langt fra! Hvorledes kunde Gud da dømme Verden?"],[3,7,"Thi dersom Guds Sandhed haver viist sig ydermere til hans Ære formedelst min Troløshed, hvi dømmes jeg da endnu som en Synder?","Thi dersom Guds Sandhed haver viist sig ydermere til hans Ære formedelst min Troløshed, hvi dømmes jeg da endnu som en Synder?"],[3,8,"Og hvorfor skulle vi da ikke, (som man bespotteligen siger om os, og som Nogle foregive, at vi lære), gjøre Ondt, at der kan komme Godt af? Saadannes Fordømmelse er retfærdig.","Og hvorfor skulle vi da ikke, (som man bespotteligen siger om os, og som Nogle foregive, at vi lære), gjøre Ondt, at der kan komme Godt af? Saadannes Fordømmelse er retfærdig."],[3,9,"Hvad da? have vi Noget forud? Aldeles Intet; thi vi have forhen beviist, at baade Jøder og Græker ere alle under Synd,","Hvad da? have vi Noget forud? Aldeles Intet; thi vi have forhen beviist, at baade Jøder og Græker ere alle under Synd,"],[3,10,"som skrevet staaer: der er Ingen retfærdig, end ikke Een;","som skrevet staaer: der er Ingen retfærdig, end ikke Een;"],[3,11,"der er Ingen forstandig, der er Ingen, som søger efter Gud;","der er Ingen forstandig, der er Ingen, som søger efter Gud;"],[3,12,"alle ere afvegne; de ere tilsammen blevne uduelige, der er Ingen, som gjør Godt, der er end ikke Een.","alle ere afvegne; de ere tilsammen blevne uduelige, der er Ingen, som gjør Godt, der er end ikke Een."],[3,13,"En aabnet Grav er deres Strube; med deres Tunger besvige de; Øglers Forgift er under deres Læber;","En aabnet Grav er deres Strube; med deres Tunger besvige de; Øglers Forgift er under deres Læber;"],[3,14,"deres Mund er fuld af Forbandelser og Beeskhed;","deres Mund er fuld af Forbandelser og Beeskhed;"],[3,15,"deres Fødder ere snare til at udøse Blod.","deres Fødder ere snare til at udøse Blod."],[3,16,"Der er Fordærvelse og Elendighed i deres Veie,","Der er Fordærvelse og Elendighed i deres Veie,"],[3,17,"og Fredens Vei have de ikke kjendt.","og Fredens Vei have de ikke kjendt."],[3,18,"Der er ikke Gudsfrygt for deres Øine.","Der er ikke Gudsfrygt for deres Øine."],[3,19,"Men vi vide, at hvadsomhelst Loven siger, siger den til dem, som ere under Loven, saa at hver Mund skal tilstoppes og al Verden være skyldig for Gud.","Men vi vide, at hvadsomhelst Loven siger, siger den til dem, som ere under Loven, saa at hver Mund skal tilstoppes og al Verden være skyldig for Gud."],[3,20,"Derfor kan intet Kjød blive retfærdiggjort for ham ved Lovens Gjerninger; thi ved Loven kommer Syndens Erkjendelse.","Derfor kan intet Kjød blive retfærdiggjort for ham ved Lovens Gjerninger; thi ved Loven kommer Syndens Erkjendelse."],[3,21,"Men nu er uden Loven Guds Retfærdighed aabenbaret, om hvilken er vidnet ved Loven og Propheterne.","Men nu er uden Loven Guds Retfærdighed aabenbaret, om hvilken er vidnet ved Loven og Propheterne."],[3,22,"Guds Retfærdighed ved Jesu Christi Tro, for Alle og over Alle, som troe; thi der er ikke Forskjel.","Guds Retfærdighed ved Jesu Christi Tro, for Alle og over Alle, som troe; thi der er ikke Forskjel."],[3,23,"Alle have jo syndet, og dem fattes Ære for Gud,","Alle have jo syndet, og dem fattes Ære for Gud,"],[3,24,"og de blive retfærdiggjort uforskyldt af hans Naade, ved den Forløsning, som er i Christus Jesus,","og de blive retfærdiggjort uforskyldt af hans Naade, ved den Forløsning, som er i Christus Jesus,"],[3,25,"hvilken Gud haver fremstillet til en Forsoning formedelst Troen paa hans Blod, for at vise sin Retfærdighed ved de forhen begangne Synders Forladelse i Guds Langmodighed;","hvilken Gud haver fremstillet til en Forsoning formedelst Troen paa hans Blod, for at vise sin Retfærdighed ved de forhen begangne Synders Forladelse i Guds Langmodighed;"],[3,26,"for at vise sin Retfærdighed paa den nærværende Tid, at han maa være retfærdig og gjøre den retfærdig, som er af Jesu Tro.","for at vise sin Retfærdighed paa den nærværende Tid, at han maa være retfærdig og gjøre den retfærdig, som er af Jesu Tro."],[3,27,"Hvor er altsaa vor Roes? Den er udelukt. Formedelst hvilken Lov? Gjerningernes? Nei, men Formedelst Troens Lov.","Hvor er altsaa vor Roes? Den er udelukt. Formedelst hvilken Lov? Gjerningernes? Nei, men Formedelst Troens Lov."],[3,28,"Derfor slutte vi, at Mennesket bliver retfærdiggjort ved Troen, uden Lovens Gjerninger.","Derfor slutte vi, at Mennesket bliver retfærdiggjort ved Troen, uden Lovens Gjerninger."],[3,29,"Eller er Gud alene Jødernes Gud? mon ikke ogsaa Hedningernes? Jo, ogsaa Hedningernes.","Eller er Gud alene Jødernes Gud? mon ikke ogsaa Hedningernes? Jo, ogsaa Hedningernes."],[3,30,"Efterdi der er een Gud, som vil retfærdiggjøre den Omskaarne ved Troen, og den Uomskaarne formedelst Troen.","Efterdi der er een Gud, som vil retfærdiggjøre den Omskaarne ved Troen, og den Uomskaarne formedelst Troen."],[3,31,"Afskaffe vi da Loven formedelst Troen? Det være langt fra! Nei, vi stadfæste Loven.","Afskaffe vi da Loven formedelst Troen? Det være langt fra! Nei, vi stadfæste Loven."],[4,1,"Hvad skulle vi da sige, at vor Fader Abraham vandt efter Kjødet ?","Hvad skulle vi da sige, at vor Fader Abraham vandt efter Kjødet ?"],[4,2,"Thi dersom Abraham blev retfærdiggjort ved Gjerninger, haver han Roes, men ikke for Gud.","Thi dersom Abraham blev retfærdiggjort ved Gjerninger, haver han Roes, men ikke for Gud."],[4,3,"Thi hvad siger Skriften? Abraham troede Gud, og det blev regnet ham til Retfærdighed.","Thi hvad siger Skriften? Abraham troede Gud, og det blev regnet ham til Retfærdighed."],[4,4,"Men den, som har Gjerninger at fremvise, tilregnes Lønnen ikke af Naade, men som Skyldighed:","Men den, som har Gjerninger at fremvise, tilregnes Lønnen ikke af Naade, men som Skyldighed:"],[4,5,"den derimod, som ikke har Gjerninger, men troer paa ham, som retfærdiggjør Synderen, regnes hans Tro til Retfærdighed;","den derimod, som ikke har Gjerninger, men troer paa ham, som retfærdiggjør Synderen, regnes hans Tro til Retfærdighed;"],[4,6,"ligesom og David priser det Menneske saligt, hvilket Gud tilregner Retfærdighed uden Gjerninger:","ligesom og David priser det Menneske saligt, hvilket Gud tilregner Retfærdighed uden Gjerninger:"],[4,7,"salige de, hvis Overtrædelser ere forladte, og hvis Synder ere skjulte;","salige de, hvis Overtrædelser ere forladte, og hvis Synder ere skjulte;"],[4,8,"salig den Mand, hvem Herren ikke vil tilregne Synd.","salig den Mand, hvem Herren ikke vil tilregne Synd."],[4,9,"Tilhører da denne Salighed Omskærelsen alene, eller ogsaa Forhuden? Vi sige jo, at Troen blev regnet Abraham til Retfærdighed.","Tilhører da denne Salighed Omskærelsen alene, eller ogsaa Forhuden? Vi sige jo, at Troen blev regnet Abraham til Retfærdighed."],[4,10,"Hvorledes blev den ham da tilregnet? da han var omskaaren, eller da han havde Forhud? Ikke da han var omskaaren, men da han havde Forhud.","Hvorledes blev den ham da tilregnet? da han var omskaaren, eller da han havde Forhud? Ikke da han var omskaaren, men da han havde Forhud."],[4,11,"Og han annammede Omskærelsens Tegn som en Befaling paa den Retfærdighed ved Troen, hvilken han havde som uomskaaren, saa at han skulde være Fædre til alle dem, som troe uden at være omskaarne, at Retfærdighed maa vorde ogsaa dem tilregnet,","Og han annammede Omskærelsens Tegn som en Befaling paa den Retfærdighed ved Troen, hvilken han havde som uomskaaren, saa at han skulde være Fædre til alle dem, som troe uden at være omskaarne, at Retfærdighed maa vorde ogsaa dem tilregnet,"],[4,12,"og Fader til de Omskaarne, til dem, som ikke alene have Omskærelse, men ogsaa vandre i den Troes Forspor, hvilken vor Fader Abraham havde som uomskaaren.","og Fader til de Omskaarne, til dem, som ikke alene have Omskærelse, men ogsaa vandre i den Troes Forspor, hvilken vor Fader Abraham havde som uomskaaren."],[4,13,"Thi ikke formedelst Loven fik Abraham og hans Sæd den Forjættelse, at han skulde arve Verden, men formedelst Troens Retfærdighed.","Thi ikke formedelst Loven fik Abraham og hans Sæd den Forjættelse, at han skulde arve Verden, men formedelst Troens Retfærdighed."],[4,14,"Og ere de, som holde sig til Loven, Arvinger, da er Troen Forgjeves, og Forjættelsen gjort til Intet.","Og ere de, som holde sig til Loven, Arvinger, da er Troen Forgjeves, og Forjættelsen gjort til Intet."],[4,15,"Loven virker Straf; thi hvor der ikke er Lov, der er heller ikke Overtrædelse.","Loven virker Straf; thi hvor der ikke er Lov, der er heller ikke Overtrædelse."],[4,16,"Derfor er Forjættelsen ved Tro, saa den tildeles af Naade, paa det den maatte staae fast for den ganske Sæd, ikke alene for den, som haver Loven, men og for den, som haver Abrahams Tro, hvilken er alle vores Fader,","Derfor er Forjættelsen ved Tro, saa den tildeles af Naade, paa det den maatte staae fast for den ganske Sæd, ikke alene for den, som haver Loven, men og for den, som haver Abrahams Tro, hvilken er alle vores Fader,"],[4,17,"(som skrevet er: jeg haver sat dig til mange Folks Fader,) for Gud, hvem han troede, som levendegjør de Døde, og kalder de Ting, der ikke ere, som om de vare.","(som skrevet er: jeg haver sat dig til mange Folks Fader,) for Gud, hvem han troede, som levendegjør de Døde, og kalder de Ting, der ikke ere, som om de vare."],[4,18,"Han troede imod Haab mod Haab, at han skulde vorde mange Folks Fader, efter det, som sagt var: saaledes skal din Sæd vorde;","Han troede imod Haab mod Haab, at han skulde vorde mange Folks Fader, efter det, som sagt var: saaledes skal din Sæd vorde;"],[4,19,"og uden at vakle i Troen, saae han ikke paa sit eget Legeme, som allerede var kraftesløst, thi han var nær hundrede Aar, eller paa Kraftløsheden i Saras Liv;","og uden at vakle i Troen, saae han ikke paa sit eget Legeme, som allerede var kraftesløst, thi han var nær hundrede Aar, eller paa Kraftløsheden i Saras Liv;"],[4,20,"han tvivlede ikke i Vantro paa Guds Forjættelse, men styrket i Troen, gav han Gud Æren,","han tvivlede ikke i Vantro paa Guds Forjættelse, men styrket i Troen, gav han Gud Æren,"],[4,21,"fuldkommeligen vis paa, at hvad han havde lovet, var han og mægtig til at gjøre.","fuldkommeligen vis paa, at hvad han havde lovet, var han og mægtig til at gjøre."],[4,22,"Derfor blev det og regnet ham til Retfærdighed.","Derfor blev det og regnet ham til Retfærdighed."],[4,23,"Dog er det ikke skrevet for hans Skyld alene, at det blev ham tilregnet,","Dog er det ikke skrevet for hans Skyld alene, at det blev ham tilregnet,"],[4,24,"men ogsaa for vor Skyld, hvilke det skal tilregnes, naar vi troe paa den, der opreiste vor Herre Jesus fra de Døde;","men ogsaa for vor Skyld, hvilke det skal tilregnes, naar vi troe paa den, der opreiste vor Herre Jesus fra de Døde;"],[4,25,"hvilken er given hen for vore Overtrædelser, og opreist for vor Retfærdiggjørelse.","hvilken er given hen for vore Overtrædelser, og opreist for vor Retfærdiggjørelse."],[5,1,"Altsaa, retfærdiggjorte ved Troen, have vi Fred med Gud ved vor Herre Jesus Christus,","Altsaa, retfærdiggjorte ved Troen, have vi Fred med Gud ved vor Herre Jesus Christus,"],[5,2,"ved hvem vi have erholdt Adgang i Troen til den Naade, hvori vi staae, og vi rose os af Haab om Herlighed hos Gud;","ved hvem vi have erholdt Adgang i Troen til den Naade, hvori vi staae, og vi rose os af Haab om Herlighed hos Gud;"],[5,3,"ja, ikke det alene, men vi rose os ogsaa af vore Trængsler, efterdi vi vide at Trængslen virker Standhaftighed,","ja, ikke det alene, men vi rose os ogsaa af vore Trængsler, efterdi vi vide at Trængslen virker Standhaftighed,"],[5,4,"men Standhaftigheden Forfarenhed, men Forfarenhed Haab,","men Standhaftigheden Forfarenhed, men Forfarenhed Haab,"],[5,5,"men Haabet beskæmmer ikke; thi Guds Kjærlighed er udøst i vore Hjerter ved den Hellig Aand, som er given os.","men Haabet beskæmmer ikke; thi Guds Kjærlighed er udøst i vore Hjerter ved den Hellig Aand, som er given os."],[5,6,"Thi da vi endnu vare Overtrædere, døde Christus til bestemte Tid for de Ugudelige.","Thi da vi endnu vare Overtrædere, døde Christus til bestemte Tid for de Ugudelige."],[5,7,"Neppe døer Nogen for en Retfærdig; for den Gode var der maaskee Nogen, som turde døe;","Neppe døer Nogen for en Retfærdig; for den Gode var der maaskee Nogen, som turde døe;"],[5,8,"men Gud beviser sin Kjærlighed mod os derved, at Christus døde for os, da vi endnu vare Syndere.","men Gud beviser sin Kjærlighed mod os derved, at Christus døde for os, da vi endnu vare Syndere."],[5,9,"Saa meget mere skulle vi derfor, nu retfærdiggjorte ved hans Blod, frelses ved ham fra Vreden.","Saa meget mere skulle vi derfor, nu retfærdiggjorte ved hans Blod, frelses ved ham fra Vreden."],[5,10,"Thi dersom vi bleve forligte med Gud formedelst hans Søns Død, der vi vare Fjender, da skulle vi meget mere, efter at vi ere forligte, frelses ved hans Liv.","Thi dersom vi bleve forligte med Gud formedelst hans Søns Død, der vi vare Fjender, da skulle vi meget mere, efter at vi ere forligte, frelses ved hans Liv."],[5,11,"Ja, ikke det alene, men vi rose os ogsaa i Gud ved vor Herre Jesus Christus, ved hvem vi nu have faaet Forligelsen.","Ja, ikke det alene, men vi rose os ogsaa i Gud ved vor Herre Jesus Christus, ved hvem vi nu have faaet Forligelsen."],[5,12,"Altsaa, ligesom Synden kom ind i Verden ved eet Menneske, og Døden ved Synden, og saaledes Døden trængte igjennem til alle Mennesker, idet de syndede alle.","Altsaa, ligesom Synden kom ind i Verden ved eet Menneske, og Døden ved Synden, og saaledes Døden trængte igjennem til alle Mennesker, idet de syndede alle."],[5,13,"(Thi Synden var i Verden indtil Loven ; men hvor der ikke er Lov, tilregnes ikke Synd;","(Thi Synden var i Verden indtil Loven ; men hvor der ikke er Lov, tilregnes ikke Synd;"],[5,14,"dog herskede Døden fra Adam til Moses ogsaa over dem, som ikke syndede i Lighed med Adams Overtrædelse, hvilken er et Billede paa ham, som skulde komme.","dog herskede Døden fra Adam til Moses ogsaa over dem, som ikke syndede i Lighed med Adams Overtrædelse, hvilken er et Billede paa ham, som skulde komme."],[5,15,"Men det er ikke med Naadegaven som med Faldet; thi døde de Mange ved den Enes Fald, da har meget mere Guds Naade og Gave, ved det ene Menneskes Jesu Christi Naade, udbredt sig overflødig over de Mange.","Men det er ikke med Naadegaven som med Faldet; thi døde de Mange ved den Enes Fald, da har meget mere Guds Naade og Gave, ved det ene Menneskes Jesu Christi Naade, udbredt sig overflødig over de Mange."],[5,16,"Og det er ikke med Gaven, som med den Ene, der syndede; thi Dommen var, efter det ene Fald, til Fordømmelse, men Naaden er, efter mange Fald, til Retfærdiggjørelse.","Og det er ikke med Gaven, som med den Ene, der syndede; thi Dommen var, efter det ene Fald, til Fordømmelse, men Naaden er, efter mange Fald, til Retfærdiggjørelse."],[5,17,"Thi dersom ved Eens Fald Døden herskede formedelst den Ene, da skulle meget mere de, som annamme den overvættes Naade og Retfærdigheds Gave, herske i Livet ved den Ene, Jesus Christus.)","Thi dersom ved Eens Fald Døden herskede formedelst den Ene, da skulle meget mere de, som annamme den overvættes Naade og Retfærdigheds Gave, herske i Livet ved den Ene, Jesus Christus.)"],[5,18,"Altsaa, ligesom der ved Eens Fald kom Fordømmelse over alle Mennesker, saaledes skal og ved Eenes Retfærdighed komme over alle Mennesker Retfærdiggjørelse og Liv.","Altsaa, ligesom der ved Eens Fald kom Fordømmelse over alle Mennesker, saaledes skal og ved Eenes Retfærdighed komme over alle Mennesker Retfærdiggjørelse og Liv."],[5,19,"Thi ligesom ved det ene Menneskes Ulydighed Mange ere blevne Syndere, saa skulle og ved den Enes Lydighed Mange vorde retfærdige.","Thi ligesom ved det ene Menneskes Ulydighed Mange ere blevne Syndere, saa skulle og ved den Enes Lydighed Mange vorde retfærdige."],[5,20,"Men Loven kom til, at Faldet kunde des fuldere kjendes; men hvor Synden blev fuldere kjendt, der viste Naaden sig end overflødigere,","Men Loven kom til, at Faldet kunde des fuldere kjendes; men hvor Synden blev fuldere kjendt, der viste Naaden sig end overflødigere,"],[5,21,"saa at, ligesom Synden herskede ved Døden, saa skal og Naaden herske ved Retfærdighed til et evigt Liv, formedelst Jesus Christus, vor Herre.","saa at, ligesom Synden herskede ved Døden, saa skal og Naaden herske ved Retfærdighed til et evigt Liv, formedelst Jesus Christus, vor Herre."],[6,1,"Hvad skulle vi da sige? skulle vi blive ved i Synden, at Naaden maa blive des overflødigere?","Hvad skulle vi da sige? skulle vi blive ved i Synden, at Naaden maa blive des overflødigere?"],[6,2,"Det være langt fra! Vi, som ere døde fra Synden, hvorledes skulle vi endnu leve i den?","Det være langt fra! Vi, som ere døde fra Synden, hvorledes skulle vi endnu leve i den?"],[6,3,"Vide I ikke, at vi, saa mange som ere døbte til Christus Jesus, ere døbte til hans Død?","Vide I ikke, at vi, saa mange som ere døbte til Christus Jesus, ere døbte til hans Død?"],[6,4,"Vi ere altsaa begravne med ham ved Daaben til Døden, paa det at, ligesom Christus er opreist fra de Døde ved Faderens Herlighed, saa skulle og vi vandre i et nyt Levnet.","Vi ere altsaa begravne med ham ved Daaben til Døden, paa det at, ligesom Christus er opreist fra de Døde ved Faderens Herlighed, saa skulle og vi vandre i et nyt Levnet."],[6,5,"Thi dersom vi ere blevne forenede med ham ved Lighed med hans Død, da skulle vi og være det i Lighed med hans Opstandelse:","Thi dersom vi ere blevne forenede med ham ved Lighed med hans Død, da skulle vi og være det i Lighed med hans Opstandelse:"],[6,6,"efterdi vi vide dette, at vort gamle Menneske er korsfæstet med ham, paa det Syndens Legeme skal blive Intet, saa at vi ikke fremdeles skulle tjene Synden.","efterdi vi vide dette, at vort gamle Menneske er korsfæstet med ham, paa det Syndens Legeme skal blive Intet, saa at vi ikke fremdeles skulle tjene Synden."],[6,7,"Thi hvo som er død, er frigjort fra Synden.","Thi hvo som er død, er frigjort fra Synden."],[6,8,"Men dersom vi ere døde med Christus, da troe vi, at vi og skulle leve med ham,","Men dersom vi ere døde med Christus, da troe vi, at vi og skulle leve med ham,"],[6,9,"efterdi vi vide, at Christus, som er opreist fra de Døde, døer ikke mere; Døden hersker ikke mere over ham.","efterdi vi vide, at Christus, som er opreist fra de Døde, døer ikke mere; Døden hersker ikke mere over ham."],[6,10,"Thi det, han døde, døde han een Gang for Synden; men det, han lever, det lever han for Gud.","Thi det, han døde, døde han een Gang for Synden; men det, han lever, det lever han for Gud."],[6,11,"Saaledes anseer ogsaa I Eder selv som døde for Synden, men som levende for Gud i Christus Jesus, vor Herre.","Saaledes anseer ogsaa I Eder selv som døde for Synden, men som levende for Gud i Christus Jesus, vor Herre."],[6,12,"Derfor herske Synden ikke Eders dødelige Legeme, saa I lyde den i dets Begjeringer.","Derfor herske Synden ikke Eders dødelige Legeme, saa I lyde den i dets Begjeringer."],[6,13,"Fremstiller ei heller Eders Lemmer for Synden til Uretfærdigheds Redskab; men fremstiller Eder selv for Gud som de, der fra Døde ere blevne Levende, og Eders Lemmer for Gud til retfærdigheds Redskab.","Fremstiller ei heller Eders Lemmer for Synden til Uretfærdigheds Redskab; men fremstiller Eder selv for Gud som de, der fra Døde ere blevne Levende, og Eders Lemmer for Gud til retfærdigheds Redskab."],[6,14,"Thi Synden skal ikke herske over Eder; I ere jo ikke under Loven, men under Naaden.","Thi Synden skal ikke herske over Eder; I ere jo ikke under Loven, men under Naaden."],[6,15,"Hvad da? skulle vi synde, efterdi vi ere ikke under Loven, men under Naaden? Det være langt fra!","Hvad da? skulle vi synde, efterdi vi ere ikke under Loven, men under Naaden? Det være langt fra!"],[6,16,"Vide I ikke, at hvem I fremstille Eder som Tjenere til Lydighed, dens Tjenere ere I, hvem I lyde, enten Syndens til Død, eller Lydighedens til Retfærdighed?","Vide I ikke, at hvem I fremstille Eder som Tjenere til Lydighed, dens Tjenere ere I, hvem I lyde, enten Syndens til Død, eller Lydighedens til Retfærdighed?"],[6,17,"Men Gud være Tak, at I have været Syndens Tjenere, men ere nu af Hjertet blevne den Lærdoms Form lydige, hvilken I have annammet,","Men Gud være Tak, at I have været Syndens Tjenere, men ere nu af Hjertet blevne den Lærdoms Form lydige, hvilken I have annammet,"],[6,18,"og frigjorte fra Synden, ere I blevne Retfærdighedens Tjenere.","og frigjorte fra Synden, ere I blevne Retfærdighedens Tjenere."],[6,19,"Jeg taler efter menneskelig Viis formedelst Eders Kjøds Skrøbelighed . Thi ligesom I have fremstillet Eders Lemmer som Ureenheds og Uretfærdigheds Tjenere til Uretfærdighed, saa fremstiller nu Eders Lemmer som Retfærdigheds Tjenere til Helliggjørelse.","Jeg taler efter menneskelig Viis formedelst Eders Kjøds Skrøbelighed . Thi ligesom I have fremstillet Eders Lemmer som Ureenheds og Uretfærdigheds Tjenere til Uretfærdighed, saa fremstiller nu Eders Lemmer som Retfærdigheds Tjenere til Helliggjørelse."],[6,20,"Thi da I vare Syndens Tjenere, vare I frie fra Retfærdigheden.","Thi da I vare Syndens Tjenere, vare I frie fra Retfærdigheden."],[6,21,"Hvad havde I da for Frugt af de Ting, ved hvilke I nu skamme Eder? thi Enden derpaa er Døden.","Hvad havde I da for Frugt af de Ting, ved hvilke I nu skamme Eder? thi Enden derpaa er Døden."],[6,22,"Men nu I ere frigjorte fra Synden og blevne Guds Tjenere, havde I Frugt deraf for Eder til Helliggjørelse, og Enden er et evigt Liv.","Men nu I ere frigjorte fra Synden og blevne Guds Tjenere, havde I Frugt deraf for Eder til Helliggjørelse, og Enden er et evigt Liv."],[6,23,"Thi Syndens Sold er Døden, men Guds Naadegave er et evigt Liv i Christus Jesus, vor Herre.","Thi Syndens Sold er Døden, men Guds Naadegave er et evigt Liv i Christus Jesus, vor Herre."],[7,1,"Vide I ikke, Brødre! (thi jeg taler til dem, som kjende Loven), at Loven hersker over Mennesket, saa lang Tid han lever?","Vide I ikke, Brødre! (thi jeg taler til dem, som kjende Loven), at Loven hersker over Mennesket, saa lang Tid han lever?"],[7,2,"Den gifte Kvinde er bunden ved Loven til Manden, den Stund han lever; men dersom Manden døer, er hun løst fra Mandens Lov.","Den gifte Kvinde er bunden ved Loven til Manden, den Stund han lever; men dersom Manden døer, er hun løst fra Mandens Lov."],[7,3,"Derfor skal hun kaldes en Hore, om hun bliver en anden Mands, medens Manden lever; men dersom Manden er død, er hun fri fra den Lov, saa at hun ikke er en Hore, om hun bliver en anden Mands.","Derfor skal hun kaldes en Hore, om hun bliver en anden Mands, medens Manden lever; men dersom Manden er død, er hun fri fra den Lov, saa at hun ikke er en Hore, om hun bliver en anden Mands."],[7,4,"Ligesaa ere og I, mine Brødre! døde fra Loven ved Christi Legeme , at I skulle blive en Andens, hans, som blev opreist fra de Døde, paa det vi skulle bære Gud Frugt.","Ligesaa ere og I, mine Brødre! døde fra Loven ved Christi Legeme , at I skulle blive en Andens, hans, som blev opreist fra de Døde, paa det vi skulle bære Gud Frugt."],[7,5,"Thi da vi vare i Kjødet , virkede de syndige Lyster, som vaktes ved Loven, i vore Lemmer til at bære Døden Frugt.","Thi da vi vare i Kjødet , virkede de syndige Lyster, som vaktes ved Loven, i vore Lemmer til at bære Døden Frugt."],[7,6,"Men nu ere vi som Døde løste fra Loven, under hvilken vi holdtes, saa at vi skulle tjene i Aandens nye Væsen, og ikke i Bogstavens gamle Væsen.","Men nu ere vi som Døde løste fra Loven, under hvilken vi holdtes, saa at vi skulle tjene i Aandens nye Væsen, og ikke i Bogstavens gamle Væsen."],[7,7,"Hvad skulle vi da sige? er Loven Synd? Det være langt fra! Men jeg kjendte ikke Synden uden ved Loven; thi end Begjerligheden kjendte jeg ikke, dersom Loven ei havde sagt: du skal ikke begjere.","Hvad skulle vi da sige? er Loven Synd? Det være langt fra! Men jeg kjendte ikke Synden uden ved Loven; thi end Begjerligheden kjendte jeg ikke, dersom Loven ei havde sagt: du skal ikke begjere."],[7,8,"Men Synden, som tog Anledning af Budet, virkede al Begjerlighed i mig; thi uden Lov er Synden død.","Men Synden, som tog Anledning af Budet, virkede al Begjerlighed i mig; thi uden Lov er Synden død."],[7,9,"Jeg levede nogen Tid uden Lov, men der Budet kom, blev Synden levende igjen;","Jeg levede nogen Tid uden Lov, men der Budet kom, blev Synden levende igjen;"],[7,10,"og jeg døde, og det Bud, som var givet til Liv, det fandtes at geraade mig til Død;","og jeg døde, og det Bud, som var givet til Liv, det fandtes at geraade mig til Død;"],[7,11,"thi Synden, som tog Anledning af Budet, forførte mig og dræbte mig ved samme.","thi Synden, som tog Anledning af Budet, forførte mig og dræbte mig ved samme."],[7,12,"Saaledes er vel Loven hellig, og Budet er helligt og retfærdigt og godt.","Saaledes er vel Loven hellig, og Budet er helligt og retfærdigt og godt."],[7,13,"Et da det, som er godt, blevet mig til en Død? Det være langt fra! Men Synden, paa det den skulde kjendes som Synd, er det, som formedelst det Gode virkede mig Døden, paa det Synden formedelst Budet skulde vorde overvættes syndig.","Et da det, som er godt, blevet mig til en Død? Det være langt fra! Men Synden, paa det den skulde kjendes som Synd, er det, som formedelst det Gode virkede mig Døden, paa det Synden formedelst Budet skulde vorde overvættes syndig."],[7,14,"Thi vi vide, at Loven er aandelig; men jeg er kjødelig, solgt under Synden.","Thi vi vide, at Loven er aandelig; men jeg er kjødelig, solgt under Synden."],[7,15,"Thi jeg forstaaer ikke, hvad jeg gjør; det, som jeg vil, gjør jeg ikke, men hvad jeg hader, det gjør jeg.","Thi jeg forstaaer ikke, hvad jeg gjør; det, som jeg vil, gjør jeg ikke, men hvad jeg hader, det gjør jeg."],[7,16,"Men gjør jeg det, som jeg ikke vil, da giver jeg Loven det Vidnesbyrd, at den er god.","Men gjør jeg det, som jeg ikke vil, da giver jeg Loven det Vidnesbyrd, at den er god."],[7,17,"Men nu gjør ikke jeg det mere, men Synden, som boer i mig.","Men nu gjør ikke jeg det mere, men Synden, som boer i mig."],[7,18,"Thi jeg veed, at i mig, det er i mit Kjød, boer ikke Godt; Villien har jeg vel, men at udrette det Gode formaaer jeg ikke;","Thi jeg veed, at i mig, det er i mit Kjød, boer ikke Godt; Villien har jeg vel, men at udrette det Gode formaaer jeg ikke;"],[7,19,"thi det Gode, som jeg vil, det gjør jeg ikke; men det Onde, som jeg ikke vil, det gjør jeg.","thi det Gode, som jeg vil, det gjør jeg ikke; men det Onde, som jeg ikke vil, det gjør jeg."],[7,20,"Dersom jeg da gjør det, som jeg ikke vil, saa er det ikke mere mig, der uretter det, men Synden, som boer i mig.","Dersom jeg da gjør det, som jeg ikke vil, saa er det ikke mere mig, der uretter det, men Synden, som boer i mig."],[7,21,"Saa finder jeg da den Lov hos mig, idet jeg vil gjøre det Gode, at det Onde hænger ved mig.","Saa finder jeg da den Lov hos mig, idet jeg vil gjøre det Gode, at det Onde hænger ved mig."],[7,22,"Thi jeg haver Lyst til Guds Lov efter det indvortes Menneske;","Thi jeg haver Lyst til Guds Lov efter det indvortes Menneske;"],[7,23,"men jeg seer en anden Lov i mine Lemmer, som strider imod mit Sinds Lov og tager mig fangen under Syndens Lov, som er i mine Lemmer.","men jeg seer en anden Lov i mine Lemmer, som strider imod mit Sinds Lov og tager mig fangen under Syndens Lov, som er i mine Lemmer."],[7,24,"Jeg elendige Menneske! hvo skal frie mig fra dette Dødsens Legeme?","Jeg elendige Menneske! hvo skal frie mig fra dette Dødsens Legeme?"],[7,25,"Jeg takker Gud ved Jesus Christus, vor Herre. Saa tjener da jeg, den selvsamme, Guds Lov med Sindet, men Syndens Lov med Kjødet.","Jeg takker Gud ved Jesus Christus, vor Herre. Saa tjener da jeg, den selvsamme, Guds Lov med Sindet, men Syndens Lov med Kjødet."],[8,1,"Saa er da nu ingen Fordømmelse for dem, som ere i Christus Jesus, der ikke vandre efter Kjødet, men efter Aanden.","Saa er da nu ingen Fordømmelse for dem, som ere i Christus Jesus, der ikke vandre efter Kjødet, men efter Aanden."],[8,2,"Thi Aandens Lov, der levendegjør i Christus Jesus, haver frigjort mig fra Syndens og Dødens Lov.","Thi Aandens Lov, der levendegjør i Christus Jesus, haver frigjort mig fra Syndens og Dødens Lov."],[8,3,"Thi det, som var Loven umuligt, efterdi den var kraftesløs formedelst Kjødet, det gjorde Gud, da han sendte sin egen Søn i syndigt Kjøds Lignelse og til et Synd-Offer, og straffede saaledes Synden paa Kjødet,","Thi det, som var Loven umuligt, efterdi den var kraftesløs formedelst Kjødet, det gjorde Gud, da han sendte sin egen Søn i syndigt Kjøds Lignelse og til et Synd-Offer, og straffede saaledes Synden paa Kjødet,"],[8,4,"paa det Lovens Fordring skulde fuldbringes i os, som ikke vandre efter Kjødet, men efter Aanden.","paa det Lovens Fordring skulde fuldbringes i os, som ikke vandre efter Kjødet, men efter Aanden."],[8,5,"Thi de, som ere efter Kjødet, sandse det Kjødelige, men de, som ere efter Aanden, det Aandelige.","Thi de, som ere efter Kjødet, sandse det Kjødelige, men de, som ere efter Aanden, det Aandelige."],[8,6,"Thi Kjødets Sands er Døden, men Aandens Sands er Liv og Fred;","Thi Kjødets Sands er Døden, men Aandens Sands er Liv og Fred;"],[8,7,"efterdi Kjødets Sands er Fjendskab imod Gud, thi den er ikke Guds Lov underdanig, ei heller kan den være det.","efterdi Kjødets Sands er Fjendskab imod Gud, thi den er ikke Guds Lov underdanig, ei heller kan den være det."],[8,8,"Men de, som ere kjødelige, kunne ikke tækkes Gud.","Men de, som ere kjødelige, kunne ikke tækkes Gud."],[8,9,"I derimod ere ikke kjødelige, men aandelige, saafremt Guds Aand, boer i Eder; men om Nogen ikke haver Christi Aand, denne er ikke hans.","I derimod ere ikke kjødelige, men aandelige, saafremt Guds Aand, boer i Eder; men om Nogen ikke haver Christi Aand, denne er ikke hans."],[8,10,"Men om Christus er i Eder, da er vel Legemet dødt formedelst Synden, men Aanden er Liv formedelst Retfærdighed.","Men om Christus er i Eder, da er vel Legemet dødt formedelst Synden, men Aanden er Liv formedelst Retfærdighed."],[8,11,"Men om hans Aand, der opreiste Jesus fra de Døde, boer i Eder, da skal han, som opreiste Christus fra de Døde, levendegjøre ogsaa Eders dødelige Legemer formedelst sin Aand, som boer i Eder.","Men om hans Aand, der opreiste Jesus fra de Døde, boer i Eder, da skal han, som opreiste Christus fra de Døde, levendegjøre ogsaa Eders dødelige Legemer formedelst sin Aand, som boer i Eder."],[8,12,"Derfor, Brødre! ere vi ikke Kjødets Skyldnere, saa vi skulde leve efter Kjødet;","Derfor, Brødre! ere vi ikke Kjødets Skyldnere, saa vi skulde leve efter Kjødet;"],[8,13,"thi dersom I leve efter Kjødet, skulle I døe, men dersom I døde Legemets Gjerninger formedelst Aanden, skulle I leve.","thi dersom I leve efter Kjødet, skulle I døe, men dersom I døde Legemets Gjerninger formedelst Aanden, skulle I leve."],[8,14,"Thi saa Mange, som drives af Guds Aand, disse ere Guds Børn.","Thi saa Mange, som drives af Guds Aand, disse ere Guds Børn."],[8,15,"Og I annammede ikke en Trældoms Aand atter til Frygt; men I annammede en sønlig Udkaarelses Aand, i hvilken vi raabe: Abba, Fader!","Og I annammede ikke en Trældoms Aand atter til Frygt; men I annammede en sønlig Udkaarelses Aand, i hvilken vi raabe: Abba, Fader!"],[8,16,"Denne Aand vidner med vor Aand, at vi ere Guds Børn.","Denne Aand vidner med vor Aand, at vi ere Guds Børn."],[8,17,"Men dersom vi ere Børn, ere vi og Arvinger, nemlig Guds Arvinger og Christi Medarvinger, saafremt vi lide med ham, at vi da ogsaa skulle herliggjøres med ham.","Men dersom vi ere Børn, ere vi og Arvinger, nemlig Guds Arvinger og Christi Medarvinger, saafremt vi lide med ham, at vi da ogsaa skulle herliggjøres med ham."],[8,18,"Thi jeg holder for, at den nærværende Tids Lidelser ere ikke at agte mod den Herlighed, som skal aabenbares paa os.","Thi jeg holder for, at den nærværende Tids Lidelser ere ikke at agte mod den Herlighed, som skal aabenbares paa os."],[8,19,"Derfor Venter og Skabningens Forlængsel paa Guds Børns Aabenbarelse.","Derfor Venter og Skabningens Forlængsel paa Guds Børns Aabenbarelse."],[8,20,"Thi Skabningen er underlagt Forfængelighed, (ikke med sin Villie, men efter hans, som lagde den derunder),","Thi Skabningen er underlagt Forfængelighed, (ikke med sin Villie, men efter hans, som lagde den derunder),"],[8,21,"dog i det Haab, at Skabningen selv skal og blive frigjort fra Forkrænkelighedens Trældom til Guds Børns herlige Frihed.","dog i det Haab, at Skabningen selv skal og blive frigjort fra Forkrænkelighedens Trældom til Guds Børns herlige Frihed."],[8,22,"Dog vi vide, at al Skabningen tilsammen sukker og er tilsammen i Smerte indtil nu.","Dog vi vide, at al Skabningen tilsammen sukker og er tilsammen i Smerte indtil nu."],[8,23,"Dog ikke det alene, men ogsaa de, som have Aanden Førstegrøde, ogsaa vi selv skulle i os selv, forventende en sønlig Udkaarelse, vort Legemes Forløsning.","Dog ikke det alene, men ogsaa de, som have Aanden Førstegrøde, ogsaa vi selv skulle i os selv, forventende en sønlig Udkaarelse, vort Legemes Forløsning."],[8,24,"Thi vi ere frelste i Haabet. Men det Haab, som sees, er ikke Haab; thi hvad Nogen seer, hvorledes kan han tillige haabe det?","Thi vi ere frelste i Haabet. Men det Haab, som sees, er ikke Haab; thi hvad Nogen seer, hvorledes kan han tillige haabe det?"],[8,25,"Men dersom vi haabe det, som vi ikke see, da forvente vi det med Taalmodighed.","Men dersom vi haabe det, som vi ikke see, da forvente vi det med Taalmodighed."],[8,26,"Desligeste kommer og Aanden vor Skrøbelighed til Hjælp; thi vi vide ikke, hvad vi skulle bede, som det sig bør, men Aanden selv træder frem for os med uudsigelige Sukke.","Desligeste kommer og Aanden vor Skrøbelighed til Hjælp; thi vi vide ikke, hvad vi skulle bede, som det sig bør, men Aanden selv træder frem for os med uudsigelige Sukke."],[8,27,"Men han, som ransager Hjerterne, veed, hvad Aandens Sands er; thi den træder frem for de Hellige efter Guds Villie.","Men han, som ransager Hjerterne, veed, hvad Aandens Sands er; thi den træder frem for de Hellige efter Guds Villie."],[8,28,"Men vi vide, at alle Ting tjene dem til Gode, som elske Gud, dem, som efter hans Beslutning ere kaldte.","Men vi vide, at alle Ting tjene dem til Gode, som elske Gud, dem, som efter hans Beslutning ere kaldte."],[8,29,"Thi hvilke han forud kjendte, dem haver han og forud beskikket til at vorde dannede efter hans Søns Billede, paa det han skulle være den førstefødte af mange Brødre.","Thi hvilke han forud kjendte, dem haver han og forud beskikket til at vorde dannede efter hans Søns Billede, paa det han skulle være den førstefødte af mange Brødre."],[8,30,"Men hvilke han forud beskikkede, dem haver han og kaldet; og hvilken han kaldte, dem haver han og retfærdiggjort; men hvilke han retfærdiggjorde, dem haver han og herliggjort.","Men hvilke han forud beskikkede, dem haver han og kaldet; og hvilken han kaldte, dem haver han og retfærdiggjort; men hvilke han retfærdiggjorde, dem haver han og herliggjort."],[8,31,"Hvad skulle vi da hertil sige? er Gud for os, hvo kan da være imod os.","Hvad skulle vi da hertil sige? er Gud for os, hvo kan da være imod os."],[8,32,"Han, som ikke sparede sin egen Søn, men gav ham hen for os alle, hvorledes skulle han ikke ogsaa skjenke os alle Ting med ham?","Han, som ikke sparede sin egen Søn, men gav ham hen for os alle, hvorledes skulle han ikke ogsaa skjenke os alle Ting med ham?"],[8,33,"Hvo vil anklage Guds Udvalgte? Gud er den, som retfærdiggjør.","Hvo vil anklage Guds Udvalgte? Gud er den, som retfærdiggjør."],[8,34,"Hvo er den, som fordømmer? Christus er den, som er død, ja meget mere, som og er opreist, som og er ved Guds høire Haand, som og træder frem for os.","Hvo er den, som fordømmer? Christus er den, som er død, ja meget mere, som og er opreist, som og er ved Guds høire Haand, som og træder frem for os."],[8,35,"Hvo skal kunne skille os fra Christi Kjærlighed? Trængsel eller Angest eller Forfølgelse eller Hunger eller Nøgenhed eller Fare eller Sværd?","Hvo skal kunne skille os fra Christi Kjærlighed? Trængsel eller Angest eller Forfølgelse eller Hunger eller Nøgenhed eller Fare eller Sværd?"],[8,36,"(Som skrevet er: for din Skyld dræbes vi den ganske Dag, vi ere regnede som Slagtefaar.)","(Som skrevet er: for din Skyld dræbes vi den ganske Dag, vi ere regnede som Slagtefaar.)"],[8,37,"Men i alt dette mere end seire vi ved ham, som os elskede.","Men i alt dette mere end seire vi ved ham, som os elskede."],[8,38,"Thi jeg er vis paa, at hverken Død, ei heller Liv, ei heller Engle, ei heller Fyrstendømmer, ei heller Magter, ei heller det Nærværende, ei heller det Tilkommende,","Thi jeg er vis paa, at hverken Død, ei heller Liv, ei heller Engle, ei heller Fyrstendømmer, ei heller Magter, ei heller det Nærværende, ei heller det Tilkommende,"],[8,39,"ei heller det Høie, ei heller det Dybe, ei heller nogen anden Skabning skal kunne skille os fra Guds Kjærlighed i Christus Jesus, vor Herre.","ei heller det Høie, ei heller det Dybe, ei heller nogen anden Skabning skal kunne skille os fra Guds Kjærlighed i Christus Jesus, vor Herre."],[9,1,"Jeg siger Sandhed i Christus, jeg lyver ikke, min Samvittighed vidner med mig i den Hellig Aand,","Jeg siger Sandhed i Christus, jeg lyver ikke, min Samvittighed vidner med mig i den Hellig Aand,"],[9,2,"at jeg haver en stor Sorg, og en uafladelig Smerte i mit Inderste.","at jeg haver en stor Sorg, og en uafladelig Smerte i mit Inderste."],[9,3,"Thi jeg ønskede selv at være en Forbandelse fra Christus for mine Brødre, mine Frænder efter Kjødet,","Thi jeg ønskede selv at være en Forbandelse fra Christus for mine Brødre, mine Frænder efter Kjødet,"],[9,4,"hvilke ere Israelitter, hvem den sønlige Udkaarelse og Herligheden og Pagterne og Lovgivningen og Gudstjenesten og Forjættelserne tilhøre,","hvilke ere Israelitter, hvem den sønlige Udkaarelse og Herligheden og Pagterne og Lovgivningen og Gudstjenesten og Forjættelserne tilhøre,"],[9,5,"hvem Fædrene tilhøre, og af hvilke Christus er efter Kjødet, han, som er Gud over Alting, høilovet i Evighed! Amen.","hvem Fædrene tilhøre, og af hvilke Christus er efter Kjødet, han, som er Gud over Alting, høilovet i Evighed! Amen."],[9,6,"Ikke som om Guds Ord haver feilet; thi ikke Alle, som stamme fra Israel, ere Israel;","Ikke som om Guds Ord haver feilet; thi ikke Alle, som stamme fra Israel, ere Israel;"],[9,7,"ei heller ere Alle Abrahams Børn, fordi de ere Abrahams Sæd, men: i Isaak skal Sæden fremkaldes dig.","ei heller ere Alle Abrahams Børn, fordi de ere Abrahams Sæd, men: i Isaak skal Sæden fremkaldes dig."],[9,8,"Det er: ikke de Samme, som ere Børn efter Kjødet , ere Guds Børn; men Forjættelsens Børn regnes til Sæden.","Det er: ikke de Samme, som ere Børn efter Kjødet , ere Guds Børn; men Forjættelsens Børn regnes til Sæden."],[9,9,"Thi dette er Forjættelsens Ord: ved denne Tid vil jeg komme, saa skal Sara have en Søn.","Thi dette er Forjættelsens Ord: ved denne Tid vil jeg komme, saa skal Sara have en Søn."],[9,10,"Saa skete det ikke alene den Gang, men ogsaa med Rebekka, der hun var frugtsommelig ved den Ene, Isaak, vor Fader.","Saa skete det ikke alene den Gang, men ogsaa med Rebekka, der hun var frugtsommelig ved den Ene, Isaak, vor Fader."],[9,11,"Thi der de endnu ikke vare fødte og hverken havde gjort noget Godt eller Ondt, (paa det Guds Beslutning efter Udvælgelse skulde staae fast, ikke ved Gjerninger, men ved ham, som kaldte),","Thi der de endnu ikke vare fødte og hverken havde gjort noget Godt eller Ondt, (paa det Guds Beslutning efter Udvælgelse skulde staae fast, ikke ved Gjerninger, men ved ham, som kaldte),"],[9,12,"da blev der sagt til hende: den Ældre skal tjene den Yngre;","da blev der sagt til hende: den Ældre skal tjene den Yngre;"],[9,13,"som skrevet er: Jakob elskede jeg, men Esau hadede jeg.","som skrevet er: Jakob elskede jeg, men Esau hadede jeg."],[9,14,"Hvad skulle vi da sige? mon der være Uretfærdighed hos Gud? Det være langt fra!","Hvad skulle vi da sige? mon der være Uretfærdighed hos Gud? Det være langt fra!"],[9,15,"Thi han siger til Moses: jeg vil være den miskundelig, hvilken jeg er miskundelig og forbarme mig over den, hvilken jeg forbarmer mig over.","Thi han siger til Moses: jeg vil være den miskundelig, hvilken jeg er miskundelig og forbarme mig over den, hvilken jeg forbarmer mig over."],[9,16,"Derfor staaer det ikke til den, som vil, ei heller til den, som løber, men til Gud, som gjør Miskundhed.","Derfor staaer det ikke til den, som vil, ei heller til den, som løber, men til Gud, som gjør Miskundhed."],[9,17,"Thi Skriften siger til Pharao: til dette Samme har jeg ladet dig staae, at jeg vilde vise min Magt paa dig, og paa det mit Navn skulde forkyndes paa al Jorden.","Thi Skriften siger til Pharao: til dette Samme har jeg ladet dig staae, at jeg vilde vise min Magt paa dig, og paa det mit Navn skulde forkyndes paa al Jorden."],[9,18,"Saa forbarmer han sig da over den, som han vil, men forhærder den, som han vil.","Saa forbarmer han sig da over den, som han vil, men forhærder den, som han vil."],[9,19,"Derfor kunde du sige til mig: hvad klager han over endnu? hvor haver imodstaaet hans Villie?","Derfor kunde du sige til mig: hvad klager han over endnu? hvor haver imodstaaet hans Villie?"],[9,20,"Men, o Menneske! hvo er du, at du vil gaae i Rette mod Gud? mon Noget, som er dannet, kan sige til den, som dannede det: hvi gjorde du mig saaledes?","Men, o Menneske! hvo er du, at du vil gaae i Rette mod Gud? mon Noget, som er dannet, kan sige til den, som dannede det: hvi gjorde du mig saaledes?"],[9,21,"Eller haver Pottemageren ikke Magt over Leret, af det samme Stykke at gjøre et Kar til Ære, men et andet til Vanære?","Eller haver Pottemageren ikke Magt over Leret, af det samme Stykke at gjøre et Kar til Ære, men et andet til Vanære?"],[9,22,"Men hvad, om nu Gud, der han vilde vise Vreden og kundgjøre sin Magt, taalte med stor Langmodighed Vredens Kar , som vare dannede til Fordærvelse;","Men hvad, om nu Gud, der han vilde vise Vreden og kundgjøre sin Magt, taalte med stor Langmodighed Vredens Kar , som vare dannede til Fordærvelse;"],[9,23,"og han nu vilde kundgjøre sin Herligheds Rigdom over Barmhjertighedens Kar , hvilke han forud havde beredt til Herlighed,","og han nu vilde kundgjøre sin Herligheds Rigdom over Barmhjertighedens Kar , hvilke han forud havde beredt til Herlighed,"],[9,24,"hvilke han og kaldte, os nemlig, ikke alene af Jøder, men ogsaa af Hedninger!","hvilke han og kaldte, os nemlig, ikke alene af Jøder, men ogsaa af Hedninger!"],[9,25,"Som han og siger hos Hoseas: jeg vil kalde det mit Folk, som ikke var mit Folk, og hende den Elskede, som ikke var den Elskede;","Som han og siger hos Hoseas: jeg vil kalde det mit Folk, som ikke var mit Folk, og hende den Elskede, som ikke var den Elskede;"],[9,26,"og det skal skee, at paa det Sted, hvor der var sagt til dem: I ere ikke mit Folk, der skulle de kaldes den levende Guds Børn.","og det skal skee, at paa det Sted, hvor der var sagt til dem: I ere ikke mit Folk, der skulle de kaldes den levende Guds Børn."],[9,27,"Men Esaias udraaber over Israel: om end Israels Børns Tal var som Havets Sand, saa skal kun en Levning frelses.","Men Esaias udraaber over Israel: om end Israels Børns Tal var som Havets Sand, saa skal kun en Levning frelses."],[9,28,"Thi der er den, som fuldkommer sit Ord og hasteligen opfylder det i Retfærdighed; ja, et hasteligen opfyldt Ord skal Herren vise paa Jorden.","Thi der er den, som fuldkommer sit Ord og hasteligen opfylder det i Retfærdighed; ja, et hasteligen opfyldt Ord skal Herren vise paa Jorden."],[9,29,"Og som Esaias haver sagt tilforn: dersom den Herre Zebaoth ikke havde levnet os en Sæd, da vare vi blevne som Sodoma og lige med Gomorra.","Og som Esaias haver sagt tilforn: dersom den Herre Zebaoth ikke havde levnet os en Sæd, da vare vi blevne som Sodoma og lige med Gomorra."],[9,30,"Hvad skulle vi da sige? Hedningerne, som ikke jagede efter Retfærdighed, fik Retfærdighed, nemlig den Retfærdighed, som er af Troen:","Hvad skulle vi da sige? Hedningerne, som ikke jagede efter Retfærdighed, fik Retfærdighed, nemlig den Retfærdighed, som er af Troen:"],[9,31,"men Israel, som jagede efter Retfærdigheds Lov, kom ikke til Retfærdigheds Lov.","men Israel, som jagede efter Retfærdigheds Lov, kom ikke til Retfærdigheds Lov."],[9,32,"Hvorfor? fordi de ikke søgte den ved Troen, men ved Lovens Gjerninger. Thi de stødte an paa Anstødsstenen,","Hvorfor? fordi de ikke søgte den ved Troen, men ved Lovens Gjerninger. Thi de stødte an paa Anstødsstenen,"],[9,33,"som skrevet er: see, jeg sætter i Zion en Anstødsteen og en Forargelses Klippe; og hver den, som troer paa ham, skal ikke beskæmmes.","som skrevet er: see, jeg sætter i Zion en Anstødsteen og en Forargelses Klippe; og hver den, som troer paa ham, skal ikke beskæmmes."],[10,1,"Brødre! mit Hjertes Ønske og Begjering til Gud for Israel er om deres Frelse.","Brødre! mit Hjertes Ønske og Begjering til Gud for Israel er om deres Frelse."],[10,2,"Jeg giver dem det Vidnesbyrd, at de have Nidkjærheden for Gud, men ikke med Kundskab;","Jeg giver dem det Vidnesbyrd, at de have Nidkjærheden for Gud, men ikke med Kundskab;"],[10,3,"thi da de ikke kjende Guds Retfærdighed og tragte efter at oprette en egen Retfærdighed, underkaste de sig ikke Guds Retfærdighed .","thi da de ikke kjende Guds Retfærdighed og tragte efter at oprette en egen Retfærdighed, underkaste de sig ikke Guds Retfærdighed ."],[10,4,"Thi Christus er Lovens Ende, til Retfærdighed for hver den, som troer.","Thi Christus er Lovens Ende, til Retfærdighed for hver den, som troer."],[10,5,"Moses skriver om den Retfærdighed, som er af Loven, at det Menneske, som gjør disse Ting, skal derved leve.","Moses skriver om den Retfærdighed, som er af Loven, at det Menneske, som gjør disse Ting, skal derved leve."],[10,6,"Men den Retfærdighed, som er af Troen, siger saaledes: siig ikke i dit Hjerte: hvo vil fare op til Himmelen? nemlig for at hente Christus ned;","Men den Retfærdighed, som er af Troen, siger saaledes: siig ikke i dit Hjerte: hvo vil fare op til Himmelen? nemlig for at hente Christus ned;"],[10,7,"eller: hvo vil fare ned i Afgrunden? nemlig for at hente Christus op fra de Døde.","eller: hvo vil fare ned i Afgrunden? nemlig for at hente Christus op fra de Døde."],[10,8,"Men hvad siger den? Ordet er dig nær, i din Mund og i dit Hjerte, nemlig det Troens Ord, som vi prædike.","Men hvad siger den? Ordet er dig nær, i din Mund og i dit Hjerte, nemlig det Troens Ord, som vi prædike."],[10,9,"Thi dersom du bekjender den Herre Jesus med din Mund og troer i dit Hjerte, at Gud opreiste ham fra de Døde, da skal du blive salig.","Thi dersom du bekjender den Herre Jesus med din Mund og troer i dit Hjerte, at Gud opreiste ham fra de Døde, da skal du blive salig."],[10,10,"Thi med Hjertet troer man til Retfærdighed, men med Munden bekjender man til Saliggjørelse.","Thi med Hjertet troer man til Retfærdighed, men med Munden bekjender man til Saliggjørelse."],[10,11,"Skriften siger jo: hver den, som troer paa ham, skal ikke beskæmmes.","Skriften siger jo: hver den, som troer paa ham, skal ikke beskæmmes."],[10,12,"Og der er ikke Forskjel paa Jøde og Græker; thi den Samme er Alles Herre, som er rig nok for alle dem, som paakalde ham.","Og der er ikke Forskjel paa Jøde og Græker; thi den Samme er Alles Herre, som er rig nok for alle dem, som paakalde ham."],[10,13,"Thi hver den, som paakalder Herrens Navn, skal vorde salig.","Thi hver den, som paakalder Herrens Navn, skal vorde salig."],[10,14,"Hvorledes skulle de vel paakalde den, paa hvem de ikke have troet? men hvorledes skulle de troe paa den, om hvem de ikke have hørt? Men hvorledes skulle de høre, uden der er Nogen, som prædiker?","Hvorledes skulle de vel paakalde den, paa hvem de ikke have troet? men hvorledes skulle de troe paa den, om hvem de ikke have hørt? Men hvorledes skulle de høre, uden der er Nogen, som prædiker?"],[10,15,"men hvorledes skal Nogen prædike, dersom de ikke blive udsendte? Som skrevet er: hvor deilige ere deres Fødder, som forkynde Fred, som forkynde godt Budskab.","men hvorledes skal Nogen prædike, dersom de ikke blive udsendte? Som skrevet er: hvor deilige ere deres Fødder, som forkynde Fred, som forkynde godt Budskab."],[10,16,"Men de løde ikke alle det gode Budskab, som Esaias siger: Herre! hvo troede det, han hørte af os?","Men de løde ikke alle det gode Budskab, som Esaias siger: Herre! hvo troede det, han hørte af os?"],[10,17,"Altsaa kommer Troen derved, at man hører, men at man hører, skeer ved Guds Ord.","Altsaa kommer Troen derved, at man hører, men at man hører, skeer ved Guds Ord."],[10,18,"Nu spørger jeg: have de ikke hørt? Jo sandelig, deres Røst er udgangen over al Jorden, og deres Ord til Jorderiges Grændser.","Nu spørger jeg: have de ikke hørt? Jo sandelig, deres Røst er udgangen over al Jorden, og deres Ord til Jorderiges Grændser."],[10,19,"Jeg spørger atter: haver Israel ikke vidst det? Først siger Moses: jeg vil gjøre Eder nidkjære over et Folk, som ikke er et Folk, over et uforstandigt Folk vil jeg vække Eder til Harme.","Jeg spørger atter: haver Israel ikke vidst det? Først siger Moses: jeg vil gjøre Eder nidkjære over et Folk, som ikke er et Folk, over et uforstandigt Folk vil jeg vække Eder til Harme."],[10,20,"Men Esaias drister sig til at sige: jeg er funden af dem, som mig ikke søgte, jeg er bleven aabenbar for dem, som ikke spurgte efter mig.","Men Esaias drister sig til at sige: jeg er funden af dem, som mig ikke søgte, jeg er bleven aabenbar for dem, som ikke spurgte efter mig."],[10,21,"Men til Israel siger han: jeg udstrakte mine Hænder den ganske Dag til et ulydigt og gjenstridigt Folk.","Men til Israel siger han: jeg udstrakte mine Hænder den ganske Dag til et ulydigt og gjenstridigt Folk."],[11,1,"Jeg spørger derfor: mon Gud haver forskudt sit Folk? Det være langt fra! Thi jeg er og en Israelit, af Abrahams Sæd, af Benjamins Stamme.","Jeg spørger derfor: mon Gud haver forskudt sit Folk? Det være langt fra! Thi jeg er og en Israelit, af Abrahams Sæd, af Benjamins Stamme."],[11,2,"Gud haver ikke forskudt sit Folk, hvilket han forud kjendte. Vide I ikke, hvad Skriften siger om Elias? hvorledes han træder frem for Gud imod Israel, sigende:","Gud haver ikke forskudt sit Folk, hvilket han forud kjendte. Vide I ikke, hvad Skriften siger om Elias? hvorledes han træder frem for Gud imod Israel, sigende:"],[11,3,"Herre! de have ihjelslaget dine Propheter og nedbrudt dine altre, og jeg er alene overbleven, og de efterstræbe mit Liv.","Herre! de have ihjelslaget dine Propheter og nedbrudt dine altre, og jeg er alene overbleven, og de efterstræbe mit Liv."],[11,4,"Men hvad siger det guddommelige Gjensvar til ham? Jeg levnede mig selv syv tusinde Mænd, som ikke have bøiet Knæ for Baal.","Men hvad siger det guddommelige Gjensvar til ham? Jeg levnede mig selv syv tusinde Mænd, som ikke have bøiet Knæ for Baal."],[11,5,"Saaledes er da og i den nærværende Tid en Levning efter Naadens Udvælgelse bleven tilbage.","Saaledes er da og i den nærværende Tid en Levning efter Naadens Udvælgelse bleven tilbage."],[11,6,"Men er det af Naade, da er det ikke mere af Gjerninger, ellers bliver Naaden ikke mere Naade; men er det af Gjerninger, da er det ikke mere Naade, ellers er Gjerningen ikke mere Gjerning.","Men er det af Naade, da er det ikke mere af Gjerninger, ellers bliver Naaden ikke mere Naade; men er det af Gjerninger, da er det ikke mere Naade, ellers er Gjerningen ikke mere Gjerning."],[11,7,"Hvad altsaa? det, Israel søger efter, haver det ikke erholdt, men de Udvalgte have erholdt det; de øvrige bleve forhærdede;","Hvad altsaa? det, Israel søger efter, haver det ikke erholdt, men de Udvalgte have erholdt det; de øvrige bleve forhærdede;"],[11,8,"som skrevet er: Gud gav dem en Dorskheds Aand, Øine til ikke at see, Øren til ikke at høre, indtil denne Dag.","som skrevet er: Gud gav dem en Dorskheds Aand, Øine til ikke at see, Øren til ikke at høre, indtil denne Dag."],[11,9,"Og David siger: deres Bord vorde dem til en Snare og til en Fælde og til et Anstød og til et Vederlag:","Og David siger: deres Bord vorde dem til en Snare og til en Fælde og til et Anstød og til et Vederlag:"],[11,10,"deres Øine vorde Mørke, saa de ikke see, og bøi altid deres Ryg!","deres Øine vorde Mørke, saa de ikke see, og bøi altid deres Ryg!"],[11,11,"Jeg spørger derfor: mon de have stødt an, paa det de skulde falde? Det være langt fra! men ved deres Fald er Saliggjørelsen vederfaren Hedningerne, paa det hine skulle vækkes til Nidkjærhed.","Jeg spørger derfor: mon de have stødt an, paa det de skulde falde? Det være langt fra! men ved deres Fald er Saliggjørelsen vederfaren Hedningerne, paa det hine skulle vækkes til Nidkjærhed."],[11,12,"Men dersom deres Fald er Verdens Rigdom, og deres Skade er Hedningernes Rigdom, hvor meget mere skal deres Fylde være det!","Men dersom deres Fald er Verdens Rigdom, og deres Skade er Hedningernes Rigdom, hvor meget mere skal deres Fylde være det!"],[11,13,"Thi jeg taler til Eder, I af Hedningerne! saavidt jeg er Hedningernes Apostel, ærer jeg mit Embede,","Thi jeg taler til Eder, I af Hedningerne! saavidt jeg er Hedningernes Apostel, ærer jeg mit Embede,"],[11,14,"om jeg dog kunde vække min Slægt til Nidkjærhed og frelse Nogle af dem.","om jeg dog kunde vække min Slægt til Nidkjærhed og frelse Nogle af dem."],[11,15,"Thi dersom deres Forkastelse er Verdens Forligelse, hvad er da deres Antagelse Andet, end Liv af Død?","Thi dersom deres Forkastelse er Verdens Forligelse, hvad er da deres Antagelse Andet, end Liv af Død?"],[11,16,"Men dersom den første Grøde er hellig, da er Deigen ligesaa; og dersom Roden er hellig, da ere Grenene ligesaa.","Men dersom den første Grøde er hellig, da er Deigen ligesaa; og dersom Roden er hellig, da ere Grenene ligesaa."],[11,17,"Men ere nogle af Grenene afbrudte, og er du, en vild Olieqvist, indpodet iblandt dem og bleven meddeelagtig i Olietræets Rod og Fedme,","Men ere nogle af Grenene afbrudte, og er du, en vild Olieqvist, indpodet iblandt dem og bleven meddeelagtig i Olietræets Rod og Fedme,"],[11,18,"da roes dig ikke imod Grenene; men dersom du roser dig, da bærer jo du ikke Roden, men Roden dig.","da roes dig ikke imod Grenene; men dersom du roser dig, da bærer jo du ikke Roden, men Roden dig."],[11,19,"Du vil sige: Grenene ere afbrudte, paa det jeg skulde blive indpodet.","Du vil sige: Grenene ere afbrudte, paa det jeg skulde blive indpodet."],[11,20,"Vel! de ere afbrudte ved Vantro, men du staaer ved Troen; vær ikke overmodig, men frygt!","Vel! de ere afbrudte ved Vantro, men du staaer ved Troen; vær ikke overmodig, men frygt!"],[11,21,"Thi sparede Gud ikke de naturlige Grene, skal han maaskee ei heller spare dig.","Thi sparede Gud ikke de naturlige Grene, skal han maaskee ei heller spare dig."],[11,22,"See derfor Guds Godhed og Strenghed; Strengheden mod dem, som ere faldne, men Godheden mod dig, om du bliver ved i Godheden; ellers skal ogsaa du afhugges.","See derfor Guds Godhed og Strenghed; Strengheden mod dem, som ere faldne, men Godheden mod dig, om du bliver ved i Godheden; ellers skal ogsaa du afhugges."],[11,23,"Men ogsaa hine skulle indpodes, dersom de ikke blive ved i Vantroen; thi Gud er mægtig til atter at indpode dem.","Men ogsaa hine skulle indpodes, dersom de ikke blive ved i Vantroen; thi Gud er mægtig til atter at indpode dem."],[11,24,"Thi dersom du er afhuggen af det Olietræ, som er vildt af Naturen, og imod Naturen er indpodet i et godt Olietræ, hvor meget mere skulle disse, som ere af Naturen Olietræets Grene, indpodes i deres eget Træ?","Thi dersom du er afhuggen af det Olietræ, som er vildt af Naturen, og imod Naturen er indpodet i et godt Olietræ, hvor meget mere skulle disse, som ere af Naturen Olietræets Grene, indpodes i deres eget Træ?"],[11,25,"Thi jeg vil ikke, Brødre! at I skulle være uvidende om denne Hemmlighed, (paa det I ikke skulle mene Eder kloge), at Forhærdelse er kommen over en Deel af Israel, indtil Hedningernes Fylde er indgaaet;","Thi jeg vil ikke, Brødre! at I skulle være uvidende om denne Hemmlighed, (paa det I ikke skulle mene Eder kloge), at Forhærdelse er kommen over en Deel af Israel, indtil Hedningernes Fylde er indgaaet;"],[11,26,"og saa skal det ganske Israel frelses, som skrevet er: fra Zion skal Befrieren komme og afvende Ugudelighed fra Jakob;","og saa skal det ganske Israel frelses, som skrevet er: fra Zion skal Befrieren komme og afvende Ugudelighed fra Jakob;"],[11,27,"og denne er min Pagt med dem, naar jeg har borttaget deres Synder.","og denne er min Pagt med dem, naar jeg har borttaget deres Synder."],[11,28,"Efter Evangelium ere de vel Fjender for Eders Skyld; men efter Udvælgelsen ere de elskelige for Fædrenes Skyld;","Efter Evangelium ere de vel Fjender for Eders Skyld; men efter Udvælgelsen ere de elskelige for Fædrenes Skyld;"],[11,29,"thi Naadegaverne og sit Kald fortryder Gud ikke.","thi Naadegaverne og sit Kald fortryder Gud ikke."],[11,30,"Og ligesom I tilforn vare ulydige mod Gud, men have nu faaet Barmhjertighed ved deres Vantro,","Og ligesom I tilforn vare ulydige mod Gud, men have nu faaet Barmhjertighed ved deres Vantro,"],[11,31,"saaledes ere og disse nu blevne ulydige ved den Barmhjertighed som Eder er vederfaren, at ogsaa de maatte faae Barmhjertighed.","saaledes ere og disse nu blevne ulydige ved den Barmhjertighed som Eder er vederfaren, at ogsaa de maatte faae Barmhjertighed."],[11,32,"Thi Gud haver indesluttet Alle under Ulydighed, at han kunde forbarme sig over Alle.","Thi Gud haver indesluttet Alle under Ulydighed, at han kunde forbarme sig over Alle."],[11,33,"O Rigdoms Dyb, baade paa Guds Viisdom og Kundskab! hvor uransagelige ere hans Domme, og hans Veie usporlige!","O Rigdoms Dyb, baade paa Guds Viisdom og Kundskab! hvor uransagelige ere hans Domme, og hans Veie usporlige!"],[11,34,"Thi hvo haver kjendt Herrens Sind? eller hvo var hans Raadgiver!","Thi hvo haver kjendt Herrens Sind? eller hvo var hans Raadgiver!"],[11,35,"eller hvo gav ham først, at det igjen skulde betales ham?","eller hvo gav ham først, at det igjen skulde betales ham?"],[11,36,"Thi af ham og ved ham og til ham ere alle Ting; ham være Ære i Evighed! Amen.","Thi af ham og ved ham og til ham ere alle Ting; ham være Ære i Evighed! Amen."],[12,1,"Desaarsag formaner jeg Eder, Brødre! ved Guds Barmhjertighed, at I fremstille Eders Legemer som et levende, helligt, Gud velbehageligt Offer, hvilket er Eders fornuftige Gudsdyrkelse.","Desaarsag formaner jeg Eder, Brødre! ved Guds Barmhjertighed, at I fremstille Eders Legemer som et levende, helligt, Gud velbehageligt Offer, hvilket er Eders fornuftige Gudsdyrkelse."],[12,2,"Og skikke Eder ikke lige med denne Verden, men vorder forvandlede ved Eders Sinds Fornyelse, at I maa skjønne, hvad der er Guds gode og velbehagelige og fuldkomne Villie.","Og skikke Eder ikke lige med denne Verden, men vorder forvandlede ved Eders Sinds Fornyelse, at I maa skjønne, hvad der er Guds gode og velbehagelige og fuldkomne Villie."],[12,3,"Thi formedelst den Naade, som mig er given, siger jeg til enhver iblandt Eder, at han ikke skal tænke høiere om sig selv, end han bør at tænke, men tænke om sig selv med Betænksomhed, eftersom Gud tilmaalte Enhver Troens Gave.","Thi formedelst den Naade, som mig er given, siger jeg til enhver iblandt Eder, at han ikke skal tænke høiere om sig selv, end han bør at tænke, men tænke om sig selv med Betænksomhed, eftersom Gud tilmaalte Enhver Troens Gave."],[12,4,"Thi ligerviis som vi have mange Lemmer paa eet Legeme, men alle Lemmer have ikke den samme Gjerning;","Thi ligerviis som vi have mange Lemmer paa eet Legeme, men alle Lemmer have ikke den samme Gjerning;"],[12,5,"ligesaa ere vi mange eet Legeme i Christus, men hver for sig ere vi hverandres Lemmer.","ligesaa ere vi mange eet Legeme i Christus, men hver for sig ere vi hverandres Lemmer."],[12,6,"Men efterdi vi have adskillige Naadegaver efter den Naade, som er given os, enten vi have Prophetiens Gave , da lader os bruge den i Forhold til vor Tro;","Men efterdi vi have adskillige Naadegaver efter den Naade, som er given os, enten vi have Prophetiens Gave , da lader os bruge den i Forhold til vor Tro;"],[12,7,"eller vi have et Embede, da lader os tage vare paa Embedet; eller om nogen lærer, paa Lærdommen;","eller vi have et Embede, da lader os tage vare paa Embedet; eller om nogen lærer, paa Lærdommen;"],[12,8,"eller om Nogen formaner, paa Formanelsen; den, som uddeler , gjøre det med Redelighed; den, som er Forstander, være det med Iver; den, som gjør Barmhjertighed, gjøre det med Glæde.","eller om Nogen formaner, paa Formanelsen; den, som uddeler , gjøre det med Redelighed; den, som er Forstander, være det med Iver; den, som gjør Barmhjertighed, gjøre det med Glæde."],[12,9,"Kjærligheden være uden Skrømt; haver Afsky til det Onde, Hænder fast ved det Gode;","Kjærligheden være uden Skrømt; haver Afsky til det Onde, Hænder fast ved det Gode;"],[12,10,"værer hverandre inderligen hengivne i broderlig Kjærlighed; forekommer hverandre med Ærbødighed;","værer hverandre inderligen hengivne i broderlig Kjærlighed; forekommer hverandre med Ærbødighed;"],[12,11,"værer ikke lunkne i Eders Iver; værer brændende i Aanden; tjener Herren;","værer ikke lunkne i Eders Iver; værer brændende i Aanden; tjener Herren;"],[12,12,"værer glade i Haabet, taalmodige i Trængslen, varagtige i Bønnen,","værer glade i Haabet, taalmodige i Trængslen, varagtige i Bønnen,"],[12,13,"Antager Eder de Helliges Nødtørftighed; laaner gjerne Huus.","Antager Eder de Helliges Nødtørftighed; laaner gjerne Huus."],[12,14,"Velsigner dem, som Eder forfølge, velsigner, og forbander ikke.","Velsigner dem, som Eder forfølge, velsigner, og forbander ikke."],[12,15,"Glæder Eder med de Glade, og græder med de Grædende.","Glæder Eder med de Glade, og græder med de Grædende."],[12,16,"Haver eet Sind imod hverandre; tragter ikke efter høie Ting, men holder Eder til de lave; mener Eder selv ikke kloge.","Haver eet Sind imod hverandre; tragter ikke efter høie Ting, men holder Eder til de lave; mener Eder selv ikke kloge."],[12,17,"Betaler ikke Nogen Ondt for Godt; beflitter Eder paa hvad der er godt for alle Menneskers Aasyn.","Betaler ikke Nogen Ondt for Godt; beflitter Eder paa hvad der er godt for alle Menneskers Aasyn."],[12,18,"Dersom det er muligt, da haver Fred med alle Mennesker, saavidt det staaer til Eder.","Dersom det er muligt, da haver Fred med alle Mennesker, saavidt det staaer til Eder."],[12,19,"Hevner Eder ikke selv, I Elskelige, men giver Straffen Tid; thi der er skrevet: Hevnen hører mig til, jeg vil betale, siger Herren.","Hevner Eder ikke selv, I Elskelige, men giver Straffen Tid; thi der er skrevet: Hevnen hører mig til, jeg vil betale, siger Herren."],[12,20,"Dersom da din Fjende hungrer, giv ham Mad; dersom han tørster, giv ham Drikke; thi naar du det gjør, samler du gloende Kul paa hans Hoved.","Dersom da din Fjende hungrer, giv ham Mad; dersom han tørster, giv ham Drikke; thi naar du det gjør, samler du gloende Kul paa hans Hoved."],[12,21,"Lad dig ikke overvinde af det Onde, men overvind det Onde med det Gode.","Lad dig ikke overvinde af det Onde, men overvind det Onde med det Gode."],[13,1,"Hvert Menneske være de foresatte Øvrigheder underdanig; thi der er ikke Øvrighed uden af Gud, men de Øvrigheder, som ere, haver Gud beskikket,","Hvert Menneske være de foresatte Øvrigheder underdanig; thi der er ikke Øvrighed uden af Gud, men de Øvrigheder, som ere, haver Gud beskikket,"],[13,2,"saa at hvo som sætter sig imod Øvrigheden, imodstaaer Guds Anordning; men de, som modstaae, skulle faae deres Dom.","saa at hvo som sætter sig imod Øvrigheden, imodstaaer Guds Anordning; men de, som modstaae, skulle faae deres Dom."],[13,3,"Thi de Regjerende ere ikke til Skræk for gode Gjerninger, men for onde. Vil du da ikke frygte for Øvrigheden, saa gjør det, som godt er, og du skal have Roes af den.","Thi de Regjerende ere ikke til Skræk for gode Gjerninger, men for onde. Vil du da ikke frygte for Øvrigheden, saa gjør det, som godt er, og du skal have Roes af den."],[13,4,"Thi den er Guds Tjener, dig til Gode. Men dersom du gjør det, som er ondt, da frygt dig; thi den bærer ikke Sværdet forgjeves, den er Guds Tjener, en Hevner, til Straf over den, som gjør det Onde.","Thi den er Guds Tjener, dig til Gode. Men dersom du gjør det, som er ondt, da frygt dig; thi den bærer ikke Sværdet forgjeves, den er Guds Tjener, en Hevner, til Straf over den, som gjør det Onde."],[13,5,"Derfor er det fornødent at være underdanig, ikke alene for Straffens Skyld, men ogsaa for Samvittighedens.","Derfor er det fornødent at være underdanig, ikke alene for Straffens Skyld, men ogsaa for Samvittighedens."],[13,6,"Derfor betale I dem ogsaa Skat; thi de ere Guds Tjenere, som just skulle tage vare paa dette.","Derfor betale I dem ogsaa Skat; thi de ere Guds Tjenere, som just skulle tage vare paa dette."],[13,7,"Betaler derfor Alle, hvad I ere dem skyldige: den, som i ere Skat skyldige, Skat; den, som Told, Told; den, som Frygt, Frygt; den, som Ære, Ære.","Betaler derfor Alle, hvad I ere dem skyldige: den, som i ere Skat skyldige, Skat; den, som Told, Told; den, som Frygt, Frygt; den, som Ære, Ære."],[13,8,"Bliver Ingen Noget skyldige, uden dette, at elske hverandre; thi hvo som elsker den Anden, haver opfyldt Loven.","Bliver Ingen Noget skyldige, uden dette, at elske hverandre; thi hvo som elsker den Anden, haver opfyldt Loven."],[13,9,"Thi det: du skal ikke bedrive Hoer; du skal ikke ihjelslaae; du skal ikke stjæle; du skal ikke bære falsk Vidnesbyrd; du skal ikke begjere; og om der er noget andet Bud, det befattes som i en Hovedsum i dette Ord: du skal elske din Næste som dig selv.","Thi det: du skal ikke bedrive Hoer; du skal ikke ihjelslaae; du skal ikke stjæle; du skal ikke bære falsk Vidnesbyrd; du skal ikke begjere; og om der er noget andet Bud, det befattes som i en Hovedsum i dette Ord: du skal elske din Næste som dig selv."],[13,10,"Kjærligheden gjør Næsten ikke Ondt; derfor er Kjærligheden Lovens Fylde.","Kjærligheden gjør Næsten ikke Ondt; derfor er Kjærligheden Lovens Fylde."],[13,11,"Og dette desto mere i Betragtning af Tiden, da Stunden nu er der, at vi skulle opstaae af Søvne; thi vor Frelse er nu nærmere, end da vi bleve troende.","Og dette desto mere i Betragtning af Tiden, da Stunden nu er der, at vi skulle opstaae af Søvne; thi vor Frelse er nu nærmere, end da vi bleve troende."],[13,12,"Natten er fremrykket, og Dagen er kommen nær. Derfor lader os aflægge Mørkets Gjerninger og iføre Lysets Vaaben;","Natten er fremrykket, og Dagen er kommen nær. Derfor lader os aflægge Mørkets Gjerninger og iføre Lysets Vaaben;"],[13,13,"lader os vandre skikkeligen som om Dagen, ikke i Fraadseri og Drukkenskab, ikke i Løsagtighed og Uteerlighed, ikke i Kiv og Avind;","lader os vandre skikkeligen som om Dagen, ikke i Fraadseri og Drukkenskab, ikke i Løsagtighed og Uteerlighed, ikke i Kiv og Avind;"],[13,14,"men ifører den Herre Jesus Christus, og pleier ikke Kjødet til at vække Begjerlighed.","men ifører den Herre Jesus Christus, og pleier ikke Kjødet til at vække Begjerlighed."],[14,1,"Antager Eder den, som er skrøbelig i Troen, og dømmer ikke hans Meninger.","Antager Eder den, som er skrøbelig i Troen, og dømmer ikke hans Meninger."],[14,2,"En troer, at man tør æde alt; men den Skrøbelige æder kun Urter.","En troer, at man tør æde alt; men den Skrøbelige æder kun Urter."],[14,3,"Hvo som æder, foragte ikke den, som ikke æder; og hvo som ikke æder, dømme ikke den, som æder; thi Gud haver antaget ham.","Hvo som æder, foragte ikke den, som ikke æder; og hvo som ikke æder, dømme ikke den, som æder; thi Gud haver antaget ham."],[14,4,"Hvo er du, som dømmer en fremmed Svend? For sin egen Herre staaer eller falder han; men han skal blive staaende, thi Gud er mægtig til at holde ham.","Hvo er du, som dømmer en fremmed Svend? For sin egen Herre staaer eller falder han; men han skal blive staaende, thi Gud er mægtig til at holde ham."],[14,5,"En agter den ene Dag fremfor den anden, en Anden agter alle Dage lige; hver have fuld Vished i sit eget Sind.","En agter den ene Dag fremfor den anden, en Anden agter alle Dage lige; hver have fuld Vished i sit eget Sind."],[14,6,"Hvo som gjør sig Mening om Dage, han gjør det for Herren; og hvo som ikke gjør sig Mening om Dage, han gjør det ogsaa for Herren. Hvo som æder gjør det for Herren, thi han takker Gud; og hvo som ikke æder, gjør det ogsaa for Herren, og takker Gud.","Hvo som gjør sig Mening om Dage, han gjør det for Herren; og hvo som ikke gjør sig Mening om Dage, han gjør det ogsaa for Herren. Hvo som æder gjør det for Herren, thi han takker Gud; og hvo som ikke æder, gjør det ogsaa for Herren, og takker Gud."],[14,7,"Thi Ingen af os lever sig selv, og Ingen døer sig selv;","Thi Ingen af os lever sig selv, og Ingen døer sig selv;"],[14,8,"thi baade dersom vi leve, leve vi Herren, og dersom vi døe, døe vi Herren; derfor enten vi leve, eller vi døe, ere vi Herrens.","thi baade dersom vi leve, leve vi Herren, og dersom vi døe, døe vi Herren; derfor enten vi leve, eller vi døe, ere vi Herrens."],[14,9,"Dertil er jo Christus baade død og opstanden og bleven levende igjen, at han skal herske baade over Døde og Levende.","Dertil er jo Christus baade død og opstanden og bleven levende igjen, at han skal herske baade over Døde og Levende."],[14,10,"Du altsaa, hvi dømmer du din Broder? eller du, hvi foragter du din Broder? Vi skulle jo alle fremstilles for Christi Domstol.","Du altsaa, hvi dømmer du din Broder? eller du, hvi foragter du din Broder? Vi skulle jo alle fremstilles for Christi Domstol."],[14,11,"Thi der er skrevet: saa sandt jeg lever, siger Herren, skal hvert Knæ bøies for mig, og hver Tunge skal bekjende Gud.","Thi der er skrevet: saa sandt jeg lever, siger Herren, skal hvert Knæ bøies for mig, og hver Tunge skal bekjende Gud."],[14,12,"Altsaa skal hver af os gjøre Gud Regnskab for sig selv.","Altsaa skal hver af os gjøre Gud Regnskab for sig selv."],[14,13,"Derfor lader os ikke mere dømme hverandre, men dømmer hellere dette, ikke at sætte Anstød eller Forargelse for en Broder.","Derfor lader os ikke mere dømme hverandre, men dømmer hellere dette, ikke at sætte Anstød eller Forargelse for en Broder."],[14,14,"Jeg veed og er vis paa i den Herre Jesus, at Intet er ureent i sig selv; dog for den, som agter Noget for ureent, ham er det ureent.","Jeg veed og er vis paa i den Herre Jesus, at Intet er ureent i sig selv; dog for den, som agter Noget for ureent, ham er det ureent."],[14,15,"Men dersom din Broder bedrøves for Mads Skyld, da omgaaes du ikke mere efter Kjærlighed. Led ikke ved din mad den i Fordærvelse, for hvis Skyld Christus er død.","Men dersom din Broder bedrøves for Mads Skyld, da omgaaes du ikke mere efter Kjærlighed. Led ikke ved din mad den i Fordærvelse, for hvis Skyld Christus er død."],[14,16,"Lader derfor Eders Gode ikke blive bespottet.","Lader derfor Eders Gode ikke blive bespottet."],[14,17,"Thi Guds Rige er ikke Mad og Drikke, men Retfærdighed og Fred og Glæde i den Hellig Aand.","Thi Guds Rige er ikke Mad og Drikke, men Retfærdighed og Fred og Glæde i den Hellig Aand."],[14,18,"Hvo som derudi tjener Christus, er velbehagelig for Gud og tækkelig for Menneskene.","Hvo som derudi tjener Christus, er velbehagelig for Gud og tækkelig for Menneskene."],[14,19,"Derfor lader os tragte efter det som tjener til Fred og indbyrdes Opbyggelse.","Derfor lader os tragte efter det som tjener til Fred og indbyrdes Opbyggelse."],[14,20,"Nedbryd ikke Guds Værk for Mads Skyld. Vel er Alt reent, men det er ondt for det Menneske, som æder med Anstød.","Nedbryd ikke Guds Værk for Mads Skyld. Vel er Alt reent, men det er ondt for det Menneske, som æder med Anstød."],[14,21,"Det er godt, ikke at æde Kjød eller at drikke Viin eller at gjøre Noget, som støder din Broder, forarger eller ængster ham.","Det er godt, ikke at æde Kjød eller at drikke Viin eller at gjøre Noget, som støder din Broder, forarger eller ængster ham."],[14,22,"Du haver Tro ; hav den hos dig selv for Gud. Salig er den, som ikke maa dømme sig selv i det, han vælger.","Du haver Tro ; hav den hos dig selv for Gud. Salig er den, som ikke maa dømme sig selv i det, han vælger."],[14,23,"Men hvo som tvivler og dog æder, han er skyldig, fordi det ikke er af Tro; men alt det, som ikke er af Tro, er Synd.","Men hvo som tvivler og dog æder, han er skyldig, fordi det ikke er af Tro; men alt det, som ikke er af Tro, er Synd."],[15,1,"Vi, som ere stærke, bør da bære over med de Svages Skrøbeligheder og ikke behage os selv.","Vi, som ere stærke, bør da bære over med de Svages Skrøbeligheder og ikke behage os selv."],[15,2,"Hver af os være sin Næste til Behag i det Gode til Opbyggelse.","Hver af os være sin Næste til Behag i det Gode til Opbyggelse."],[15,3,"Thi ogsaa Christus levede ikke sig selv til Behag; men som skrevet staaer: deres Forhaanelser, som dig forhaane, ere faldne paa mig.","Thi ogsaa Christus levede ikke sig selv til Behag; men som skrevet staaer: deres Forhaanelser, som dig forhaane, ere faldne paa mig."],[15,4,"Thi hvadsomhelst tilforn er skrevet, det er skrevet os til Lærdom, paa det vi skulle have Haab ved Taalmodighed og Skriftens Trøst.","Thi hvadsomhelst tilforn er skrevet, det er skrevet os til Lærdom, paa det vi skulle have Haab ved Taalmodighed og Skriftens Trøst."],[15,5,"Men Taalmodighedens og Trøstens Gud giver Eder at have eet Sind indbyrdes efter Christus Jesus,","Men Taalmodighedens og Trøstens Gud giver Eder at have eet Sind indbyrdes efter Christus Jesus,"],[15,6,"at I eendrægteligen med een Mund kunne prise Gud og vor Herres Jesu Christi Fader.","at I eendrægteligen med een Mund kunne prise Gud og vor Herres Jesu Christi Fader."],[15,7,"Derfor antager Eder hverandre, ligesom Christus haver antaget sig os, til Guds Ære.","Derfor antager Eder hverandre, ligesom Christus haver antaget sig os, til Guds Ære."],[15,8,"Jeg siger nemlig, at Jesus Christus er bleven Omskærelsens Tjener for Guds Sanddruheds Skyld til at stadfæste Forjættelserne til Fædrene;","Jeg siger nemlig, at Jesus Christus er bleven Omskærelsens Tjener for Guds Sanddruheds Skyld til at stadfæste Forjættelserne til Fædrene;"],[15,9,"men at Hedningerne skulle prise Gud for hans Barmhjertigheds Skyld, som skrevet er: derfor vil jeg bekjende dig iblandt Hedningerne og lovsynge dit Navn.","men at Hedningerne skulle prise Gud for hans Barmhjertigheds Skyld, som skrevet er: derfor vil jeg bekjende dig iblandt Hedningerne og lovsynge dit Navn."],[15,10,"Og atter siges der: fryder Eder, I Hedninger, med hans Folk!","Og atter siges der: fryder Eder, I Hedninger, med hans Folk!"],[15,11,"Og atter: lover Herren, alle Hedninger, og priser ham, alle Folk!","Og atter: lover Herren, alle Hedninger, og priser ham, alle Folk!"],[15,12,"Og atter siger Esaias: der skal være en Rod af Jessai, og den, som opstaaer at regjere over Hedningerne, paa ham skulle Hedningerne haabe.","Og atter siger Esaias: der skal være en Rod af Jessai, og den, som opstaaer at regjere over Hedningerne, paa ham skulle Hedningerne haabe."],[15,13,"Men Haabets Gud fylde Eder med al Glæde og Fred, idet I troe, at I kunne vorde rige i Haabet ved den Hellig Aands Kraft.","Men Haabets Gud fylde Eder med al Glæde og Fred, idet I troe, at I kunne vorde rige i Haabet ved den Hellig Aands Kraft."],[15,14,"Iøvrigt, mine Brødre! er jeg og selv forvisset om Eder, at ogsaa i ere fulde af Godhed, rige paa al Kundskab, istand til at paaminde hverandre.","Iøvrigt, mine Brødre! er jeg og selv forvisset om Eder, at ogsaa i ere fulde af Godhed, rige paa al Kundskab, istand til at paaminde hverandre."],[15,15,"Dog har jeg for en Deel tilskrevet Eder, mine Brødre! noget dristigere for at paaminde Eder, efter den Naade, som mig er given af Gud,","Dog har jeg for en Deel tilskrevet Eder, mine Brødre! noget dristigere for at paaminde Eder, efter den Naade, som mig er given af Gud,"],[15,16,"at være Jesu Christi Tjener iblandt Hedningerne, at betjene Guds Evangelium, paa det Hedningernes Offer maa blive velbehageligt, helliget formedelst den Hellig Aand.","at være Jesu Christi Tjener iblandt Hedningerne, at betjene Guds Evangelium, paa det Hedningernes Offer maa blive velbehageligt, helliget formedelst den Hellig Aand."],[15,17,"Saaledes haver jeg Roes i Christus Jesus i min Tjeneste for Gud.","Saaledes haver jeg Roes i Christus Jesus i min Tjeneste for Gud."],[15,18,"Thi jeg vil ikke fordriste mig til at tale Noget om det, som Christus ikke haver udrettet ved mig til Hedningernes Lydighed , ved Ord og Handling,","Thi jeg vil ikke fordriste mig til at tale Noget om det, som Christus ikke haver udrettet ved mig til Hedningernes Lydighed , ved Ord og Handling,"],[15,19,"ved Tegns og Undergjerningers Kraft, ved Guds Aands Kraft; saa at jeg fra Jerusalem og trindt omkring indtil Illyrien haver tilfulde forkyndt Christi Evangelium;","ved Tegns og Undergjerningers Kraft, ved Guds Aands Kraft; saa at jeg fra Jerusalem og trindt omkring indtil Illyrien haver tilfulde forkyndt Christi Evangelium;"],[15,20,"dog saaledes, at jeg havde synderlig Villie til at prædike Evangelium, ikke der, hvor Christus var nævnet, at jeg ikke skulde bygge paa en fremmed Grundvold,","dog saaledes, at jeg havde synderlig Villie til at prædike Evangelium, ikke der, hvor Christus var nævnet, at jeg ikke skulde bygge paa en fremmed Grundvold,"],[15,21,"men, som skrevet staaer: de, for hvilke Intet var kundgjort om ham, skulle see, og de, som ikke havde hørt, skulle forstaae.","men, som skrevet staaer: de, for hvilke Intet var kundgjort om ham, skulle see, og de, som ikke havde hørt, skulle forstaae."],[15,22,"Derved er jeg og mange Gange bleven forhindret i at komme til Eder.","Derved er jeg og mange Gange bleven forhindret i at komme til Eder."],[15,23,"Men nu, da jeg ikke mere haver Rum i disse Lande, og fra mange Aar af haver Længsel efter at komme til Eder,","Men nu, da jeg ikke mere haver Rum i disse Lande, og fra mange Aar af haver Længsel efter at komme til Eder,"],[15,24,"vil jeg, naar jeg reiser til Spanien, komme til Eder; thi jeg haaber at see Eder, naar jeg reiser igjennem, og af Eder at blive ledsaget derhen, naar jeg først i nogen Maade er bleven tilfredsstillet hos Eder.","vil jeg, naar jeg reiser til Spanien, komme til Eder; thi jeg haaber at see Eder, naar jeg reiser igjennem, og af Eder at blive ledsaget derhen, naar jeg først i nogen Maade er bleven tilfredsstillet hos Eder."],[15,25,"Men nu reiser jeg til Jerusalem for at tjene de Hellige.","Men nu reiser jeg til Jerusalem for at tjene de Hellige."],[15,26,"Thi Macedonien og Achaia have anseet for godt, at gjøre et Sammenskud til de Fattige iblandt de Hellige i Jerusalem.","Thi Macedonien og Achaia have anseet for godt, at gjøre et Sammenskud til de Fattige iblandt de Hellige i Jerusalem."],[15,27,"De ansaae det for godt, og ere ogsaa deres Skyldnere. Thi ere Hedningerne blevne deelagtige i hines aandelige Fordele, da ere de og skyldige at tjene dem i det Timelige.","De ansaae det for godt, og ere ogsaa deres Skyldnere. Thi ere Hedningerne blevne deelagtige i hines aandelige Fordele, da ere de og skyldige at tjene dem i det Timelige."],[15,28,"Naar jeg da haver fuldbragt dette og forsikkret dem denne Frugt, vil jeg derfra drage igjennem Eders Stad til Spanien.","Naar jeg da haver fuldbragt dette og forsikkret dem denne Frugt, vil jeg derfra drage igjennem Eders Stad til Spanien."],[15,29,"Men jeg veed, at naar jeg kommer til Eder, skal jeg komme med Christi Evangeliums Velsignelses Fylde.","Men jeg veed, at naar jeg kommer til Eder, skal jeg komme med Christi Evangeliums Velsignelses Fylde."],[15,30,"Men jeg formaner Eder, Brødre! ved vor Herre Jesus Christus og ved Aandens Kjærlighed, og I ville med mig stride i Bøn for mig til Gud,","Men jeg formaner Eder, Brødre! ved vor Herre Jesus Christus og ved Aandens Kjærlighed, og I ville med mig stride i Bøn for mig til Gud,"],[15,31,"at jeg maa udfries fra de Vantroe i Judæa, og at mit Ærinde til Jerusalem maa blive de Hellige behageligt,","at jeg maa udfries fra de Vantroe i Judæa, og at mit Ærinde til Jerusalem maa blive de Hellige behageligt,"],[15,32,"paa det jeg kan komme til Eder med Glæde, efter Guds Villie, og vederkvæges med Eder.","paa det jeg kan komme til Eder med Glæde, efter Guds Villie, og vederkvæges med Eder."],[15,33,"Fredens Gud være med Eder alle! Amen.","Fredens Gud være med Eder alle! Amen."],[16,1,"Jeg, befaler Eder Phoebe, vor Søster, Tjenerinde ved Menigheden i Kenchreæ,","Jeg, befaler Eder Phoebe, vor Søster, Tjenerinde ved Menigheden i Kenchreæ,"],[16,2,"at I antage hende i Herren, som det sømmer de Hellige, og gjøre hende Bistand i hvadsomhelst hun maatte have Eder behov; thi hun haver og gjort Mange Bistand, ja ogsaa mig selv.","at I antage hende i Herren, som det sømmer de Hellige, og gjøre hende Bistand i hvadsomhelst hun maatte have Eder behov; thi hun haver og gjort Mange Bistand, ja ogsaa mig selv."],[16,3,"Hilser Priscilla og Aqvilas, mine Medarbeidere i Christus Jesus,","Hilser Priscilla og Aqvilas, mine Medarbeidere i Christus Jesus,"],[16,4,"hvilke for mit Liv have vovet deres eget, hvem ikke jeg alene takker, men og alle Hedningernes Menigheder;","hvilke for mit Liv have vovet deres eget, hvem ikke jeg alene takker, men og alle Hedningernes Menigheder;"],[16,5,"og hilser Menigheden i deres Huus. Hilser Epænetus, den Elskelige, Achaias Førstegrøde i Christus.","og hilser Menigheden i deres Huus. Hilser Epænetus, den Elskelige, Achaias Førstegrøde i Christus."],[16,6,"Hilser Maria, som haver arbeidet meget for os.","Hilser Maria, som haver arbeidet meget for os."],[16,7,"Hilser Andronicus og Junias, mine Frænder og mine Medfangne, som ere mærkelige iblandt Apostlerne, og have, før jeg, været i Christus.","Hilser Andronicus og Junias, mine Frænder og mine Medfangne, som ere mærkelige iblandt Apostlerne, og have, før jeg, været i Christus."],[16,8,"Hilser Amplias, min Elskelige i Herren.","Hilser Amplias, min Elskelige i Herren."],[16,9,"Hilser Urbanus, vor Medarbeider i Christus, og Stachys, min Elskelige.","Hilser Urbanus, vor Medarbeider i Christus, og Stachys, min Elskelige."],[16,10,"Hilser Apelles, den Prøvede i Christus. Hilser dem, som ere af Aristobulus’ Huus.","Hilser Apelles, den Prøvede i Christus. Hilser dem, som ere af Aristobulus’ Huus."],[16,11,"Hilser Herodion min, Frænde. Hilser dem af Narcissus’ Huus, som ere i Herren.","Hilser Herodion min, Frænde. Hilser dem af Narcissus’ Huus, som ere i Herren."],[16,12,"Hilser Tryphena og Tryphosa, som have arbeidet i Herren. Hilser Persis, den Elskelige, som haver arbeidet meget i Herren.","Hilser Tryphena og Tryphosa, som have arbeidet i Herren. Hilser Persis, den Elskelige, som haver arbeidet meget i Herren."],[16,13,"Hilser Rufus, den Udvalgte i Herren, og hans og min Moder.","Hilser Rufus, den Udvalgte i Herren, og hans og min Moder."],[16,14,"Hilser Asyncritus, Phlegon, Hermas, Patrobas, Hermes og Brødrene hos dem.","Hilser Asyncritus, Phlegon, Hermas, Patrobas, Hermes og Brødrene hos dem."],[16,15,"Hilser Philologus og Julias, Nereus og hans Søster, og Olympa, og alle de Hellige hos dem.","Hilser Philologus og Julias, Nereus og hans Søster, og Olympa, og alle de Hellige hos dem."],[16,16,"Hilser hverandre med et helligt Kys. Christi Menigheder hilse Eder.","Hilser hverandre med et helligt Kys. Christi Menigheder hilse Eder."],[16,17,"End formaner jeg Eder, Brødre! at I give Agt paa dem, som volde Splid og Forargelser, tvertimod den Lærdom, som I have lært, og viger af fra dem.","End formaner jeg Eder, Brødre! at I give Agt paa dem, som volde Splid og Forargelser, tvertimod den Lærdom, som I have lært, og viger af fra dem."],[16,18,"Thi Saadanne tjene ikke vor Herre Jesus Christus, men deres egen Bug, og ved søde Ord og smigrende Taler forføre de de Eenfoldiges Hjerter.","Thi Saadanne tjene ikke vor Herre Jesus Christus, men deres egen Bug, og ved søde Ord og smigrende Taler forføre de de Eenfoldiges Hjerter."],[16,19,"Eders Lydighed er bleven Alle bekjendt, derfor glæder jeg mig over Eder. Men jeg vil, at I skulle være vise til det Gode, og eenfoldige til det Onde.","Eders Lydighed er bleven Alle bekjendt, derfor glæder jeg mig over Eder. Men jeg vil, at I skulle være vise til det Gode, og eenfoldige til det Onde."],[16,20,"Men Fredens Gud skal snart knuse Satanas under Eders Fødder. Vor Herres Jesu Christi Naade være med Eder! Amen.","Men Fredens Gud skal snart knuse Satanas under Eders Fødder. Vor Herres Jesu Christi Naade være med Eder! Amen."],[16,21,"Timotheus, min Medarbeider, og Lucius og Jason og Sosipater, mine Frænder, hilse Eder.","Timotheus, min Medarbeider, og Lucius og Jason og Sosipater, mine Frænder, hilse Eder."],[16,22,"Jeg, Tertius, som har skrevet dette Brev, hilser Eder i Herren.","Jeg, Tertius, som har skrevet dette Brev, hilser Eder i Herren."],[16,23,"Cajus, min og den hele Menigheds Vært, hilser Eder. Crastus, Stadens Rentemester, hilser Eder, og Broderen Qvartus.","Cajus, min og den hele Menigheds Vært, hilser Eder. Crastus, Stadens Rentemester, hilser Eder, og Broderen Qvartus."],[16,24,"Vor Herres Jesu Christi Naade være med Eder alle! Amen.","Vor Herres Jesu Christi Naade være med Eder alle! Amen."],[16,25,"Men ham, som er mægtig til at styrke Eder efter mit Evangelium og Jesu Christi Prædiken, efter Aabenbaringen af den Hemmelighed, som var fortiet fra evige Tider,","Men ham, som er mægtig til at styrke Eder efter mit Evangelium og Jesu Christi Prædiken, efter Aabenbaringen af den Hemmelighed, som var fortiet fra evige Tider,"],[16,26,"men nu er aabenbaret og, ifølge de prophetiske Skrifter, efter den evige Guds Befaling, er kundgjort for alle Hedninger til Troens Lydighed:","men nu er aabenbaret og, ifølge de prophetiske Skrifter, efter den evige Guds Befaling, er kundgjort for alle Hedninger til Troens Lydighed:"],[16,27,"ham, den ene vise Gud, være Ære ved Jesus Christus i al Evighed! Amen.","ham, den ene vise Gud, være Ære ved Jesus Christus i al Evighed! Amen."]],"epo-londona":[[1,1,"Paŭlo, servisto de Jesuo Kristo, apostolo vokita, apartigita al la evangelio de Dio,","Paŭlo, servisto de Jesuo Kristo, apostolo vokita, apartigita al la evangelio de Dio,"],[1,2,"kiun Li promesis antaŭe per Siaj profetoj en la sanktaj skriboj,","kiun Li promesis antaŭe per Siaj profetoj en la sanktaj skriboj,"],[1,3,"pri Sia Filo, kiu naskiĝis el la idaro de David laŭ la karno,","pri Sia Filo, kiu naskiĝis el la idaro de David laŭ la karno,"],[1,4,"la difinita Filo de Dio en potenco laŭ la Spirito de sankteco per la releviĝo de la mortintoj — Jesuo Kristo, nia Sinjoro,","la difinita Filo de Dio en potenco laŭ la Spirito de sankteco per la releviĝo de la mortintoj — Jesuo Kristo, nia Sinjoro,"],[1,5,"per kiu ni ricevis gracon kaj apostolecon por obeemo de fido ĉe ĉiuj nacioj pro lia nomo,","per kiu ni ricevis gracon kaj apostolecon por obeemo de fido ĉe ĉiuj nacioj pro lia nomo,"],[1,6,"inter kiuj estas ankaŭ vi, vokitaj de Jesuo Kristo;","inter kiuj estas ankaŭ vi, vokitaj de Jesuo Kristo;"],[1,7,"al ĉiuj, kiuj estas en Romo, amataj de Dio, vokitaj sanktuloj: Graco al vi kaj paco de Dio, nia Patro, kaj de la Sinjoro Jesuo Kristo.","al ĉiuj, kiuj estas en Romo, amataj de Dio, vokitaj sanktuloj: Graco al vi kaj paco de Dio, nia Patro, kaj de la Sinjoro Jesuo Kristo."],[1,8,"Unue mi dankas al mia Dio per Jesuo Kristo por vi ĉiuj, ke via fido estas proklamata tra la tuta mondo.","Unue mi dankas al mia Dio per Jesuo Kristo por vi ĉiuj, ke via fido estas proklamata tra la tuta mondo."],[1,9,"Ĉar mia atestanto estas Dio, kiun mi servas en mia spirito en la evangelio de Lia Filo, ke mi senĉese memorigas pri vi en miaj preĝoj,","Ĉar mia atestanto estas Dio, kiun mi servas en mia spirito en la evangelio de Lia Filo, ke mi senĉese memorigas pri vi en miaj preĝoj,"],[1,10,"ĉiam petante, ke iel al mi jam fine prosperos veni al vi per la volo de Dio.","ĉiam petante, ke iel al mi jam fine prosperos veni al vi per la volo de Dio."],[1,11,"Ĉar mi sopiras vin vidi, por ke mi transdonu al vi ian spiritan donacon, por ke vi estu firmigitaj;","Ĉar mi sopiras vin vidi, por ke mi transdonu al vi ian spiritan donacon, por ke vi estu firmigitaj;"],[1,12,"tio estas, por ke estu inter ni reciproka kuraĝigo, per la komuna fido, egale via kaj mia.","tio estas, por ke estu inter ni reciproka kuraĝigo, per la komuna fido, egale via kaj mia."],[1,13,"Kaj mi ne volas, ke vi nesciu, fratoj, ke ofte mi celis veni al vi (sed mi estas malhelpita ĝis nun), por ke mi havu iom da frukto ĉe vi, kiel ankaŭ ĉe la aliaj nacioj.","Kaj mi ne volas, ke vi nesciu, fratoj, ke ofte mi celis veni al vi (sed mi estas malhelpita ĝis nun), por ke mi havu iom da frukto ĉe vi, kiel ankaŭ ĉe la aliaj nacioj."],[1,14,"Mi estas ŝuldanto al Grekoj kaj al Barbaroj, al saĝuloj kaj al senprudentuloj.","Mi estas ŝuldanto al Grekoj kaj al Barbaroj, al saĝuloj kaj al senprudentuloj."],[1,15,"Tial laŭ mia eblo mi estas fervora prediki la evangelion ankaŭ al vi, kiuj estas en Romo.","Tial laŭ mia eblo mi estas fervora prediki la evangelion ankaŭ al vi, kiuj estas en Romo."],[1,16,"Ĉar mi ne hontas pri la evangelio; ĉar ĝi estas la potenco de Dio al savo por ĉiu, kiu kredas, al la Judoj unue, kaj ankaŭ al la Grekoj.","Ĉar mi ne hontas pri la evangelio; ĉar ĝi estas la potenco de Dio al savo por ĉiu, kiu kredas, al la Judoj unue, kaj ankaŭ al la Grekoj."],[1,17,"Ĉar la justeco de Dio malkaŝiĝas en ĝi de fido al fido, kiel estas skribite: La virtulo vivos per sia fideleco.","Ĉar la justeco de Dio malkaŝiĝas en ĝi de fido al fido, kiel estas skribite: La virtulo vivos per sia fideleco."],[1,18,"Ĉar la kolero de Dio malkaŝiĝas el la ĉielo kontraŭ ĉia malpieco kaj maljusteco de homoj, kiuj tenas la veron en maljusteco;","Ĉar la kolero de Dio malkaŝiĝas el la ĉielo kontraŭ ĉia malpieco kaj maljusteco de homoj, kiuj tenas la veron en maljusteco;"],[1,19,"ĉar la scio pri Dio estas elmontrita ĉe ili, ĉar Dio elmontris ĝin al ili.","ĉar la scio pri Dio estas elmontrita ĉe ili, ĉar Dio elmontris ĝin al ili."],[1,20,"Ĉar Liaj nevideblaj ecoj de post la kreado de la mondo fariĝas videblaj, sentate per Liaj faritaĵoj, nome, Lia eterna potenco kaj dieco; tial al ili mankas defenda pledo;","Ĉar Liaj nevideblaj ecoj de post la kreado de la mondo fariĝas videblaj, sentate per Liaj faritaĵoj, nome, Lia eterna potenco kaj dieco; tial al ili mankas defenda pledo;"],[1,21,"ĉar konante Dion, ili ne gloris Lin kiel Dion, nek estis dankemaj, sed vaniĝis per diskutadoj, kaj ilia sensaĝa koro mallumiĝis.","ĉar konante Dion, ili ne gloris Lin kiel Dion, nek estis dankemaj, sed vaniĝis per diskutadoj, kaj ilia sensaĝa koro mallumiĝis."],[1,22,"Pretendante esti saĝaj, ili malsaĝiĝis,","Pretendante esti saĝaj, ili malsaĝiĝis,"],[1,23,"kaj ŝanĝis la gloron de la senmorta Dio en bildon de morta homo kaj de birdoj kaj kvarpiedaj bestoj kaj rampaĵoj.","kaj ŝanĝis la gloron de la senmorta Dio en bildon de morta homo kaj de birdoj kaj kvarpiedaj bestoj kaj rampaĵoj."],[1,24,"Tial Dio fordonis ilin al la voluptoj de iliaj koroj, al malpureco, por ke iliaj korpoj malhonoriĝu inter ili mem;","Tial Dio fordonis ilin al la voluptoj de iliaj koroj, al malpureco, por ke iliaj korpoj malhonoriĝu inter ili mem;"],[1,25,"kiuj ŝanĝis la veron de Dio en mensogon, kaj adoris kaj servis la kreitaĵojn prefere ol la Kreinton, kiu estas eterne benata. Amen.","kiuj ŝanĝis la veron de Dio en mensogon, kaj adoris kaj servis la kreitaĵojn prefere ol la Kreinton, kiu estas eterne benata. Amen."],[1,26,"Tial Dio fordonis ilin al malhonoraj pasioj; ĉar iliaj virinoj ŝanĝis la naturan uzadon en kontraŭnaturan;","Tial Dio fordonis ilin al malhonoraj pasioj; ĉar iliaj virinoj ŝanĝis la naturan uzadon en kontraŭnaturan;"],[1,27,"kaj tiel same ankaŭ la viroj, forlasante la naturan uzadon de la virino, brulis en sia volupto unu al alia, kaj viroj kun viroj faris hontindaĵon kaj ricevis en si mem la taŭgan rekompencon de sia malvirto.","kaj tiel same ankaŭ la viroj, forlasante la naturan uzadon de la virino, brulis en sia volupto unu al alia, kaj viroj kun viroj faris hontindaĵon kaj ricevis en si mem la taŭgan rekompencon de sia malvirto."],[1,28,"Kaj ĉar ili malŝatis teni Dion en sia konado, Dio fordonis ilin al malaprobinda menso, por ke ili faru nedecaĵojn;","Kaj ĉar ili malŝatis teni Dion en sia konado, Dio fordonis ilin al malaprobinda menso, por ke ili faru nedecaĵojn;"],[1,29,"plenigite de ĉia maljusteco, malvirteco, avideco, malboneco; plenaj de envio, mortigo, malpaco, ruzo, malico; flustrantaj,","plenigite de ĉia maljusteco, malvirteco, avideco, malboneco; plenaj de envio, mortigo, malpaco, ruzo, malico; flustrantaj,"],[1,30,"kalumniantaj, Dimalamantaj, insultantaj, arogantaj, fanfaronemaj, elpensantaj malbonaĵojn, malobeemaj al gepatroj,","kalumniantaj, Dimalamantaj, insultantaj, arogantaj, fanfaronemaj, elpensantaj malbonaĵojn, malobeemaj al gepatroj,"],[1,31,"senprudentaj, nefidindaj, neparencamaj, senkompataj;","senprudentaj, nefidindaj, neparencamaj, senkompataj;"],[1,32,"kiuj, sciante pri la juĝo de Dio, ke la farantoj de tiaj agoj meritas morton, ne nur mem faras ilin, sed ankaŭ konsentas al la farantoj de ili.","kiuj, sciante pri la juĝo de Dio, ke la farantoj de tiaj agoj meritas morton, ne nur mem faras ilin, sed ankaŭ konsentas al la farantoj de ili."],[2,1,"Sekve, vi estas nedefendebla, ho ĉiu homo juĝanta; ĉar dum vi juĝas alian, vi kondamnas vin mem, ĉar vi, la juĝanto, faradas la samajn agojn.","Sekve, vi estas nedefendebla, ho ĉiu homo juĝanta; ĉar dum vi juĝas alian, vi kondamnas vin mem, ĉar vi, la juĝanto, faradas la samajn agojn."],[2,2,"Kaj ni scias, ke la juĝo de Dio estas laŭ vero kontraŭ tiuj, kiuj faradas tiajn agojn.","Kaj ni scias, ke la juĝo de Dio estas laŭ vero kontraŭ tiuj, kiuj faradas tiajn agojn."],[2,3,"Kaj ĉu vi kalkulas, ho homo, kiu juĝas la farantojn de tiaj agoj kaj faras la samajn, ke vi evitos la juĝon de Dio?","Kaj ĉu vi kalkulas, ho homo, kiu juĝas la farantojn de tiaj agoj kaj faras la samajn, ke vi evitos la juĝon de Dio?"],[2,4,"Aŭ ĉu vi malestimas la riĉecon de Lia boneco kaj toleremeco kaj pacienco, ne sciante, ke la boneco de Dio alkondukas vin al pento?","Aŭ ĉu vi malestimas la riĉecon de Lia boneco kaj toleremeco kaj pacienco, ne sciante, ke la boneco de Dio alkondukas vin al pento?"],[2,5,"sed laŭ via obstineco kaj senpenta koro vi amasigas por vi koleron en la tago de kolero kaj malkaŝigo de la justa juĝo de Dio,","sed laŭ via obstineco kaj senpenta koro vi amasigas por vi koleron en la tago de kolero kaj malkaŝigo de la justa juĝo de Dio,"],[2,6,"kiu redonos al ĉiu homo laŭ liaj faroj;","kiu redonos al ĉiu homo laŭ liaj faroj;"],[2,7,"al tiuj, kiuj per pacienco en bonfarado celas al gloro kaj honoro kaj senmorteco, eternan vivon;","al tiuj, kiuj per pacienco en bonfarado celas al gloro kaj honoro kaj senmorteco, eternan vivon;"],[2,8,"sed al tiuj, kiuj estas malpacemaj kaj ne obeas al la vero, sed obeas al maljusteco, koleron kaj indignon,","sed al tiuj, kiuj estas malpacemaj kaj ne obeas al la vero, sed obeas al maljusteco, koleron kaj indignon,"],[2,9,"aflikton kaj maltrankvilon, sur ĉiun animon de homo, kiu faras malbonon, de Judo unue kaj de Greko;","aflikton kaj maltrankvilon, sur ĉiun animon de homo, kiu faras malbonon, de Judo unue kaj de Greko;"],[2,10,"sed gloron kaj honoron kaj pacon al ĉiu, kiu faras bonon, al Judo unue kaj al Greko;","sed gloron kaj honoron kaj pacon al ĉiu, kiu faras bonon, al Judo unue kaj al Greko;"],[2,11,"ĉar ne estas personfavorado ĉe Dio.","ĉar ne estas personfavorado ĉe Dio."],[2,12,"Ĉar ĉiu, kiu pekis sen leĝo, ankaŭ pereos sen leĝo; kaj ĉiu, kiu pekis sub leĝo, estos juĝata per leĝo;","Ĉar ĉiu, kiu pekis sen leĝo, ankaŭ pereos sen leĝo; kaj ĉiu, kiu pekis sub leĝo, estos juĝata per leĝo;"],[2,13,"(ĉar ne la aŭskultantoj de leĝo estos justaj antaŭ Dio, sed la plenumantoj de leĝo estos pravigitaj","(ĉar ne la aŭskultantoj de leĝo estos justaj antaŭ Dio, sed la plenumantoj de leĝo estos pravigitaj"],[2,14,"ĉar kiam la nacianoj, kiuj ne havas la leĝon, faras nature la aferojn de la leĝo, ĉi tiuj, ne havante leĝon, estas leĝo por si mem;","ĉar kiam la nacianoj, kiuj ne havas la leĝon, faras nature la aferojn de la leĝo, ĉi tiuj, ne havante leĝon, estas leĝo por si mem;"],[2,15,"kiuj elmontras la faradon de la leĝo skribita en iliaj koroj, kiam ilia konscienco kunatestas, kaj iliaj rezonadoj inter si akuzas aŭ defendas ilin.)","kiuj elmontras la faradon de la leĝo skribita en iliaj koroj, kiam ilia konscienco kunatestas, kaj iliaj rezonadoj inter si akuzas aŭ defendas ilin.)"],[2,16,"en la tago, kiam Dio juĝos la sekretojn de homoj, laŭ mia evangelio, per Jesuo Kristo.","en la tago, kiam Dio juĝos la sekretojn de homoj, laŭ mia evangelio, per Jesuo Kristo."],[2,17,"Sed se vi estas nomata Judo, kaj apogas vin sur la leĝon, kaj fieras pri Dio,","Sed se vi estas nomata Judo, kaj apogas vin sur la leĝon, kaj fieras pri Dio,"],[2,18,"kaj konas Lian volon, kaj aprobas la aprobindaĵojn, kaj estas instruita el la leĝo,","kaj konas Lian volon, kaj aprobas la aprobindaĵojn, kaj estas instruita el la leĝo,"],[2,19,"kaj estas konvinkita, ke vi mem estas gvidanto por la blinduloj, lumo por tiuj, kiuj estas en mallumo,","kaj estas konvinkita, ke vi mem estas gvidanto por la blinduloj, lumo por tiuj, kiuj estas en mallumo,"],[2,20,"edukanto por la senprudentuloj, instruanto por infanoj, havante en la leĝo la formon de la scio kaj la vero;","edukanto por la senprudentuloj, instruanto por infanoj, havante en la leĝo la formon de la scio kaj la vero;"],[2,21,"vi, kiu instruas alian, ĉu vi ne instruas vin mem? vi, kiu predikas: Ne ŝtelu; ĉu vi ŝtelas?","vi, kiu instruas alian, ĉu vi ne instruas vin mem? vi, kiu predikas: Ne ŝtelu; ĉu vi ŝtelas?"],[2,22,"vi, kiu diras: Ne adultu; ĉu vi adultas? vi, kiu abomenas idolojn, ĉu vi prirabas templojn?","vi, kiu diras: Ne adultu; ĉu vi adultas? vi, kiu abomenas idolojn, ĉu vi prirabas templojn?"],[2,23,"vi, kiu fieras pri la leĝo, ĉu vi malhonoras Dion per via transpaŝo de la leĝo?","vi, kiu fieras pri la leĝo, ĉu vi malhonoras Dion per via transpaŝo de la leĝo?"],[2,24,"Ĉar pro vi, la nomo de Dio estas blasfemata inter la nacianoj, kiel estas skribite.","Ĉar pro vi, la nomo de Dio estas blasfemata inter la nacianoj, kiel estas skribite."],[2,25,"Ĉar cirkumcido vere utilas, se vi estas faranto de la leĝo; sed se vi estas pekanto kontraŭ la leĝo, via cirkumcido fariĝas necirkumcido.","Ĉar cirkumcido vere utilas, se vi estas faranto de la leĝo; sed se vi estas pekanto kontraŭ la leĝo, via cirkumcido fariĝas necirkumcido."],[2,26,"Se do necirkumcidulo plenumas la ordonojn de la leĝo, ĉu lia necirkumcido ne kalkuliĝos kiel cirkumcido?","Se do necirkumcidulo plenumas la ordonojn de la leĝo, ĉu lia necirkumcido ne kalkuliĝos kiel cirkumcido?"],[2,27,"kaj ĉu la laŭnatura necirkumcidulo, se li plenumas la leĝon, ne juĝos vin, kiu kun la skribo kaj cirkumcido transpaŝas la leĝon?","kaj ĉu la laŭnatura necirkumcidulo, se li plenumas la leĝon, ne juĝos vin, kiu kun la skribo kaj cirkumcido transpaŝas la leĝon?"],[2,28,"Ĉar Judo estas ne tiu, kiu estas ekstere tia, kaj cirkumcido estas ne tio, kio estas tia ekstere en la karno;","Ĉar Judo estas ne tiu, kiu estas ekstere tia, kaj cirkumcido estas ne tio, kio estas tia ekstere en la karno;"],[2,29,"sed Judo estas tiu, kiu estas interne tia, kaj cirkumcido estas en la koro, laŭ la spirito, ne laŭ la litero, kies laŭdo estas ne de homoj, sed de Dio.","sed Judo estas tiu, kiu estas interne tia, kaj cirkumcido estas en la koro, laŭ la spirito, ne laŭ la litero, kies laŭdo estas ne de homoj, sed de Dio."],[3,1,"Kia do estas la supereco de la Judoj? aŭ kia estas la utilo de cirkumcido?","Kia do estas la supereco de la Judoj? aŭ kia estas la utilo de cirkumcido?"],[3,2,"Multa en ĉiu rilato: unue, ke al ili estis konfiditaj la orakoloj de Dio.","Multa en ĉiu rilato: unue, ke al ili estis konfiditaj la orakoloj de Dio."],[3,3,"Ĉu do estas grave, se kelkaj ne fidis? ĉu ilia senfideco vantigos la fidelecon de Dio?","Ĉu do estas grave, se kelkaj ne fidis? ĉu ilia senfideco vantigos la fidelecon de Dio?"],[3,4,"Nepre ne! Dio montriĝu vera, sed ĉiu homo mensoganto, kiel estas skribite: Ke Vi estu justa en Via vorto Kaj pura en Via juĝo.","Nepre ne! Dio montriĝu vera, sed ĉiu homo mensoganto, kiel estas skribite: Ke Vi estu justa en Via vorto Kaj pura en Via juĝo."],[3,5,"Sed se nia maljusteco rekomendas la justecon de Dio, kion ni diros? Ĉu maljusta estas Dio, kiu alportas koleron? (Mi parolas kiel homo.)","Sed se nia maljusteco rekomendas la justecon de Dio, kion ni diros? Ĉu maljusta estas Dio, kiu alportas koleron? (Mi parolas kiel homo.)"],[3,6,"Nepre ne! ĉar kiel Dio juĝus la mondon?","Nepre ne! ĉar kiel Dio juĝus la mondon?"],[3,7,"Ĉar se la vero de Dio per mia mensogo abundis al Lia gloro, kial mi estas ankoraŭ juĝata, kiel pekinto?","Ĉar se la vero de Dio per mia mensogo abundis al Lia gloro, kial mi estas ankoraŭ juĝata, kiel pekinto?"],[3,8,"kaj kial ne (kiel ni estas kalumniataj, kaj kelkaj asertas, ke ni diras): Ni faru malbonon, por ke venu bono? ilia kondamno estas justa.","kaj kial ne (kiel ni estas kalumniataj, kaj kelkaj asertas, ke ni diras): Ni faru malbonon, por ke venu bono? ilia kondamno estas justa."],[3,9,"Kio do? ĉu ni nin senkulpigas? Tute ne: ĉar ni jam akuzis egale Judojn kaj Grekojn, ke ĉiuj estas sub peko;","Kio do? ĉu ni nin senkulpigas? Tute ne: ĉar ni jam akuzis egale Judojn kaj Grekojn, ke ĉiuj estas sub peko;"],[3,10,"kiel estas skribite: Ne ekzistas justulo, ne eĉ unu;","kiel estas skribite: Ne ekzistas justulo, ne eĉ unu;"],[3,11,"Ne ekzistas prudentulo, Ne ekzistas iu, kiu serĉas Dion;","Ne ekzistas prudentulo, Ne ekzistas iu, kiu serĉas Dion;"],[3,12,"Ĉiuj devojiĝis, ĉiuj senutiliĝis; Ekzistas neniu, kiu faras bonon, ne eĉ unu;","Ĉiuj devojiĝis, ĉiuj senutiliĝis; Ekzistas neniu, kiu faras bonon, ne eĉ unu;"],[3,13,"Malfermita tombo estas ilia gorĝo; Per sia lango ili hipokritis; Veneno de vipuro estas sub iliaj lipoj;","Malfermita tombo estas ilia gorĝo; Per sia lango ili hipokritis; Veneno de vipuro estas sub iliaj lipoj;"],[3,14,"Ilia buŝo estas plena de malbenado kaj malico;","Ilia buŝo estas plena de malbenado kaj malico;"],[3,15,"Iliaj piedoj rapidas, por verŝi sangon;","Iliaj piedoj rapidas, por verŝi sangon;"],[3,16,"Ruinigo kaj pereigo estas sur iliaj vojoj;","Ruinigo kaj pereigo estas sur iliaj vojoj;"],[3,17,"Kaj vojon de paco ili ne konas;","Kaj vojon de paco ili ne konas;"],[3,18,"Antaŭ iliaj okuloj ne ekzistas timo antaŭ Dio.","Antaŭ iliaj okuloj ne ekzistas timo antaŭ Dio."],[3,19,"Sed ni scias, ke ĉion ajn, kion la leĝo diras, ĝi parolas al tiuj, kiuj estas sub la leĝo; ke ĉiu buŝo fermiĝu, kaj ke la tuta mondo submetiĝu sub la juĝon de Dio;","Sed ni scias, ke ĉion ajn, kion la leĝo diras, ĝi parolas al tiuj, kiuj estas sub la leĝo; ke ĉiu buŝo fermiĝu, kaj ke la tuta mondo submetiĝu sub la juĝon de Dio;"],[3,20,"ĉar per la faroj de la leĝo neniu karno praviĝos antaŭ Li; ĉar per la leĝo venas konscio pri peko.","ĉar per la faroj de la leĝo neniu karno praviĝos antaŭ Li; ĉar per la leĝo venas konscio pri peko."],[3,21,"Sed nun, ekster la leĝo, justeco de Dio montriĝis, atestata per la leĝo kaj la profetoj;","Sed nun, ekster la leĝo, justeco de Dio montriĝis, atestata per la leĝo kaj la profetoj;"],[3,22,"nome, la justeco de Dio, per fido al Jesuo Kristo, por ĉiuj kredantoj, ĉar ne ekzistas diferencigo;","nome, la justeco de Dio, per fido al Jesuo Kristo, por ĉiuj kredantoj, ĉar ne ekzistas diferencigo;"],[3,23,"ĉar ĉiuj pekis kaj maltrafis la gloron de Dio;","ĉar ĉiuj pekis kaj maltrafis la gloron de Dio;"],[3,24,"pravigite donace de Lia graco, per la elaĉeto, kiu estas en Kristo Jesuo;","pravigite donace de Lia graco, per la elaĉeto, kiu estas en Kristo Jesuo;"],[3,25,"kiun Dio antaŭdifinis kiel repacigilon per fido en lia sango, por la elmontrado de Sia justeco per la pardono de la pekoj, antaŭe faritaj laŭ la toleremeco de Dio;","kiun Dio antaŭdifinis kiel repacigilon per fido en lia sango, por la elmontrado de Sia justeco per la pardono de la pekoj, antaŭe faritaj laŭ la toleremeco de Dio;"],[3,26,"por la elmontrado de Lia justeco en la nuna tempo, kaj ke Li estas mem justa, kaj estas la praviganto de tiu, kiu havas fidon en Jesuo.","por la elmontrado de Lia justeco en la nuna tempo, kaj ke Li estas mem justa, kaj estas la praviganto de tiu, kiu havas fidon en Jesuo."],[3,27,"Kie do estas la fanfaronado? Ĝi estas esceptita. Per kia leĝo? de faroj? Ne; sed per la leĝo de fido.","Kie do estas la fanfaronado? Ĝi estas esceptita. Per kia leĝo? de faroj? Ne; sed per la leĝo de fido."],[3,28,"Ni do konkludas, ke homo praviĝas per fido, ekster la faroj de la leĝo.","Ni do konkludas, ke homo praviĝas per fido, ekster la faroj de la leĝo."],[3,29,"Ĉu Dio estas nur Dio de la Judoj? ĉu ne ankaŭ de la nacianoj? Jes, ankaŭ de la nacianoj;","Ĉu Dio estas nur Dio de la Judoj? ĉu ne ankaŭ de la nacianoj? Jes, ankaŭ de la nacianoj;"],[3,30,"ĉar Dio estas unu, kaj Li pravigos la cirkumcidularon pro fido kaj la necirkumcidularon per fido.","ĉar Dio estas unu, kaj Li pravigos la cirkumcidularon pro fido kaj la necirkumcidularon per fido."],[3,31,"Ĉu ni do per fido vantigas la leĝon? Nepre ne! sed ni firmigas la leĝon.","Ĉu ni do per fido vantigas la leĝon? Nepre ne! sed ni firmigas la leĝon."],[4,1,"Kion do, ni diros, trovis Abraham, nia praavo laŭ la karno?","Kion do, ni diros, trovis Abraham, nia praavo laŭ la karno?"],[4,2,"Ĉar se Abraham praviĝis per faroj, li havas ion, pri kio fieri, sed ne antaŭ Dio.","Ĉar se Abraham praviĝis per faroj, li havas ion, pri kio fieri, sed ne antaŭ Dio."],[4,3,"Ĉar kion diras la Skribo? Kaj Abraham kredis al Dio, kaj tio estis kalkulita al li kiel virto.","Ĉar kion diras la Skribo? Kaj Abraham kredis al Dio, kaj tio estis kalkulita al li kiel virto."],[4,4,"Al tiu, kiu laboras, la salajro estas kalkulata ne kiel favoro, sed kiel ŝuldo.","Al tiu, kiu laboras, la salajro estas kalkulata ne kiel favoro, sed kiel ŝuldo."],[4,5,"Sed al tiu, kiu ne laboras, sed kredas al Tiu, kiu pravigas la malpiulon, lia fido estas kalkulata kiel virto.","Sed al tiu, kiu ne laboras, sed kredas al Tiu, kiu pravigas la malpiulon, lia fido estas kalkulata kiel virto."],[4,6,"Kiel David ankaŭ pridiras la feliĉon de la homo, al kiu Dio kalkulas virton ekster faroj,","Kiel David ankaŭ pridiras la feliĉon de la homo, al kiu Dio kalkulas virton ekster faroj,"],[4,7,"dirante: Feliĉaj estas tiuj, kies krimoj estas pardonitaj, Kies pekoj estas kovritaj.","dirante: Feliĉaj estas tiuj, kies krimoj estas pardonitaj, Kies pekoj estas kovritaj."],[4,8,"Feliĉa estas la homo, al kiu la Eternulo ne kalkulas lian kulpon.","Feliĉa estas la homo, al kiu la Eternulo ne kalkulas lian kulpon."],[4,9,"Ĉu do ĉi tiu feliĉo apartenas al la cirkumcidularo, aŭ al la necirkumcidularo ankaŭ? Ĉar ni diras, ke al Abraham la fido estis kalkulita kiel virto.","Ĉu do ĉi tiu feliĉo apartenas al la cirkumcidularo, aŭ al la necirkumcidularo ankaŭ? Ĉar ni diras, ke al Abraham la fido estis kalkulita kiel virto."],[4,10,"Kiel do ĝi estis kalkulita? kiam li estis en cirkumcido, aŭ en necirkumcido? Ne en cirkumcido, sed en necirkumcido;","Kiel do ĝi estis kalkulita? kiam li estis en cirkumcido, aŭ en necirkumcido? Ne en cirkumcido, sed en necirkumcido;"],[4,11,"kaj li ricevis la signon de cirkumcido, kiel sigelon de la virto de la fido, kiu ekzistis en lia necirkumcido; por ke li estu la patro de ĉiuj, kiuj ankoraŭ en necirkumcido kredas, por ke virto estu kalkulata al ili;","kaj li ricevis la signon de cirkumcido, kiel sigelon de la virto de la fido, kiu ekzistis en lia necirkumcido; por ke li estu la patro de ĉiuj, kiuj ankoraŭ en necirkumcido kredas, por ke virto estu kalkulata al ili;"],[4,12,"kaj la patro de cirkumcido al tiuj, kiuj ne nur estas anoj de la cirkumcido, sed kiuj ankaŭ sekvas la paŝojn de tiu fido, kiun nia patro Abraham havis dum sia necirkumcido.","kaj la patro de cirkumcido al tiuj, kiuj ne nur estas anoj de la cirkumcido, sed kiuj ankaŭ sekvas la paŝojn de tiu fido, kiun nia patro Abraham havis dum sia necirkumcido."],[4,13,"Ĉar ne per la leĝo fariĝis la promeso al Abraham aŭ al lia idaro, ke li estos heredanto de la mondo, sed per la virto el fido.","Ĉar ne per la leĝo fariĝis la promeso al Abraham aŭ al lia idaro, ke li estos heredanto de la mondo, sed per la virto el fido."],[4,14,"Ĉar se tiuj, kiuj estas laŭ la leĝo, estas heredantoj, la fido nuliĝis, kaj la promeso vantiĝis;","Ĉar se tiuj, kiuj estas laŭ la leĝo, estas heredantoj, la fido nuliĝis, kaj la promeso vantiĝis;"],[4,15,"ĉar la leĝo elfaras koleron; sed kie ne ekzistas leĝo, tie ankaŭ ne ekzistas transpaŝo.","ĉar la leĝo elfaras koleron; sed kie ne ekzistas leĝo, tie ankaŭ ne ekzistas transpaŝo."],[4,16,"Ĝi do estas el fido por tio, ke ĝi estu laŭ graco; por ke la promeso estu firma al la tuta idaro, ne nur al tiu, kiu estas el la leĝo, sed ankaŭ al tiu, kiu estas el la fido de Abraham, kiu estas la patro de ni ĉiuj","Ĝi do estas el fido por tio, ke ĝi estu laŭ graco; por ke la promeso estu firma al la tuta idaro, ne nur al tiu, kiu estas el la leĝo, sed ankaŭ al tiu, kiu estas el la fido de Abraham, kiu estas la patro de ni ĉiuj"],[4,17,"(kiel estas skribite: Mi faris vin patro de multe da popoloj) antaŭ Tiu, al kiu li kredis, nome Dio, kiu vivigas la mortintojn, kaj vokas la neekzistantaĵojn, kvazaŭ ili ekzistus.","(kiel estas skribite: Mi faris vin patro de multe da popoloj) antaŭ Tiu, al kiu li kredis, nome Dio, kiu vivigas la mortintojn, kaj vokas la neekzistantaĵojn, kvazaŭ ili ekzistus."],[4,18,"Li ekster espero kredis en espero, por ke li fariĝu patro de multe da popoloj, laŭ la diritaĵo: Tiel estos via idaro.","Li ekster espero kredis en espero, por ke li fariĝu patro de multe da popoloj, laŭ la diritaĵo: Tiel estos via idaro."],[4,19,"Kaj ne senfortigite en fido, li pripensis sian propran korpon jam pereintan (estante preskaŭ centjara), kaj la senvivecon de la utero de Sara;","Kaj ne senfortigite en fido, li pripensis sian propran korpon jam pereintan (estante preskaŭ centjara), kaj la senvivecon de la utero de Sara;"],[4,20,"tamen pri la promeso de Dio li ne ŝanceliĝis en nekredemo, sed fortiĝis per fido, donante la gloron al Dio,","tamen pri la promeso de Dio li ne ŝanceliĝis en nekredemo, sed fortiĝis per fido, donante la gloron al Dio,"],[4,21,"kaj plene certigite, ke tion, kion Li promesis, Li povas ankaŭ fari.","kaj plene certigite, ke tion, kion Li promesis, Li povas ankaŭ fari."],[4,22,"Tial ĝi estis kalkulita al li kiel virto.","Tial ĝi estis kalkulita al li kiel virto."],[4,23,"Kaj ne por li sola estis skribite, ke ĝi estis kalkulita al li;","Kaj ne por li sola estis skribite, ke ĝi estis kalkulita al li;"],[4,24,"sed ankaŭ por ni, al kiuj ĝi estos kalkulata, kaj kiuj kredas al Tiu, kiu levis el la mortintoj Jesuon, nian Sinjoron,","sed ankaŭ por ni, al kiuj ĝi estos kalkulata, kaj kiuj kredas al Tiu, kiu levis el la mortintoj Jesuon, nian Sinjoron,"],[4,25,"kiu estis transdonita pro niaj pekoj kaj estis relevita por nia pravigo.","kiu estis transdonita pro niaj pekoj kaj estis relevita por nia pravigo."],[5,1,"Tial ni, pravigite per fido, havu pacon kun Dio per nia Sinjoro Jesuo Kristo,","Tial ni, pravigite per fido, havu pacon kun Dio per nia Sinjoro Jesuo Kristo,"],[5,2,"per kiu ankaŭ ni ricevis enkondukon per fido en ĉi tiun gracon, en kiu ni staras; kaj ni ĝoju pro espero de la gloro de Dio.","per kiu ankaŭ ni ricevis enkondukon per fido en ĉi tiun gracon, en kiu ni staras; kaj ni ĝoju pro espero de la gloro de Dio."],[5,3,"Kaj krome ni ĝoju ankaŭ pro la afliktoj, sciante, ke aflikto faras paciencon;","Kaj krome ni ĝoju ankaŭ pro la afliktoj, sciante, ke aflikto faras paciencon;"],[5,4,"kaj pacienco provitecon, kaj proviteco esperon;","kaj pacienco provitecon, kaj proviteco esperon;"],[5,5,"kaj la espero ne hontigas, ĉar la amo de Dio estas verŝita en niajn korojn per la Sankta Spirito, donita al ni.","kaj la espero ne hontigas, ĉar la amo de Dio estas verŝita en niajn korojn per la Sankta Spirito, donita al ni."],[5,6,"Ĉar kiam ni ankoraŭ estis senfortaj, tiam Kristo ĝustatempe mortis pro malpiuloj.","Ĉar kiam ni ankoraŭ estis senfortaj, tiam Kristo ĝustatempe mortis pro malpiuloj."],[5,7,"Ĉar apenaŭ pro justulo iu mortus; ĉar pro bonulo eble iu kuraĝus morti.","Ĉar apenaŭ pro justulo iu mortus; ĉar pro bonulo eble iu kuraĝus morti."],[5,8,"Sed Dio rekomendas al ni Sian amon en tio, ke dum ni ankoraŭ estis pekuloj, Kristo mortis por ni.","Sed Dio rekomendas al ni Sian amon en tio, ke dum ni ankoraŭ estis pekuloj, Kristo mortis por ni."],[5,9,"Des plimulte do ni, jam pravigite per lia sango, estos per li savitaj el la kolero.","Des plimulte do ni, jam pravigite per lia sango, estos per li savitaj el la kolero."],[5,10,"Ĉar se ni, estante malamikoj, estas repacigitaj kun Dio per la morto de Lia Filo, des plimulte, repacigite, ni estos savitaj per lia vivo;","Ĉar se ni, estante malamikoj, estas repacigitaj kun Dio per la morto de Lia Filo, des plimulte, repacigite, ni estos savitaj per lia vivo;"],[5,11,"kaj krom tio ni fieras ankaŭ en Dio pro nia Sinjoro Jesuo Kristo, per kiu ni jam ricevis la repacigon.","kaj krom tio ni fieras ankaŭ en Dio pro nia Sinjoro Jesuo Kristo, per kiu ni jam ricevis la repacigon."],[5,12,"Pro tio, kiel per unu homo peko eniris en la mondon, kaj morto per peko, kaj tiel morto atingis ĉiujn homojn pro tio, ke ĉiuj pekis;","Pro tio, kiel per unu homo peko eniris en la mondon, kaj morto per peko, kaj tiel morto atingis ĉiujn homojn pro tio, ke ĉiuj pekis;"],[5,13,"ĉar ĝis la leĝo peko estis en la mondo, sed peko ne estas alkalkulata, kiam ne ekzistas leĝo.","ĉar ĝis la leĝo peko estis en la mondo, sed peko ne estas alkalkulata, kiam ne ekzistas leĝo."],[5,14,"Sed morto reĝis de post Adam ĝis Moseo, eĉ super tiuj, kiuj ne pekis simile al la transpaŝo de Adam, kiu estis la tipo de la venonto.","Sed morto reĝis de post Adam ĝis Moseo, eĉ super tiuj, kiuj ne pekis simile al la transpaŝo de Adam, kiu estis la tipo de la venonto."],[5,15,"Sed ne kia la eraro, tia estas la donaco. Ĉar se per la eraro de unu mortis la multaj, des plimulte abundis al la multaj la graco de Dio kaj la donaco per la graco de la unu homo Jesuo Kristo.","Sed ne kia la eraro, tia estas la donaco. Ĉar se per la eraro de unu mortis la multaj, des plimulte abundis al la multaj la graco de Dio kaj la donaco per la graco de la unu homo Jesuo Kristo."],[5,16,"Kaj la donaco ne estis laŭ la unu pekinta; ĉar la juĝo venis el unu ĝis kondamno, sed la donaco venis el multaj eraroj ĝis pravigo.","Kaj la donaco ne estis laŭ la unu pekinta; ĉar la juĝo venis el unu ĝis kondamno, sed la donaco venis el multaj eraroj ĝis pravigo."],[5,17,"Ĉar se, per la eraro de la unu, morto reĝis per unu, des plimulte reĝos en vivo per la unu Jesuo Kristo tiuj, kiuj ricevis abundon de la graco kaj de la donaco de justeco.","Ĉar se, per la eraro de la unu, morto reĝis per unu, des plimulte reĝos en vivo per la unu Jesuo Kristo tiuj, kiuj ricevis abundon de la graco kaj de la donaco de justeco."],[5,18,"Tial, kiel per unu eraro venis juĝo al ĉiuj homoj ĝis kondamno, tiel same per unu justaĵo venis la donaco al ĉiuj homoj ĝis la pravigo de vivo.","Tial, kiel per unu eraro venis juĝo al ĉiuj homoj ĝis kondamno, tiel same per unu justaĵo venis la donaco al ĉiuj homoj ĝis la pravigo de vivo."],[5,19,"Ĉar kiel per la malobeo de unu la multaj fariĝis pekuloj, tiel per la obeo de unu la multaj fariĝos justaj.","Ĉar kiel per la malobeo de unu la multaj fariĝis pekuloj, tiel per la obeo de unu la multaj fariĝos justaj."],[5,20,"Kaj la leĝo eniris, por ke la eraro plimultiĝu; sed kie peko plimultiĝis, graco multe pli superabundis,","Kaj la leĝo eniris, por ke la eraro plimultiĝu; sed kie peko plimultiĝis, graco multe pli superabundis,"],[5,21,"por ke tiel same, kiel la peko reĝis en morto, la graco reĝu per justeco ĝis eterna vivo per Jesuo Kristo, nia Sinjoro.","por ke tiel same, kiel la peko reĝis en morto, la graco reĝu per justeco ĝis eterna vivo per Jesuo Kristo, nia Sinjoro."],[6,1,"Kion do ni diru? Ĉu ni restu en peko, por ke graco abundu?","Kion do ni diru? Ĉu ni restu en peko, por ke graco abundu?"],[6,2,"Nepre ne! Ĉu ni, kiuj mortis al peko, ankoraŭ vivus en ĝi?","Nepre ne! Ĉu ni, kiuj mortis al peko, ankoraŭ vivus en ĝi?"],[6,3,"Ĉu vi ne scias, ke ni ĉiuj, kiuj baptiĝis al Jesuo Kristo, baptiĝis al lia morto?","Ĉu vi ne scias, ke ni ĉiuj, kiuj baptiĝis al Jesuo Kristo, baptiĝis al lia morto?"],[6,4,"Ni do estas entombigitaj kun li per bapto al morto, por ke, kiel Kristo estas levita el la mortintoj per la gloro de la Patro, tiel same ni ankaŭ iradu en noveco de vivo.","Ni do estas entombigitaj kun li per bapto al morto, por ke, kiel Kristo estas levita el la mortintoj per la gloro de la Patro, tiel same ni ankaŭ iradu en noveco de vivo."],[6,5,"Ĉar se ni jam kuniĝis al la simileco de lia morto, ni tiel same kuniĝos al la simileco de lia releviĝo,","Ĉar se ni jam kuniĝis al la simileco de lia morto, ni tiel same kuniĝos al la simileco de lia releviĝo,"],[6,6,"sciante, ke nia malnova homo estas kun li krucumita, por ke la korpo de peko estu neniigita, por ke ni jam ne estu sklavoj al peko;","sciante, ke nia malnova homo estas kun li krucumita, por ke la korpo de peko estu neniigita, por ke ni jam ne estu sklavoj al peko;"],[6,7,"ĉar tiu, kiu mortis, estas pravigita pri peko.","ĉar tiu, kiu mortis, estas pravigita pri peko."],[6,8,"Sed se ni mortis kun Kristo, ni kredas, ke ni ankaŭ vivos kun li;","Sed se ni mortis kun Kristo, ni kredas, ke ni ankaŭ vivos kun li;"],[6,9,"sciante, ke Kristo, levite el la mortintoj, ne plu mortas; la morto ne plu lin regas.","sciante, ke Kristo, levite el la mortintoj, ne plu mortas; la morto ne plu lin regas."],[6,10,"Ĉar mortante, li mortis al peko unufoje por ĉiam; sed vivante, li vivas al Dio.","Ĉar mortante, li mortis al peko unufoje por ĉiam; sed vivante, li vivas al Dio."],[6,11,"Tial ankaŭ vi vin kalkulu mortintoj al peko, sed vivantoj al Dio en Kristo Jesuo.","Tial ankaŭ vi vin kalkulu mortintoj al peko, sed vivantoj al Dio en Kristo Jesuo."],[6,12,"Tial peko ne reĝu en via morta korpo tiel, ke vi obeu al ĝiaj deziroj;","Tial peko ne reĝu en via morta korpo tiel, ke vi obeu al ĝiaj deziroj;"],[6,13,"ankaŭ ne prezentu viajn membrojn iloj de maljusteco al peko, sed prezentu vin al Dio vivantoj el la mortintoj, kaj viajn membrojn iloj de justeco por Dio.","ankaŭ ne prezentu viajn membrojn iloj de maljusteco al peko, sed prezentu vin al Dio vivantoj el la mortintoj, kaj viajn membrojn iloj de justeco por Dio."],[6,14,"Ĉar peko ne regos vin, ĉar vi estas ne sub la leĝo, sed sub graco.","Ĉar peko ne regos vin, ĉar vi estas ne sub la leĝo, sed sub graco."],[6,15,"Kio do? ĉu ni peku, pro tio, ke ni estas ne sub leĝo, sed sub graco? Nepre ne!","Kio do? ĉu ni peku, pro tio, ke ni estas ne sub leĝo, sed sub graco? Nepre ne!"],[6,16,"Ĉu vi ne scias, ke kiam vi vin prezentas, kiel sklavoj al iu por obeado, vi estas sklavoj de tiu, al kiu vi obeas, ĉu de peko por morto, aŭ de obeemeco por justeco?","Ĉu vi ne scias, ke kiam vi vin prezentas, kiel sklavoj al iu por obeado, vi estas sklavoj de tiu, al kiu vi obeas, ĉu de peko por morto, aŭ de obeemeco por justeco?"],[6,17,"Sed danko estu al Dio, ke kvankam vi estis la sklavoj de peko, vi tamen fariĝis kore obeemaj al tiu tipo de instruado, al kiu vi estas kondukitaj;","Sed danko estu al Dio, ke kvankam vi estis la sklavoj de peko, vi tamen fariĝis kore obeemaj al tiu tipo de instruado, al kiu vi estas kondukitaj;"],[6,18,"kaj liberigite el peko, vi sklaviĝis al justeco.","kaj liberigite el peko, vi sklaviĝis al justeco."],[6,19,"Mi parolas home pro la malforteco de via karno; ĉar kiel vi prezentis viajn membrojn sklavoj al malpureco kaj al maljusteco ĝis maljusteco, tiel nun prezentu viajn membrojn sklavoj al justeco ĝis sanktigo.","Mi parolas home pro la malforteco de via karno; ĉar kiel vi prezentis viajn membrojn sklavoj al malpureco kaj al maljusteco ĝis maljusteco, tiel nun prezentu viajn membrojn sklavoj al justeco ĝis sanktigo."],[6,20,"Ĉar kiam vi estis sklavoj de peko, vi estis liberaj de justeco.","Ĉar kiam vi estis sklavoj de peko, vi estis liberaj de justeco."],[6,21,"Kian frukton do vi havis tiam el tio, pri kio vi nun hontas? ĉar la fino de tio estas morto.","Kian frukton do vi havis tiam el tio, pri kio vi nun hontas? ĉar la fino de tio estas morto."],[6,22,"Sed nun, liberigite el peko, kaj sklaviĝinte al Dio, vi havas vian frukton ĝis sanktiĝo, kaj por fino eternan vivon.","Sed nun, liberigite el peko, kaj sklaviĝinte al Dio, vi havas vian frukton ĝis sanktiĝo, kaj por fino eternan vivon."],[6,23,"Ĉar la salajro de peko estas morto; sed la donaco de Dio estas eterna vivo en Kristo Jesuo, nia Sinjoro.","Ĉar la salajro de peko estas morto; sed la donaco de Dio estas eterna vivo en Kristo Jesuo, nia Sinjoro."],[7,1,"Aŭ ĉu vi ne scias, fratoj (ĉar mi parolas al konantoj de la leĝo), ke la leĝo regas la homon tiel longe, kiel li vivas?","Aŭ ĉu vi ne scias, fratoj (ĉar mi parolas al konantoj de la leĝo), ke la leĝo regas la homon tiel longe, kiel li vivas?"],[7,2,"Ĉar la edzinigita virino estas leĝe alligita al sia edzo dum lia vivo; sed se la edzo mortas, ŝi liberiĝas el la leĝo de la edzo.","Ĉar la edzinigita virino estas leĝe alligita al sia edzo dum lia vivo; sed se la edzo mortas, ŝi liberiĝas el la leĝo de la edzo."],[7,3,"Se do, dum la edzo vivas, ŝi kuniĝas kun alia viro, ŝi estos nomata adultulino; sed se la edzo mortis, ŝi estas libera de la leĝo, kaj ne estas adultulino, kvankam kuniĝinte kun alia viro.","Se do, dum la edzo vivas, ŝi kuniĝas kun alia viro, ŝi estos nomata adultulino; sed se la edzo mortis, ŝi estas libera de la leĝo, kaj ne estas adultulino, kvankam kuniĝinte kun alia viro."],[7,4,"Tiel, miaj fratoj, vi same mortis al la leĝo per la korpo de Kristo, por kuniĝi kun alia, nome kun tiu, kiu leviĝis el la mortintoj, por ke ni donu frukton al Dio.","Tiel, miaj fratoj, vi same mortis al la leĝo per la korpo de Kristo, por kuniĝi kun alia, nome kun tiu, kiu leviĝis el la mortintoj, por ke ni donu frukton al Dio."],[7,5,"Ĉar dum ni estis en karno, la laŭpekaj pasioj, kiuj estis per la leĝo, energiis en niaj membroj, por doni frukton al morto.","Ĉar dum ni estis en karno, la laŭpekaj pasioj, kiuj estis per la leĝo, energiis en niaj membroj, por doni frukton al morto."],[7,6,"Sed ni jam liberiĝis el la leĝo, mortinte rilate tion, en kio ni estis tenataj, por ke ni servu en noveco de spirito, kaj ne en malnoveco de litero.","Sed ni jam liberiĝis el la leĝo, mortinte rilate tion, en kio ni estis tenataj, por ke ni servu en noveco de spirito, kaj ne en malnoveco de litero."],[7,7,"Kion do ni diru? Ĉu la leĝo estas peko? Nepre ne! Tamen mi ne konus pekon, krom per la leĝo; ĉar mi ne konus deziron, se la leĝo ne dirus: Ne deziru;","Kion do ni diru? Ĉu la leĝo estas peko? Nepre ne! Tamen mi ne konus pekon, krom per la leĝo; ĉar mi ne konus deziron, se la leĝo ne dirus: Ne deziru;"],[7,8,"sed la peko, trovante pretekston, estigis en mi per la ordono ĉian deziremon, ĉar ekster leĝo la peko estas senviva.","sed la peko, trovante pretekston, estigis en mi per la ordono ĉian deziremon, ĉar ekster leĝo la peko estas senviva."],[7,9,"Kaj iam mi vivadis ekster la leĝo; sed kiam la ordono venis, la peko viviĝis, kaj mi mortis;","Kaj iam mi vivadis ekster la leĝo; sed kiam la ordono venis, la peko viviĝis, kaj mi mortis;"],[7,10,"kaj tiun ordonon, kiu estas por vivo, mi trovis por morto;","kaj tiun ordonon, kiu estas por vivo, mi trovis por morto;"],[7,11,"ĉar la peko, trovinte pretekston, per la ordono min trompis, kaj per ĝi min mortigis.","ĉar la peko, trovinte pretekston, per la ordono min trompis, kaj per ĝi min mortigis."],[7,12,"Tiel la leĝo estas sankta, kaj la ordono estas sankta kaj justa kaj bona.","Tiel la leĝo estas sankta, kaj la ordono estas sankta kaj justa kaj bona."],[7,13,"Ĉu do tio, kio estas bona, fariĝis morto por mi? Nepre ne! Sed la peko, por ke ĝi montriĝu peko, estigante morton en mi per la bono — por ke per la ordono la peko fariĝu treege peka.","Ĉu do tio, kio estas bona, fariĝis morto por mi? Nepre ne! Sed la peko, por ke ĝi montriĝu peko, estigante morton en mi per la bono — por ke per la ordono la peko fariĝu treege peka."],[7,14,"Ĉar ni scias, ke la leĝo estas spirita; sed mi estas karna, vendite sub pekon.","Ĉar ni scias, ke la leĝo estas spirita; sed mi estas karna, vendite sub pekon."],[7,15,"Ĉar mi ne havas certecon pri tio, kion mi faradas; ĉar mi ne agas laŭ tio, kion mi volas; sed kion mi malamas, tion mi faras.","Ĉar mi ne havas certecon pri tio, kion mi faradas; ĉar mi ne agas laŭ tio, kion mi volas; sed kion mi malamas, tion mi faras."],[7,16,"Sed se mi faras tion, kion mi ne volas fari, mi konsentas al la leĝo, ke ĝi estas bona.","Sed se mi faras tion, kion mi ne volas fari, mi konsentas al la leĝo, ke ĝi estas bona."],[7,17,"La faranto do estas jam ne mi, sed la peko, loĝanta en mi.","La faranto do estas jam ne mi, sed la peko, loĝanta en mi."],[7,18,"Ĉar mi scias, ke en mi (tio estas, en mia karno) bono ne loĝas; ĉar ĉe mi estas la volo, sed ne la elfaro de la bono.","Ĉar mi scias, ke en mi (tio estas, en mia karno) bono ne loĝas; ĉar ĉe mi estas la volo, sed ne la elfaro de la bono."],[7,19,"Ĉar la bonon, kiun mi volas fari, mi ne faras; sed la malbonon, kiun mi ne volas fari, mi faradas.","Ĉar la bonon, kiun mi volas fari, mi ne faras; sed la malbonon, kiun mi ne volas fari, mi faradas."],[7,20,"Sed se mi faras tion, kion mi ne volas fari, faras ĝin jam ne mi, sed la peko, loĝanta en mi.","Sed se mi faras tion, kion mi ne volas fari, faras ĝin jam ne mi, sed la peko, loĝanta en mi."],[7,21,"Mi do trovas leĝon, ke kiam mi volas fari bonon, la malbono estas ĉe mi.","Mi do trovas leĝon, ke kiam mi volas fari bonon, la malbono estas ĉe mi."],[7,22,"Ĉar mi ĝojas en la leĝo de Dio laŭ la interna homo;","Ĉar mi ĝojas en la leĝo de Dio laŭ la interna homo;"],[7,23,"sed mi vidas alian leĝon en miaj membroj, militantan kontraŭ la leĝo de mia menso, kaj forkaptantan min sub la leĝon de la peko, kiu estas en miaj membroj.","sed mi vidas alian leĝon en miaj membroj, militantan kontraŭ la leĝo de mia menso, kaj forkaptantan min sub la leĝon de la peko, kiu estas en miaj membroj."],[7,24,"Ho ve, mi malfeliĉulo! kiu min liberigos el la korpo de ĉi tiu morto?","Ho ve, mi malfeliĉulo! kiu min liberigos el la korpo de ĉi tiu morto?"],[7,25,"Danko estu al Dio, per Jesuo Kristo, nia Sinjoro. Per la menso do mi mem servas al la leĝo de Dio, sed per la karno al la leĝo de peko.","Danko estu al Dio, per Jesuo Kristo, nia Sinjoro. Per la menso do mi mem servas al la leĝo de Dio, sed per la karno al la leĝo de peko."],[8,1,"Ekzistas do jam nenia kondamno kontraŭ tiuj, kiuj estas en Kristo Jesuo.","Ekzistas do jam nenia kondamno kontraŭ tiuj, kiuj estas en Kristo Jesuo."],[8,2,"Ĉar la leĝo de la Spirito de vivo en Kristo Jesuo liberigis min de la leĝo de peko kaj morto.","Ĉar la leĝo de la Spirito de vivo en Kristo Jesuo liberigis min de la leĝo de peko kaj morto."],[8,3,"Ĉar kiam la leĝo troviĝis nekapabla pro tio, ke ĝi estis malforta pro la karno, Dio, sendante Sian propran Filon en simileco de peka karno kaj pro peko, kondamnis la pekadon en la karno;","Ĉar kiam la leĝo troviĝis nekapabla pro tio, ke ĝi estis malforta pro la karno, Dio, sendante Sian propran Filon en simileco de peka karno kaj pro peko, kondamnis la pekadon en la karno;"],[8,4,"por ke la postulo de la leĝo plenumiĝu en ni, kiuj iradas ne laŭ la karno, sed laŭ la spirito.","por ke la postulo de la leĝo plenumiĝu en ni, kiuj iradas ne laŭ la karno, sed laŭ la spirito."],[8,5,"Ĉar kiuj estas laŭ la karno, tiuj sin interesas pri la aferoj de la karno; sed kiuj estas laŭ la spirito, pri la aferoj de la spirito.","Ĉar kiuj estas laŭ la karno, tiuj sin interesas pri la aferoj de la karno; sed kiuj estas laŭ la spirito, pri la aferoj de la spirito."],[8,6,"Ĉar la intereso de la karno estas morto, sed la intereso de la spirito estas vivo kaj paco;","Ĉar la intereso de la karno estas morto, sed la intereso de la spirito estas vivo kaj paco;"],[8,7,"ĉar la intereso de la karno estas malamikeco kontraŭ Dio, ĉar ĝi ne obeas al la leĝo de Dio, kaj ĝi ja ne povas obei;","ĉar la intereso de la karno estas malamikeco kontraŭ Dio, ĉar ĝi ne obeas al la leĝo de Dio, kaj ĝi ja ne povas obei;"],[8,8,"kaj tiuj, kiuj estas en la karno, ne povas plaĉi al Dio.","kaj tiuj, kiuj estas en la karno, ne povas plaĉi al Dio."],[8,9,"Sed vi estas ne en la karno, sed en la spirito, se vere la Spirito de Dio loĝas en vi. Sed se iu ne havas la Spiriton de Kristo, tiu ne estas lia.","Sed vi estas ne en la karno, sed en la spirito, se vere la Spirito de Dio loĝas en vi. Sed se iu ne havas la Spiriton de Kristo, tiu ne estas lia."],[8,10,"Kaj se Kristo estas en vi, la korpo malvivas pro peko, sed la spirito estas vivo pro justeco.","Kaj se Kristo estas en vi, la korpo malvivas pro peko, sed la spirito estas vivo pro justeco."],[8,11,"Kaj se la Spirito de Tiu, kiu levis Jesuon el la mortintoj, loĝas en vi, tiam la Levinto de Kristo Jesuo el la mortintoj vivigos eĉ viajn mortajn korpojn per Sia Spirito, loĝanta en vi.","Kaj se la Spirito de Tiu, kiu levis Jesuon el la mortintoj, loĝas en vi, tiam la Levinto de Kristo Jesuo el la mortintoj vivigos eĉ viajn mortajn korpojn per Sia Spirito, loĝanta en vi."],[8,12,"Tial do, fratoj, ni estas ŝuldantoj, ne al la karno, por vivi laŭ la karno;","Tial do, fratoj, ni estas ŝuldantoj, ne al la karno, por vivi laŭ la karno;"],[8,13,"ĉar se vi vivas laŭ la karno, vi mortos; sed se per la spirito vi malvivigas la farojn de la korpo, vi vivos.","ĉar se vi vivas laŭ la karno, vi mortos; sed se per la spirito vi malvivigas la farojn de la korpo, vi vivos."],[8,14,"Ĉar ĉiuj, kiuj estas kondukataj de la Spirito de Dio, estas filoj de Dio.","Ĉar ĉiuj, kiuj estas kondukataj de la Spirito de Dio, estas filoj de Dio."],[8,15,"Ĉar vi ne ricevis la spiriton de sklaveco denove al timo; sed vi ricevis la spiriton de adopto, per kiu ni krias: Aba, Patro.","Ĉar vi ne ricevis la spiriton de sklaveco denove al timo; sed vi ricevis la spiriton de adopto, per kiu ni krias: Aba, Patro."],[8,16,"La Spirito mem kunatestas kun nia spirito, ke ni estas idoj de Dio;","La Spirito mem kunatestas kun nia spirito, ke ni estas idoj de Dio;"],[8,17,"kaj se idoj, tial heredantoj, heredantoj de Dio, kunheredantoj kun Kristo, se vere ni suferas kun li, por ke ni estu glorataj kun li.","kaj se idoj, tial heredantoj, heredantoj de Dio, kunheredantoj kun Kristo, se vere ni suferas kun li, por ke ni estu glorataj kun li."],[8,18,"Ĉar mi kalkulas, ke la suferoj de la nuna tempo ne indas komparon kun la gloro, kiu estas malkaŝota al ni.","Ĉar mi kalkulas, ke la suferoj de la nuna tempo ne indas komparon kun la gloro, kiu estas malkaŝota al ni."],[8,19,"Ĉar la fervora sopiro de la kreitaro atendas la malkaŝon de la filoj de Dio.","Ĉar la fervora sopiro de la kreitaro atendas la malkaŝon de la filoj de Dio."],[8,20,"Ĉar la kreitaro subiĝis sub la vanecon, ne volonte, sed, pro la subiganto, kun espero,","Ĉar la kreitaro subiĝis sub la vanecon, ne volonte, sed, pro la subiganto, kun espero,"],[8,21,"ke la kreitaro mem ankaŭ liberiĝos el la sklaveco de pereo en la liberecon de la gloro de la idoj de Dio.","ke la kreitaro mem ankaŭ liberiĝos el la sklaveco de pereo en la liberecon de la gloro de la idoj de Dio."],[8,22,"Ĉar ni scias, ke la tuta kreitaro kune ĝemas kaj naskodoloras ĝis nun.","Ĉar ni scias, ke la tuta kreitaro kune ĝemas kaj naskodoloras ĝis nun."],[8,23,"Kaj krom tio, ni mem, kiuj havas la unuaaĵon de la Spirito, ĝemas en ni, atendante nian adopton, nome la elaĉeton de nia korpo.","Kaj krom tio, ni mem, kiuj havas la unuaaĵon de la Spirito, ĝemas en ni, atendante nian adopton, nome la elaĉeton de nia korpo."],[8,24,"Ĉar per espero ni estas savitaj; sed la espero, kiu estas vidata, ne estas espero; ĉar kiu esperas al tio, kion li vidas?","Ĉar per espero ni estas savitaj; sed la espero, kiu estas vidata, ne estas espero; ĉar kiu esperas al tio, kion li vidas?"],[8,25,"Sed, se ni esperas al tio, kion ni ne vidas, tiam ni ĝin atendas pacience.","Sed, se ni esperas al tio, kion ni ne vidas, tiam ni ĝin atendas pacience."],[8,26,"Kaj tiel same la Spirito ankaŭ helpas nian malfortecon; ĉar ni ne scias, kiel preĝi dece, sed la Spirito mem propetadas por ni per ĝemoj neeldireblaj;","Kaj tiel same la Spirito ankaŭ helpas nian malfortecon; ĉar ni ne scias, kiel preĝi dece, sed la Spirito mem propetadas por ni per ĝemoj neeldireblaj;"],[8,27,"kaj Tiu, kiu esploras la korojn, scias, kio estas la penso de la Spirito, ĉar li propetadas por la sanktuloj laŭ la volo de Dio.","kaj Tiu, kiu esploras la korojn, scias, kio estas la penso de la Spirito, ĉar li propetadas por la sanktuloj laŭ la volo de Dio."],[8,28,"Kaj ni scias, ke por tiuj, kiuj amas Dion, por tiuj, kiuj estas vokitaj laŭ Lia intenco, ĉio kunlaboras al bono.","Kaj ni scias, ke por tiuj, kiuj amas Dion, por tiuj, kiuj estas vokitaj laŭ Lia intenco, ĉio kunlaboras al bono."],[8,29,"Ĉar kiujn Li antaŭkonis, tiujn Li antaŭdifinis kiel konformajn al la bildo de Lia Filo, por ke ĉi tiu estu la unuenaskita inter multaj fratoj;","Ĉar kiujn Li antaŭkonis, tiujn Li antaŭdifinis kiel konformajn al la bildo de Lia Filo, por ke ĉi tiu estu la unuenaskita inter multaj fratoj;"],[8,30,"kaj kiujn Li antaŭdifinis, tiujn Li ankaŭ vokis; kaj kiujn Li vokis, tiujn Li ankaŭ justigis; kaj kiujn Li justigis, tiujn Li ankaŭ gloris.","kaj kiujn Li antaŭdifinis, tiujn Li ankaŭ vokis; kaj kiujn Li vokis, tiujn Li ankaŭ justigis; kaj kiujn Li justigis, tiujn Li ankaŭ gloris."],[8,31,"Kion do ni diru pri ĉi tio? Se Dio estas por ni, kiu estas kontraŭ ni?","Kion do ni diru pri ĉi tio? Se Dio estas por ni, kiu estas kontraŭ ni?"],[8,32,"Ĉu Tiu, kiu ne indulgis Sian propran Filon, sed fordonis lin por ni ĉiuj, ne donos al ni libere ĉion kun li?","Ĉu Tiu, kiu ne indulgis Sian propran Filon, sed fordonis lin por ni ĉiuj, ne donos al ni libere ĉion kun li?"],[8,33,"Kiu akuzos la elektitojn de Dio? Dio estas la justiganto;","Kiu akuzos la elektitojn de Dio? Dio estas la justiganto;"],[8,34,"kiu estas la kondamnanto? Kristo estas tiu, kiu mortis, sed leviĝis el la mortintoj, kiu estas dekstre de Dio, kaj ankaŭ propetadas por ni.","kiu estas la kondamnanto? Kristo estas tiu, kiu mortis, sed leviĝis el la mortintoj, kiu estas dekstre de Dio, kaj ankaŭ propetadas por ni."],[8,35,"Kiu apartigos nin de la amo de Kristo? ĉu aflikto, aŭ turmento, aŭ persekutado, aŭ malsato, aŭ nudeco, aŭ danĝero, aŭ glavo?","Kiu apartigos nin de la amo de Kristo? ĉu aflikto, aŭ turmento, aŭ persekutado, aŭ malsato, aŭ nudeco, aŭ danĝero, aŭ glavo?"],[8,36,"Kiel estas skribite: Pro Vi ni estas mortigataj ĉiutage; Oni rigardas nin kiel ŝafojn por buĉo.","Kiel estas skribite: Pro Vi ni estas mortigataj ĉiutage; Oni rigardas nin kiel ŝafojn por buĉo."],[8,37,"Sed en ĉio tio ni supervenkas per tiu, kiu nin amis.","Sed en ĉio tio ni supervenkas per tiu, kiu nin amis."],[8,38,"Ĉar mi konvinkiĝis, ke nek morto, nek vivo, nek anĝeloj, nek aŭtoritatoj, nek estantaĵoj, nek estontaĵoj, nek potencoj,","Ĉar mi konvinkiĝis, ke nek morto, nek vivo, nek anĝeloj, nek aŭtoritatoj, nek estantaĵoj, nek estontaĵoj, nek potencoj,"],[8,39,"nek alteco, nek profundeco, nek iu alia kreitaĵo povos apartigi nin de la amo de Dio, kiu estas en Kristo Jesuo, nia Sinjoro.","nek alteco, nek profundeco, nek iu alia kreitaĵo povos apartigi nin de la amo de Dio, kiu estas en Kristo Jesuo, nia Sinjoro."],[9,1,"Mi diras la veron en Kristo, mi ne mensogas, kaj mia konscienco atestas kun mi per la Sankta Spirito,","Mi diras la veron en Kristo, mi ne mensogas, kaj mia konscienco atestas kun mi per la Sankta Spirito,"],[9,2,"ke mi havas grandan malĝojon kaj senĉesan doloron en la koro.","ke mi havas grandan malĝojon kaj senĉesan doloron en la koro."],[9,3,"Ĉar mi volus, ke mi estu anatemita for de Kristo por miaj fratoj, miaj parencoj laŭ la karno;","Ĉar mi volus, ke mi estu anatemita for de Kristo por miaj fratoj, miaj parencoj laŭ la karno;"],[9,4,"kiuj estas Izraelidoj, kies estas la adopto kaj la gloro kaj la interligoj kaj la leĝdono kaj la Diservo kaj la promesoj;","kiuj estas Izraelidoj, kies estas la adopto kaj la gloro kaj la interligoj kaj la leĝdono kaj la Diservo kaj la promesoj;"],[9,5,"kies estas la patroj, kaj el kiuj laŭ la karno estas Kristo, kiu estas super ĉiuj, Dio benata eterne. Amen.","kies estas la patroj, kaj el kiuj laŭ la karno estas Kristo, kiu estas super ĉiuj, Dio benata eterne. Amen."],[9,6,"Sed la afero ne estas, kvazaŭ la vorto de Dio estus neniiĝinta. Ĉar ne ĉiuj estas Izrael, kiuj estas el Izrael;","Sed la afero ne estas, kvazaŭ la vorto de Dio estus neniiĝinta. Ĉar ne ĉiuj estas Izrael, kiuj estas el Izrael;"],[9,7,"nek, ĉar ili estas idoj de Abraham, ĉiuj estas filoj, sed: Per Isaak oni nomos vian idaron.","nek, ĉar ili estas idoj de Abraham, ĉiuj estas filoj, sed: Per Isaak oni nomos vian idaron."],[9,8,"Tio estas, ne la filoj de la karno estas la filoj de Dio, sed la filoj de la promeso estas rigardataj kiel idaro.","Tio estas, ne la filoj de la karno estas la filoj de Dio, sed la filoj de la promeso estas rigardataj kiel idaro."],[9,9,"Ĉar jen estas la vorto de promeso: En la sama jartempo Mi venos, kaj estos filo ĉe Sara.","Ĉar jen estas la vorto de promeso: En la sama jartempo Mi venos, kaj estos filo ĉe Sara."],[9,10,"Kaj plue, kiam Rebeka ankaŭ gravediĝis per unu, nia patro Isaak","Kaj plue, kiam Rebeka ankaŭ gravediĝis per unu, nia patro Isaak"],[9,11,"(ĉar la infanoj ankoraŭ ne naskiĝis, nek faris ion bonan aŭ malbonan, por ke la intenco de Dio restu laŭ elekto, ne pro faroj, sed pro la alvokanto),","(ĉar la infanoj ankoraŭ ne naskiĝis, nek faris ion bonan aŭ malbonan, por ke la intenco de Dio restu laŭ elekto, ne pro faroj, sed pro la alvokanto),"],[9,12,"estis dirite al ŝi: La pli granda servos la malpli grandan.","estis dirite al ŝi: La pli granda servos la malpli grandan."],[9,13,"Kiel estas skribite: Mi ekamis Jakobon, sed Esavon Mi malamis.","Kiel estas skribite: Mi ekamis Jakobon, sed Esavon Mi malamis."],[9,14,"Kion do ni diru? Ĉu estas maljusteco ĉe Dio? Nepre ne!","Kion do ni diru? Ĉu estas maljusteco ĉe Dio? Nepre ne!"],[9,15,"Ĉar Li diris al Moseo: Mi favorkoros tiun, kiun Mi favorkoros, kaj Mi kompatos tiun, kiun Mi kompatos.","Ĉar Li diris al Moseo: Mi favorkoros tiun, kiun Mi favorkoros, kaj Mi kompatos tiun, kiun Mi kompatos."],[9,16,"Tial do tio apartenas ne al tiu, kiu volas, nek al tiu, kiu kuras, sed al Dio, kiu kompatas.","Tial do tio apartenas ne al tiu, kiu volas, nek al tiu, kiu kuras, sed al Dio, kiu kompatas."],[9,17,"Ĉar la Skribo diras al Faraono: Nur por tio Mi vin konservis, ke Mi montru sur vi Mian forton, kaj por ke oni rakontu pri Mia nomo sur la tuta tero.","Ĉar la Skribo diras al Faraono: Nur por tio Mi vin konservis, ke Mi montru sur vi Mian forton, kaj por ke oni rakontu pri Mia nomo sur la tuta tero."],[9,18,"Tial Li favorkoras ĉiun, kiun Li volas; kaj ĉiun, kiun Li volas, Li obstinigas.","Tial Li favorkoras ĉiun, kiun Li volas; kaj ĉiun, kiun Li volas, Li obstinigas."],[9,19,"Vi do diras al mi: Kial Li ankoraŭ riproĉas? Ĉar kiu rezistas al Lia volo?","Vi do diras al mi: Kial Li ankoraŭ riproĉas? Ĉar kiu rezistas al Lia volo?"],[9,20,"Sed antaŭ tio, ho viro, kiu vi estas, ke vi respondas kontraŭ Dio? Ĉu faritaĵo diros al sia farinto: Kial vi faris min tiel?","Sed antaŭ tio, ho viro, kiu vi estas, ke vi respondas kontraŭ Dio? Ĉu faritaĵo diros al sia farinto: Kial vi faris min tiel?"],[9,21,"Aŭ ĉu la potfaristo ne havas rajton super la argilo, el la sama maso fari jen vazon por honoro, kaj jen vazon por malhonoro?","Aŭ ĉu la potfaristo ne havas rajton super la argilo, el la sama maso fari jen vazon por honoro, kaj jen vazon por malhonoro?"],[9,22,"Kiel do, se Dio, volante elmontri Sian koleron kaj konatigi Sian potencon, toleris kun plena pacienco vazojn de kolero, taŭgajn por pereo;","Kiel do, se Dio, volante elmontri Sian koleron kaj konatigi Sian potencon, toleris kun plena pacienco vazojn de kolero, taŭgajn por pereo;"],[9,23,"kaj por ke Li konatigu la riĉon de Sia gloro sur vazojn de favoro, kiujn Li antaŭe pretigis por gloro,","kaj por ke Li konatigu la riĉon de Sia gloro sur vazojn de favoro, kiujn Li antaŭe pretigis por gloro,"],[9,24,"nome nin, kiujn Li ankaŭ vokis, ne nur el la Judoj, sed ankaŭ el la nacianoj?","nome nin, kiujn Li ankaŭ vokis, ne nur el la Judoj, sed ankaŭ el la nacianoj?"],[9,25,"Kiel Li diras ankaŭ en Hoŝea: La popolon ne Mian Mi nomos Mia popolo, Kaj la neamatinon amatino.","Kiel Li diras ankaŭ en Hoŝea: La popolon ne Mian Mi nomos Mia popolo, Kaj la neamatinon amatino."],[9,26,"Kaj sur la sama loko, kie estis al ili dirite: Vi ne estas Mia popolo, Tie oni nomos ilin infanoj de la vivanta Dio.","Kaj sur la sama loko, kie estis al ili dirite: Vi ne estas Mia popolo, Tie oni nomos ilin infanoj de la vivanta Dio."],[9,27,"Kaj Jesaja krias pri Izrael: Se la nombro de la filoj de Izrael eĉ estos kiel la apudmara sablo, la restintoj saviĝos;","Kaj Jesaja krias pri Izrael: Se la nombro de la filoj de Izrael eĉ estos kiel la apudmara sablo, la restintoj saviĝos;"],[9,28,"ĉar la Sinjoro efektivigos Sian vorton en la mondo, akcelante kaj tranĉe mallongigante ĝin.","ĉar la Sinjoro efektivigos Sian vorton en la mondo, akcelante kaj tranĉe mallongigante ĝin."],[9,29,"Kiel Jesaja diris antaŭe: Se la Eternulo Cebaot ne lasus al ni restaĵon, Ni fariĝus kiel Sodom, ni similiĝus al Gomora.","Kiel Jesaja diris antaŭe: Se la Eternulo Cebaot ne lasus al ni restaĵon, Ni fariĝus kiel Sodom, ni similiĝus al Gomora."],[9,30,"Kion do ni diru? Ke la nacianoj, kiuj ne sekvis justecon, atingis justecon, la justecon, kiu estas el fido;","Kion do ni diru? Ke la nacianoj, kiuj ne sekvis justecon, atingis justecon, la justecon, kiu estas el fido;"],[9,31,"sed ke Izrael, sekvante la leĝon de justeco, ne atingis tiun leĝon.","sed ke Izrael, sekvante la leĝon de justeco, ne atingis tiun leĝon."],[9,32,"Kial? Ĉar ili sekvis ĝin ne per fido, sed kvazaŭ per faroj. Ili falpuŝiĝis ĉe la ŝtono de falpuŝiĝo;","Kial? Ĉar ili sekvis ĝin ne per fido, sed kvazaŭ per faroj. Ili falpuŝiĝis ĉe la ŝtono de falpuŝiĝo;"],[9,33,"kiel estas skribite: Jen Mi kuŝigas en Cion ŝtonon de falpuŝiĝo kaj rokon de alfrapiĝo; Kaj tiu, kiu fidos al li, ne estos hontigita.","kiel estas skribite: Jen Mi kuŝigas en Cion ŝtonon de falpuŝiĝo kaj rokon de alfrapiĝo; Kaj tiu, kiu fidos al li, ne estos hontigita."],[10,1,"Fratoj, la deziro de mia koro kaj mia preĝo al Dio pri ili estas por ilia savado.","Fratoj, la deziro de mia koro kaj mia preĝo al Dio pri ili estas por ilia savado."],[10,2,"Ĉar mi atestas pri ili, ke ili havas fervoron al Dio, sed ne laŭ scio.","Ĉar mi atestas pri ili, ke ili havas fervoron al Dio, sed ne laŭ scio."],[10,3,"Ĉar nesciante la justecon de Dio, kaj penante starigi sian propran justecon, ili ne subiĝis al la justeco de Dio.","Ĉar nesciante la justecon de Dio, kaj penante starigi sian propran justecon, ili ne subiĝis al la justeco de Dio."],[10,4,"Ĉar Kristo estas la fino de la leĝo por justeco por ĉiu, kiu kredas.","Ĉar Kristo estas la fino de la leĝo por justeco por ĉiu, kiu kredas."],[10,5,"Ĉar Moseo skribis, ke tiu, kiu plenumas la justecon de la leĝo, vivos per ĝi.","Ĉar Moseo skribis, ke tiu, kiu plenumas la justecon de la leĝo, vivos per ĝi."],[10,6,"Sed la justeco, kiu estas el fido, diras jene: Ne diru en via koro: Kiu suprenirus en la ĉielon? (tio estas, por malsuprenigi Kriston),","Sed la justeco, kiu estas el fido, diras jene: Ne diru en via koro: Kiu suprenirus en la ĉielon? (tio estas, por malsuprenigi Kriston),"],[10,7,"nek: Kiu malsuprenirus en la abismon? (tio estas, por suprenkonduki Kriston el la mortintoj).","nek: Kiu malsuprenirus en la abismon? (tio estas, por suprenkonduki Kriston el la mortintoj)."],[10,8,"Sed kion ĝi diras? La afero estas proksime de vi, en via buŝo kaj en via koro; tio estas, la vorto de fido, kiun ni predikas;","Sed kion ĝi diras? La afero estas proksime de vi, en via buŝo kaj en via koro; tio estas, la vorto de fido, kiun ni predikas;"],[10,9,"ĉar se vi per via buŝo konfesas Jesuon Sinjoro, kaj kredas en via koro, ke Dio lin levis el la mortintoj, vi saviĝos;","ĉar se vi per via buŝo konfesas Jesuon Sinjoro, kaj kredas en via koro, ke Dio lin levis el la mortintoj, vi saviĝos;"],[10,10,"ĉar per la koro la homo kredas ĝis justeco, kaj per la buŝo konfesas ĝis savo.","ĉar per la koro la homo kredas ĝis justeco, kaj per la buŝo konfesas ĝis savo."],[10,11,"Ĉar la Skribo diras: Ĉiu, kiu fidas al li, ne estos hontigita.","Ĉar la Skribo diras: Ĉiu, kiu fidas al li, ne estos hontigita."],[10,12,"Ĉar estas nenia diferencigo inter Judo kaj Greko, ĉar unu sama estas Sinjoro de ĉiuj, kaj estas riĉa por ĉiuj, kiuj lin vokas;","Ĉar estas nenia diferencigo inter Judo kaj Greko, ĉar unu sama estas Sinjoro de ĉiuj, kaj estas riĉa por ĉiuj, kiuj lin vokas;"],[10,13,"ĉar: Ĉiu, kiu vokos la nomon de la Eternulo, saviĝos.","ĉar: Ĉiu, kiu vokos la nomon de la Eternulo, saviĝos."],[10,14,"Kiel do ili vokos Tiun, al kiu ili ne kredis? kaj kiel ili kredos al Tiu, pri kiu ili ne aŭdis? kaj kiel ili aŭdos sen predikanto?","Kiel do ili vokos Tiun, al kiu ili ne kredis? kaj kiel ili kredos al Tiu, pri kiu ili ne aŭdis? kaj kiel ili aŭdos sen predikanto?"],[10,15,"kaj kiel oni predikos, se ili ne estos senditaj? kiel estas skribite: Kiel ĉarmaj estas la piedoj de la anoncantoj de la evangelio de bono!","kaj kiel oni predikos, se ili ne estos senditaj? kiel estas skribite: Kiel ĉarmaj estas la piedoj de la anoncantoj de la evangelio de bono!"],[10,16,"Sed ne ĉiuj aŭskultis la evangelion. Ĉar Jesuo diris: Ho Eternulo! kiu kredus al tio, kion ni aŭdis?","Sed ne ĉiuj aŭskultis la evangelion. Ĉar Jesuo diris: Ho Eternulo! kiu kredus al tio, kion ni aŭdis?"],[10,17,"La fido venas do per aŭdado, kaj aŭdado per la vorto de Kristo.","La fido venas do per aŭdado, kaj aŭdado per la vorto de Kristo."],[10,18,"Sed mi diras: Ĉu ili ne aŭdis? Certe: Tra la tuta mondo iris ilia sono, Kaj ĝis la finoj de la tero iris iliaj vortoj.","Sed mi diras: Ĉu ili ne aŭdis? Certe: Tra la tuta mondo iris ilia sono, Kaj ĝis la finoj de la tero iris iliaj vortoj."],[10,19,"Sed mi diras: Ĉu Izrael ne sciis? Unue Moseo diris: Mi incitos vin per ne-popolo, Per popolo malnobla Mi vin kolerigos.","Sed mi diras: Ĉu Izrael ne sciis? Unue Moseo diris: Mi incitos vin per ne-popolo, Per popolo malnobla Mi vin kolerigos."],[10,20,"Kaj Jesaja estis tre kuraĝa, kaj diris: Mi estas trovebla por tiuj, kiuj Min ne serĉis; Mi montris Min al tiuj, kiuj pri Mi ne demandis.","Kaj Jesaja estis tre kuraĝa, kaj diris: Mi estas trovebla por tiuj, kiuj Min ne serĉis; Mi montris Min al tiuj, kiuj pri Mi ne demandis."],[10,21,"Sed pri Izrael li diris: Ĉiutage Mi etendis Miajn manojn al popolo malobeema kaj obstina.","Sed pri Izrael li diris: Ĉiutage Mi etendis Miajn manojn al popolo malobeema kaj obstina."],[11,1,"Mi do diras: Ĉu Dio forpuŝis Sian popolon? Nepre ne! Ĉar ankaŭ mi estas Izraelido, el la idoj de Abraham, el la tribo de Benjamen.","Mi do diras: Ĉu Dio forpuŝis Sian popolon? Nepre ne! Ĉar ankaŭ mi estas Izraelido, el la idoj de Abraham, el la tribo de Benjamen."],[11,2,"Dio ne forpuŝis Sian popolon, kiun Li antaŭkonis. Aŭ ĉu vi ne scias, kion la Skribo diras pri Elija? kiel li pledis ĉe Dio kontraŭ Izrael:","Dio ne forpuŝis Sian popolon, kiun Li antaŭkonis. Aŭ ĉu vi ne scias, kion la Skribo diras pri Elija? kiel li pledis ĉe Dio kontraŭ Izrael:"],[11,3,"Ho Eternulo, oni mortigis Viajn profetojn, detruis Viajn altarojn; kaj mi sola restis, kaj oni serĉas mian animon.","Ho Eternulo, oni mortigis Viajn profetojn, detruis Viajn altarojn; kaj mi sola restis, kaj oni serĉas mian animon."],[11,4,"Sed kion diras al li la orakolo de Dio? Mi restigis por Mi sep mil virojn, kies genuoj ne fleksiĝis antaŭ Baal.","Sed kion diras al li la orakolo de Dio? Mi restigis por Mi sep mil virojn, kies genuoj ne fleksiĝis antaŭ Baal."],[11,5,"Tiel same do estas ankaŭ nuntempe restaĵo laŭ la elektado de graco.","Tiel same do estas ankaŭ nuntempe restaĵo laŭ la elektado de graco."],[11,6,"Sed se per graco, ne plu el faroj; alie graco jam ne estus graco.","Sed se per graco, ne plu el faroj; alie graco jam ne estus graco."],[11,7,"Kion do? Kion Izrael serĉadas, tion li ne atingis, sed la elektitaro atingis ĝin, kaj la restaĵo estis obstinigita;","Kion do? Kion Izrael serĉadas, tion li ne atingis, sed la elektitaro atingis ĝin, kaj la restaĵo estis obstinigita;"],[11,8,"kiel estas skribite: Dio donis al ili spiriton de profunda dormo, okulojn, por ke ili ne vidu, kaj orelojn, por ke ili ne aŭdu, ĝis la nuna tago.","kiel estas skribite: Dio donis al ili spiriton de profunda dormo, okulojn, por ke ili ne vidu, kaj orelojn, por ke ili ne aŭdu, ĝis la nuna tago."],[11,9,"Kaj David diris: Ilia tablo fariĝu por ili reto kaj kaptilo Kaj falpuŝilo kaj repago;","Kaj David diris: Ilia tablo fariĝu por ili reto kaj kaptilo Kaj falpuŝilo kaj repago;"],[11,10,"Mallumiĝu iliaj okuloj, ke ili ne vidu; Kaj iliajn lumbojn malfortigu por ĉiam.","Mallumiĝu iliaj okuloj, ke ili ne vidu; Kaj iliajn lumbojn malfortigu por ĉiam."],[11,11,"Mi do diras: Ĉu ili falpuŝiĝis, por ke ili falu? Nepre ne! sed per ilia eraro venis savo al la nacianoj, por ĵaluzigi ilin.","Mi do diras: Ĉu ili falpuŝiĝis, por ke ili falu? Nepre ne! sed per ilia eraro venis savo al la nacianoj, por ĵaluzigi ilin."],[11,12,"Se do ilia eraro riĉigis la mondon, kaj ilia perdo estas la gajno de la nacianoj, kiom pli ilia pleneco?","Se do ilia eraro riĉigis la mondon, kaj ilia perdo estas la gajno de la nacianoj, kiom pli ilia pleneco?"],[11,13,"Sed mi parolas al vi, nacianoj. Laŭ tio, kiom mi estas apostolo al nacianoj, mi gloras mian servadon;","Sed mi parolas al vi, nacianoj. Laŭ tio, kiom mi estas apostolo al nacianoj, mi gloras mian servadon;"],[11,14,"se nur mi iel povos ĵaluzigi tiujn, kiuj estas mia karno, kaj savi kelkajn el ili.","se nur mi iel povos ĵaluzigi tiujn, kiuj estas mia karno, kaj savi kelkajn el ili."],[11,15,"Ĉar se la forĵetado de ili estas la repacigo de la mondo, kio estos la akcepto de ili, se ne vivo el la mortintoj?","Ĉar se la forĵetado de ili estas la repacigo de la mondo, kio estos la akcepto de ili, se ne vivo el la mortintoj?"],[11,16,"Kaj se la unuaaĵo estas sankta, la maso ankaŭ estas sankta; kaj se la radiko estas sankta, la branĉoj ankaŭ estas sanktaj.","Kaj se la unuaaĵo estas sankta, la maso ankaŭ estas sankta; kaj se la radiko estas sankta, la branĉoj ankaŭ estas sanktaj."],[11,17,"Sed se kelkaj el la branĉoj derompiĝis, kaj vi, estante sovaĝa olivarbo, engreftiĝis inter ili kaj fariĝis partoprenanto en la radiko kaj graso de la olivarbo,","Sed se kelkaj el la branĉoj derompiĝis, kaj vi, estante sovaĝa olivarbo, engreftiĝis inter ili kaj fariĝis partoprenanto en la radiko kaj graso de la olivarbo,"],[11,18,"ne fieru super la branĉoj; sed se vi fieras, ne vi portas la radikon, sed la radiko portas vin.","ne fieru super la branĉoj; sed se vi fieras, ne vi portas la radikon, sed la radiko portas vin."],[11,19,"Vi do diros: Branĉoj estis derompitaj, por ke mi estu engreftita.","Vi do diros: Branĉoj estis derompitaj, por ke mi estu engreftita."],[11,20,"Bone; pro nekredemeco ili estis derompitaj, kaj vi staras per via fido. Ne tenu vin alte, sed timu;","Bone; pro nekredemeco ili estis derompitaj, kaj vi staras per via fido. Ne tenu vin alte, sed timu;"],[11,21,"ĉar se Dio ne indulgis la naturajn branĉojn, Li ankaŭ vin ne indulgos.","ĉar se Dio ne indulgis la naturajn branĉojn, Li ankaŭ vin ne indulgos."],[11,22,"Vidu do la bonecon kaj severecon de Dio: al la falintoj severecon, sed al vi bonecon, se vi restados en Lia boneco; alie vi ankaŭ detranĉiĝos.","Vidu do la bonecon kaj severecon de Dio: al la falintoj severecon, sed al vi bonecon, se vi restados en Lia boneco; alie vi ankaŭ detranĉiĝos."],[11,23,"Kaj ili ankaŭ, se ili ne restados en sia nekredemeco, engreftiĝos; ĉar Dio povas reengrefti ilin.","Kaj ili ankaŭ, se ili ne restados en sia nekredemeco, engreftiĝos; ĉar Dio povas reengrefti ilin."],[11,24,"Ĉar se vi eltranĉiĝis el tio, kio estas nature sovaĝa olivarbo, kaj kontraŭnature engreftiĝis en bonan olivarbon, kiom pli ĉi tiuj, kiuj estas la naturaj branĉoj, engreftiĝos en sian propran olivarbon?","Ĉar se vi eltranĉiĝis el tio, kio estas nature sovaĝa olivarbo, kaj kontraŭnature engreftiĝis en bonan olivarbon, kiom pli ĉi tiuj, kiuj estas la naturaj branĉoj, engreftiĝos en sian propran olivarbon?"],[11,25,"Ĉar mi ne volas, fratoj, ke vi ne sciu ĉi tiun misteron, por ke vi ne opiniu vin saĝaj, ke laŭparta obstiniĝo okazis al Izrael, ĝis la pleneco de la nacianoj envenos;","Ĉar mi ne volas, fratoj, ke vi ne sciu ĉi tiun misteron, por ke vi ne opiniu vin saĝaj, ke laŭparta obstiniĝo okazis al Izrael, ĝis la pleneco de la nacianoj envenos;"],[11,26,"kaj tiamaniere la tuta Izrael saviĝos, kiel estas skribite: El Cion venos la Liberiganto; Li deturnos de Jakob malpiecon;","kaj tiamaniere la tuta Izrael saviĝos, kiel estas skribite: El Cion venos la Liberiganto; Li deturnos de Jakob malpiecon;"],[11,27,"Kaj ĉi tio estos Mia interligo kun ili, Kiam Mi forigos iliajn pekojn.","Kaj ĉi tio estos Mia interligo kun ili, Kiam Mi forigos iliajn pekojn."],[11,28,"Rilate al la evangelio, ili estas malamikoj pro vi; sed rilate al la elekto, ili estas amataj pro la patroj.","Rilate al la evangelio, ili estas malamikoj pro vi; sed rilate al la elekto, ili estas amataj pro la patroj."],[11,29,"Ĉar la donacoj kaj la vokado de Dio estas nerevokeblaj.","Ĉar la donacoj kaj la vokado de Dio estas nerevokeblaj."],[11,30,"Ĉar kiel vi iam estis malobeemaj al Dio, sed jam ricevis kompaton per ilia malobeo,","Ĉar kiel vi iam estis malobeemaj al Dio, sed jam ricevis kompaton per ilia malobeo,"],[11,31,"tiel same ankaŭ ĉi tiuj jam malobeis, por ke, per la kompato montrita al vi, ili ankaŭ nun ricevu kompaton.","tiel same ankaŭ ĉi tiuj jam malobeis, por ke, per la kompato montrita al vi, ili ankaŭ nun ricevu kompaton."],[11,32,"Ĉar Dio kunŝlosis ĉiujn en malobeo, por ke Li kompatu ĉiujn.","Ĉar Dio kunŝlosis ĉiujn en malobeo, por ke Li kompatu ĉiujn."],[11,33,"Ho, profundo de riĉeco kaj saĝeco kaj scio de Dio! kiel neesploreblaj estas Liaj juĝoj, kaj nesekveblaj Liaj vojoj!","Ho, profundo de riĉeco kaj saĝeco kaj scio de Dio! kiel neesploreblaj estas Liaj juĝoj, kaj nesekveblaj Liaj vojoj!"],[11,34,"Ĉar kiu sciis la spiriton de la Eternulo? aŭ kiu estis Lia konsilanto?","Ĉar kiu sciis la spiriton de la Eternulo? aŭ kiu estis Lia konsilanto?"],[11,35,"aŭ kiu antaŭe al Li donis ion, poste redonotan al li?","aŭ kiu antaŭe al Li donis ion, poste redonotan al li?"],[11,36,"Ĉar el Li kaj per Li kaj al Li estas ĉio. Al Li estu la gloro por ĉiam. Amen.","Ĉar el Li kaj per Li kaj al Li estas ĉio. Al Li estu la gloro por ĉiam. Amen."],[12,1,"Mi do vin petas, fratoj, pro la kompatoj de Dio, ke vi prezentu viajn korpojn kiel vivantan oferon, sanktan, plaĉantan al Dio, kio estas via racia servo.","Mi do vin petas, fratoj, pro la kompatoj de Dio, ke vi prezentu viajn korpojn kiel vivantan oferon, sanktan, plaĉantan al Dio, kio estas via racia servo."],[12,2,"Kaj ne konformiĝu al ĉi tiu mondo; sed aliformiĝu per renovigado de via menso, por ke vi provu, kio estas la bona kaj aprobinda kaj perfekta volo de Dio.","Kaj ne konformiĝu al ĉi tiu mondo; sed aliformiĝu per renovigado de via menso, por ke vi provu, kio estas la bona kaj aprobinda kaj perfekta volo de Dio."],[12,3,"Ĉar mi diras al ĉiu el vi, per la graco al mi donita, ke li ne tro estimu sin, sed estimu sin kun modereco, laŭ mezuro de la fido, kiun Dio disdonis al ĉiu.","Ĉar mi diras al ĉiu el vi, per la graco al mi donita, ke li ne tro estimu sin, sed estimu sin kun modereco, laŭ mezuro de la fido, kiun Dio disdonis al ĉiu."],[12,4,"Ĉar kiel ni havas multajn membrojn en unu korpo, kaj ne ĉiuj membroj havas la saman funkcion,","Ĉar kiel ni havas multajn membrojn en unu korpo, kaj ne ĉiuj membroj havas la saman funkcion,"],[12,5,"tiel same ni multaj estas unu korpo en Kristo, kaj ĉiuj aparte membroj unu de alia.","tiel same ni multaj estas unu korpo en Kristo, kaj ĉiuj aparte membroj unu de alia."],[12,6,"Sed havante donacojn diversajn laŭ la graco donita al ni, ĉu profetadon, ni profetu laŭ la mezuro de nia fido;","Sed havante donacojn diversajn laŭ la graco donita al ni, ĉu profetadon, ni profetu laŭ la mezuro de nia fido;"],[12,7,"aŭ servadon, ni laboru en nia servado; aŭ instruanto, en sia instruado;","aŭ servadon, ni laboru en nia servado; aŭ instruanto, en sia instruado;"],[12,8,"aŭ admonanto, en sia admonado; la disdonanto agu malavare, la administranto kun diligenteco, la kompatanto kun ĝojo.","aŭ admonanto, en sia admonado; la disdonanto agu malavare, la administranto kun diligenteco, la kompatanto kun ĝojo."],[12,9,"Via amo estu sen hipokriteco. Abomenu tion, kio estas malbona; algluiĝu al la bona.","Via amo estu sen hipokriteco. Abomenu tion, kio estas malbona; algluiĝu al la bona."],[12,10,"En fratamo estu kore unuigitaj unu al alia, honore preferantaj unu la alian;","En fratamo estu kore unuigitaj unu al alia, honore preferantaj unu la alian;"],[12,11,"en diligenteco ne malviglaj, en spirito fervoraj, servantaj la Sinjoron;","en diligenteco ne malviglaj, en spirito fervoraj, servantaj la Sinjoron;"],[12,12,"en espero ĝojaj, en aflikto paciencaj, en preĝado persistaj;","en espero ĝojaj, en aflikto paciencaj, en preĝado persistaj;"],[12,13,"kotizantaj por la bezonoj de la sanktuloj, sekvantaj gastamecon.","kotizantaj por la bezonoj de la sanktuloj, sekvantaj gastamecon."],[12,14,"Benu tiujn, kiuj vin persekutas; benu, kaj ne malbenu.","Benu tiujn, kiuj vin persekutas; benu, kaj ne malbenu."],[12,15,"Ĝoju kun ĝojantoj, ploru kun plorantoj.","Ĝoju kun ĝojantoj, ploru kun plorantoj."],[12,16,"Estu simpatiaj unu al alia. Ne pripensadu altajn aferojn, sed klinadu vin al humilaj aferoj. Ne opiniu vin saĝaj.","Estu simpatiaj unu al alia. Ne pripensadu altajn aferojn, sed klinadu vin al humilaj aferoj. Ne opiniu vin saĝaj."],[12,17,"Redonu al neniu malbonon pro malbono. Celu aprobindaĵojn antaŭ ĉiuj homoj.","Redonu al neniu malbonon pro malbono. Celu aprobindaĵojn antaŭ ĉiuj homoj."],[12,18,"Se estos eble, restu pacaj viaparte kun ĉiuj homoj.","Se estos eble, restu pacaj viaparte kun ĉiuj homoj."],[12,19,"Ne venĝu vin, amataj, sed cedu lokon al kolero; ĉar estas skribite: Ĉe Mi estas venĝo, Mi repagos, diras la Sinjoro.","Ne venĝu vin, amataj, sed cedu lokon al kolero; ĉar estas skribite: Ĉe Mi estas venĝo, Mi repagos, diras la Sinjoro."],[12,20,"Sed se via malamiko malsatas, donu al li manĝi; se li soifas, donu al li trinki; ĉar tion farante, fajrajn karbojn vi kolektos sur lia kapo.","Sed se via malamiko malsatas, donu al li manĝi; se li soifas, donu al li trinki; ĉar tion farante, fajrajn karbojn vi kolektos sur lia kapo."],[12,21,"Ne venkiĝu de malbono, sed venku malbonon per bono.","Ne venkiĝu de malbono, sed venku malbonon per bono."],[13,1,"Ĉiu animo submetiĝu al la superaj aŭtoritatoj, ĉar ne ekzistas aŭtoritato, krom de Dio; kaj tiuj, kiuj ekzistas, estas starigitaj de Dio.","Ĉiu animo submetiĝu al la superaj aŭtoritatoj, ĉar ne ekzistas aŭtoritato, krom de Dio; kaj tiuj, kiuj ekzistas, estas starigitaj de Dio."],[13,2,"Tiu do, kiu kontraŭstaras al aŭtoritato, rezistas al la ordono de Dio; kaj tiuj, kiuj rezistas, ricevos juĝon.","Tiu do, kiu kontraŭstaras al aŭtoritato, rezistas al la ordono de Dio; kaj tiuj, kiuj rezistas, ricevos juĝon."],[13,3,"Ĉar regantoj estas teruraĵo ne al la bona agado, sed al la malbona. Ĉu vi volas ne timi aŭtoritatulon? faru bonon, kaj vi havos de li laŭdon;","Ĉar regantoj estas teruraĵo ne al la bona agado, sed al la malbona. Ĉu vi volas ne timi aŭtoritatulon? faru bonon, kaj vi havos de li laŭdon;"],[13,4,"ĉar li estas servanto de Dio al vi por bono. Sed timu, se vi faras malbonon; ĉar ne vane li portas la glavon, ĉar li estas servanto de Dio, venĝanto por kolero kontraŭ tiu, kiu faras malbonon.","ĉar li estas servanto de Dio al vi por bono. Sed timu, se vi faras malbonon; ĉar ne vane li portas la glavon, ĉar li estas servanto de Dio, venĝanto por kolero kontraŭ tiu, kiu faras malbonon."],[13,5,"Sekve estas necese submetiĝi, ne nur pro la kolero, sed ankaŭ pro konscienco.","Sekve estas necese submetiĝi, ne nur pro la kolero, sed ankaŭ pro konscienco."],[13,6,"Ĉar pro tio vi ankaŭ pagas tributon, ĉar ili estas servantoj de Dio, klopodantaj por ĉi tio mem.","Ĉar pro tio vi ankaŭ pagas tributon, ĉar ili estas servantoj de Dio, klopodantaj por ĉi tio mem."],[13,7,"Redonu ŝuldon al ĉiuj: tributon, al kiu tributo estas ŝuldata; imposton, al kiu imposto; timon, al kiu timo; honoron, al kiu honoro.","Redonu ŝuldon al ĉiuj: tributon, al kiu tributo estas ŝuldata; imposton, al kiu imposto; timon, al kiu timo; honoron, al kiu honoro."],[13,8,"Al neniu ŝuldu ion, krom la reciproka amo; ĉar amante sian proksimulon, oni plenumis la ceteran leĝon.","Al neniu ŝuldu ion, krom la reciproka amo; ĉar amante sian proksimulon, oni plenumis la ceteran leĝon."],[13,9,"Ĉar tio: Ne adultu, Ne mortigu, Ne ŝtelu, Ne deziru, kaj ĉiu alia ordono, estas resumitaj en la jena parolo: Amu vian proksimulon kiel vin mem.","Ĉar tio: Ne adultu, Ne mortigu, Ne ŝtelu, Ne deziru, kaj ĉiu alia ordono, estas resumitaj en la jena parolo: Amu vian proksimulon kiel vin mem."],[13,10,"Amo ne faras malbonon al proksimulo; amo do estas la plenumado de la leĝo.","Amo ne faras malbonon al proksimulo; amo do estas la plenumado de la leĝo."],[13,11,"Kaj tion faru, sciante la ĝustan tempon, ke nun estas la horo por leviĝo el dormo; ĉar nun nia savo estas pli proksima, ol kiam ni ekkredis.","Kaj tion faru, sciante la ĝustan tempon, ke nun estas la horo por leviĝo el dormo; ĉar nun nia savo estas pli proksima, ol kiam ni ekkredis."],[13,12,"La nokto jam finiĝas, kaj la tago alproksimiĝas; ni demetu do la farojn de mallumo kaj surmetu la armilojn de lumo.","La nokto jam finiĝas, kaj la tago alproksimiĝas; ni demetu do la farojn de mallumo kaj surmetu la armilojn de lumo."],[13,13,"Ni iradu dece, kiel en la tago, ne en diboĉado kaj drinkado, nek en volupto kaj senbrideco, nek en malpaco kaj ĵaluzo.","Ni iradu dece, kiel en la tago, ne en diboĉado kaj drinkado, nek en volupto kaj senbrideco, nek en malpaco kaj ĵaluzo."],[13,14,"Sed surmetu la Sinjoron Jesuo Kristo, kaj ne sekvu la intencojn de la karno al voluptoj.","Sed surmetu la Sinjoron Jesuo Kristo, kaj ne sekvu la intencojn de la karno al voluptoj."],[14,1,"Sed akceptu malfortulon en fido, tamen ne por dubaj disputadoj.","Sed akceptu malfortulon en fido, tamen ne por dubaj disputadoj."],[14,2,"Unu homo kredas, ke li povas ĉion manĝi; sed alia, estante malforta, manĝas legomojn.","Unu homo kredas, ke li povas ĉion manĝi; sed alia, estante malforta, manĝas legomojn."],[14,3,"Kiu manĝas, tiu ne malestimu tiun, kiu ne manĝas; kaj kiu ne manĝas, tiu ne juĝu tiun, kiu manĝas; ĉar Dio lin akceptis.","Kiu manĝas, tiu ne malestimu tiun, kiu ne manĝas; kaj kiu ne manĝas, tiu ne juĝu tiun, kiu manĝas; ĉar Dio lin akceptis."],[14,4,"Kiu estas vi, ke vi juĝas la servanton de alia? antaŭ sia propra sinjoro li staras aŭ falas. Li ja estos starigita, ĉar la Sinjoro povas lin starigi.","Kiu estas vi, ke vi juĝas la servanton de alia? antaŭ sia propra sinjoro li staras aŭ falas. Li ja estos starigita, ĉar la Sinjoro povas lin starigi."],[14,5,"Unu juĝas unu tagon pli alte ol alian, alia egale juĝas ĉiun tagon. Ĉiu homo konvinkiĝu en sia menso.","Unu juĝas unu tagon pli alte ol alian, alia egale juĝas ĉiun tagon. Ĉiu homo konvinkiĝu en sia menso."],[14,6,"Kiu observas la tagon, tiu observas ĝin al la Sinjoro; kaj la manĝanto manĝas al la Sinjoro, ĉar li dankas Dion; kaj la nemanĝanto nemanĝas al la Sinjoro, kaj li dankas Dion.","Kiu observas la tagon, tiu observas ĝin al la Sinjoro; kaj la manĝanto manĝas al la Sinjoro, ĉar li dankas Dion; kaj la nemanĝanto nemanĝas al la Sinjoro, kaj li dankas Dion."],[14,7,"Ĉar neniu el ni vivas al si mem, kaj neniu mortas al si mem.","Ĉar neniu el ni vivas al si mem, kaj neniu mortas al si mem."],[14,8,"Ĉar se ni vivas, ni vivas al la Sinjoro, kaj se ni mortas, ni mortas al la Sinjoro; ĉu ni vivas do, aŭ mortas, al la Sinjoro ni apartenas.","Ĉar se ni vivas, ni vivas al la Sinjoro, kaj se ni mortas, ni mortas al la Sinjoro; ĉu ni vivas do, aŭ mortas, al la Sinjoro ni apartenas."],[14,9,"Ĉar por tio Kristo mortis kaj viviĝis, por esti Sinjoro de la mortintoj kaj de la vivantoj.","Ĉar por tio Kristo mortis kaj viviĝis, por esti Sinjoro de la mortintoj kaj de la vivantoj."],[14,10,"Sed vi, kial vi juĝas vian fraton? kaj vi, kial vi malestimas vian fraton? ĉar ni ĉiuj staros antaŭ la tribunala seĝo de Dio.","Sed vi, kial vi juĝas vian fraton? kaj vi, kial vi malestimas vian fraton? ĉar ni ĉiuj staros antaŭ la tribunala seĝo de Dio."],[14,11,"Ĉar estas skribite: Kiel Mi vivas, diras la Eternulo, antaŭ Mi kliniĝos ĉiu genuo, Kaj ĉiu lango gloros Dion.","Ĉar estas skribite: Kiel Mi vivas, diras la Eternulo, antaŭ Mi kliniĝos ĉiu genuo, Kaj ĉiu lango gloros Dion."],[14,12,"Tial do ĉiu el ni respondos al Dio pri si mem.","Tial do ĉiu el ni respondos al Dio pri si mem."],[14,13,"Tial ni ne plu juĝu unu alian; sed prefere ni juĝu, ke neniu metu en la vojo de sia frato faligilon aŭ ian ofendilon.","Tial ni ne plu juĝu unu alian; sed prefere ni juĝu, ke neniu metu en la vojo de sia frato faligilon aŭ ian ofendilon."],[14,14,"Mi scias, kaj konvinkiĝis en la Sinjoro Jesuo, ke nenio estas malpura per si; sed por tiu, kiu opinias ion malpura, ĝi estas malpura.","Mi scias, kaj konvinkiĝis en la Sinjoro Jesuo, ke nenio estas malpura per si; sed por tiu, kiu opinias ion malpura, ĝi estas malpura."],[14,15,"Ĉar se pro manĝaĵo via frato ĉagreniĝas, vi jam ne iradas en amo. Ne pereigu per via manĝaĵo tiun, por kiu Kristo mortis.","Ĉar se pro manĝaĵo via frato ĉagreniĝas, vi jam ne iradas en amo. Ne pereigu per via manĝaĵo tiun, por kiu Kristo mortis."],[14,16,"Via bono do ne estu kalumniita;","Via bono do ne estu kalumniita;"],[14,17,"ĉar la regno de Dio estas ne manĝado kaj trinkado, sed justeco kaj paco kaj ĝojo en la Sankta Spirito.","ĉar la regno de Dio estas ne manĝado kaj trinkado, sed justeco kaj paco kaj ĝojo en la Sankta Spirito."],[14,18,"Ĉar tiu, kiu en tio servas Kriston, plaĉas al Dio, kaj estas aprobata de homoj.","Ĉar tiu, kiu en tio servas Kriston, plaĉas al Dio, kaj estas aprobata de homoj."],[14,19,"Ni do celu tion, kio apartenas al paco kaj al reciproka edifo.","Ni do celu tion, kio apartenas al paco kaj al reciproka edifo."],[14,20,"Ne detruu pro manĝaĵo la faron de Dio. Ĉio estas ja pura; sed estas malbone por tiu, kiu manĝas kun ofendo.","Ne detruu pro manĝaĵo la faron de Dio. Ĉio estas ja pura; sed estas malbone por tiu, kiu manĝas kun ofendo."],[14,21,"Estas bone ne manĝi viandon, nek trinki vinon, nek fari ion, per kio via frato ofendiĝas.","Estas bone ne manĝi viandon, nek trinki vinon, nek fari ion, per kio via frato ofendiĝas."],[14,22,"Tiun fidon, kiun vi havas, havu por vi mem antaŭ Dio. Feliĉa estas tiu, kiu ne juĝas sin mem per tio, kion li aprobas.","Tiun fidon, kiun vi havas, havu por vi mem antaŭ Dio. Feliĉa estas tiu, kiu ne juĝas sin mem per tio, kion li aprobas."],[14,23,"Sed tiu, kiu estas sendecida, estas kondamnita, se li manĝas; ĉar li manĝas ne el fido, kaj ĉio, kio ne estas el fido, estas peko.","Sed tiu, kiu estas sendecida, estas kondamnita, se li manĝas; ĉar li manĝas ne el fido, kaj ĉio, kio ne estas el fido, estas peko."],[15,1,"Ni, kiuj estas fortaj, devas porti la malfortaĵojn de la nefortaj, kaj ne plaĉi al ni mem.","Ni, kiuj estas fortaj, devas porti la malfortaĵojn de la nefortaj, kaj ne plaĉi al ni mem."],[15,2,"Ĉiu el ni plaĉu al sia proksimulo per tia bono, kia taŭgas, por edifi.","Ĉiu el ni plaĉu al sia proksimulo per tia bono, kia taŭgas, por edifi."],[15,3,"Ĉar Kristo ankaŭ ne plaĉis al si mem, sed, kiel estas skribite: La insultoj de Viaj insultantoj falis sur min.","Ĉar Kristo ankaŭ ne plaĉis al si mem, sed, kiel estas skribite: La insultoj de Viaj insultantoj falis sur min."],[15,4,"Ĉar ĉio, kio estas antaŭe skribita, estas skribita por nia instruado, por ke per pacienco kaj per konsolo de la Skriboj ni havu esperon.","Ĉar ĉio, kio estas antaŭe skribita, estas skribita por nia instruado, por ke per pacienco kaj per konsolo de la Skriboj ni havu esperon."],[15,5,"Kaj la Dio de pacienco kaj konsolo donu al vi, ke vi simpatiu unu kun alia laŭ Kristo Jesuo;","Kaj la Dio de pacienco kaj konsolo donu al vi, ke vi simpatiu unu kun alia laŭ Kristo Jesuo;"],[15,6,"por ke vi unuanime per unu voĉo gloru la Dion kaj Patron de nia Sinjoro Jesuo Kristo.","por ke vi unuanime per unu voĉo gloru la Dion kaj Patron de nia Sinjoro Jesuo Kristo."],[15,7,"Tial akceptu unu la alian, kiel ankaŭ Kristo akceptis vin, al la gloro de Dio.","Tial akceptu unu la alian, kiel ankaŭ Kristo akceptis vin, al la gloro de Dio."],[15,8,"Ĉar mi diras, ke Kristo fariĝis servanto al la cirkumcidularo pro la vereco de Dio, por konfirmi la promesojn al la patroj,","Ĉar mi diras, ke Kristo fariĝis servanto al la cirkumcidularo pro la vereco de Dio, por konfirmi la promesojn al la patroj,"],[15,9,"kaj ke la nacianoj pro lia kompato gloru Dion, kiel estas skribite: Tial mi gloros Vin inter la popoloj, Kaj pri Via nomo mi kantos.","kaj ke la nacianoj pro lia kompato gloru Dion, kiel estas skribite: Tial mi gloros Vin inter la popoloj, Kaj pri Via nomo mi kantos."],[15,10,"Kaj ankaŭ oni diras: Ĝoju, ho gentoj, kun Lia popolo.","Kaj ankaŭ oni diras: Ĝoju, ho gentoj, kun Lia popolo."],[15,11,"Kaj ankaŭ: Gloru la Eternulon ĉiuj popoloj, Kaj laŭdu Lin ĉiuj gentoj.","Kaj ankaŭ: Gloru la Eternulon ĉiuj popoloj, Kaj laŭdu Lin ĉiuj gentoj."],[15,12,"Kaj ankaŭ Jesaja diras: Estos radiko de Jiŝaj, Kaj la stariĝanto por regi la naciojn. Al li celados la nacioj.","Kaj ankaŭ Jesaja diras: Estos radiko de Jiŝaj, Kaj la stariĝanto por regi la naciojn. Al li celados la nacioj."],[15,13,"Kaj la Dio de espero plenigu vin per ĉia ĝojo kaj paco en kredado, por ke vi abunde havu esperon, laŭ la potenco de la Sankta Spirito.","Kaj la Dio de espero plenigu vin per ĉia ĝojo kaj paco en kredado, por ke vi abunde havu esperon, laŭ la potenco de la Sankta Spirito."],[15,14,"Kaj, ho miaj fratoj, mi mem konvinkiĝis pri vi, ke vi mem estas plenaj de boneco, plenigitaj per ĉia sciado, kaj kapablaj admoni unu la alian.","Kaj, ho miaj fratoj, mi mem konvinkiĝis pri vi, ke vi mem estas plenaj de boneco, plenigitaj per ĉia sciado, kaj kapablaj admoni unu la alian."],[15,15,"Tamen mi iom pli kuraĝe skribas al vi, kvazaŭ rememorigante vin per la graco, donita al mi de Dio,","Tamen mi iom pli kuraĝe skribas al vi, kvazaŭ rememorigante vin per la graco, donita al mi de Dio,"],[15,16,"ke mi estu servanto de Kristo Jesuo al la nacianoj, solenanta la evangelion de Dio, por ke la oferado de la nacianoj fariĝu akceptebla, sanktigite de la Sankta Spirito.","ke mi estu servanto de Kristo Jesuo al la nacianoj, solenanta la evangelion de Dio, por ke la oferado de la nacianoj fariĝu akceptebla, sanktigite de la Sankta Spirito."],[15,17,"Mi povas do fieri en Kristo Jesuo pri tio, kio rilatas al Dio.","Mi povas do fieri en Kristo Jesuo pri tio, kio rilatas al Dio."],[15,18,"Ĉar mi ne kuraĝos priparoli ion, krom tio, kion Kristo faris per mi, por obeigi la nacianojn, vorte kaj fare,","Ĉar mi ne kuraĝos priparoli ion, krom tio, kion Kristo faris per mi, por obeigi la nacianojn, vorte kaj fare,"],[15,19,"en la potenco de signoj kaj mirindaĵoj, en la potenco de la Sankta Spirito; tiel, ke de Jerusalem kaj ĉirkaŭe ĝis Iliriko mi plene predikis la evangelion de Kristo;","en la potenco de signoj kaj mirindaĵoj, en la potenco de la Sankta Spirito; tiel, ke de Jerusalem kaj ĉirkaŭe ĝis Iliriko mi plene predikis la evangelion de Kristo;"],[15,20,"jenon ambiciante: tiel prediki la evangelion, ne tie, kie Kristo jam estis priparolita, ke mi ne konstruu sur la fundamento de alia;","jenon ambiciante: tiel prediki la evangelion, ne tie, kie Kristo jam estis priparolita, ke mi ne konstruu sur la fundamento de alia;"],[15,21,"sed kiel estas skribite: Vidos tiuj, al kiuj ne estis dirite pri li, Kaj komprenos tiuj, kiuj ne aŭdis.","sed kiel estas skribite: Vidos tiuj, al kiuj ne estis dirite pri li, Kaj komprenos tiuj, kiuj ne aŭdis."],[15,22,"Pro tio ankaŭ mi ofte estis malhelpita veni al vi;","Pro tio ankaŭ mi ofte estis malhelpita veni al vi;"],[15,23,"sed jam ne havante lokon en ĉi tiuj regionoj, kaj dum multe da jaroj sopirante veni al vi,","sed jam ne havante lokon en ĉi tiuj regionoj, kaj dum multe da jaroj sopirante veni al vi,"],[15,24,"kiam mi veturos al Hispanujo, mi venos al vi (ĉar mi esperas vin viziti travojaĝante, kaj esti helpata de vi sur la vojo, se antaŭe mi estos sufiĉe gastinta ĉe vi);","kiam mi veturos al Hispanujo, mi venos al vi (ĉar mi esperas vin viziti travojaĝante, kaj esti helpata de vi sur la vojo, se antaŭe mi estos sufiĉe gastinta ĉe vi);"],[15,25,"sed nun mi veturas al Jerusalem, farante servon al la sanktuloj.","sed nun mi veturas al Jerusalem, farante servon al la sanktuloj."],[15,26,"Ĉar Makedonujo kaj la Aĥaja lando volonte decidis fari monoferon por la neriĉaj sanktuloj en Jerusalem.","Ĉar Makedonujo kaj la Aĥaja lando volonte decidis fari monoferon por la neriĉaj sanktuloj en Jerusalem."],[15,27,"Volonte ili decidis, estante iliaj ŝuldantoj. Ĉar se la nacianoj partoprenas en iliaj spiritaj aferoj, tiuj siavice devas servi al ili ankaŭ en materiaj aferoj.","Volonte ili decidis, estante iliaj ŝuldantoj. Ĉar se la nacianoj partoprenas en iliaj spiritaj aferoj, tiuj siavice devas servi al ili ankaŭ en materiaj aferoj."],[15,28,"Tial, plenuminte ĉi tion, kaj sigelinte por ili ĉi tiun frukton, mi ekiros Hispanujon, kaj vizitos vin survoje.","Tial, plenuminte ĉi tion, kaj sigelinte por ili ĉi tiun frukton, mi ekiros Hispanujon, kaj vizitos vin survoje."],[15,29,"Kaj mi scias, ke venante al vi, mi venos en la pleneco de la beno de Kristo.","Kaj mi scias, ke venante al vi, mi venos en la pleneco de la beno de Kristo."],[15,30,"Sed mi petas vin, fratoj, pro nia Sinjoro Jesuo Kristo kaj pro la amo de la Spirito, ke vi kunluktu kun mi en viaj preĝoj al Dio pro mi;","Sed mi petas vin, fratoj, pro nia Sinjoro Jesuo Kristo kaj pro la amo de la Spirito, ke vi kunluktu kun mi en viaj preĝoj al Dio pro mi;"],[15,31,"ke mi liberiĝu de la malobeemuloj en Judujo, kaj ke mia servo al Jerusalem estu akceptebla al la sanktuloj;","ke mi liberiĝu de la malobeemuloj en Judujo, kaj ke mia servo al Jerusalem estu akceptebla al la sanktuloj;"],[15,32,"por ke mi venu ĝoje al vi per la volo de Dio kaj trovu ripozon ĉe vi.","por ke mi venu ĝoje al vi per la volo de Dio kaj trovu ripozon ĉe vi."],[15,33,"Kaj la Dio de paco estu kun vi ĉiuj. Amen.","Kaj la Dio de paco estu kun vi ĉiuj. Amen."],[16,1,"Mi rekomendas al vi nian fratinon Febe, kiu estas diakonino de la eklezio en Kenkrea;","Mi rekomendas al vi nian fratinon Febe, kiu estas diakonino de la eklezio en Kenkrea;"],[16,2,"por ke vi akceptu ŝin en la Sinjoro, kiel konvenas al sanktuloj, kaj ke vi helpu ŝin, en ĉiuj aferoj, pri kiuj ŝi bezonos vin; ĉar ŝi ankaŭ estis helpantino de multaj, kaj de mi mem.","por ke vi akceptu ŝin en la Sinjoro, kiel konvenas al sanktuloj, kaj ke vi helpu ŝin, en ĉiuj aferoj, pri kiuj ŝi bezonos vin; ĉar ŝi ankaŭ estis helpantino de multaj, kaj de mi mem."],[16,3,"Salutu Priskilan kaj Akvilan, miajn kunlaborantojn en Kristo Jesuo,","Salutu Priskilan kaj Akvilan, miajn kunlaborantojn en Kristo Jesuo,"],[16,4,"kiuj pro mia vivo riskis siajn kolojn; ilin dankas ne nur mi, sed ankaŭ ĉiuj eklezioj de la nacianoj;","kiuj pro mia vivo riskis siajn kolojn; ilin dankas ne nur mi, sed ankaŭ ĉiuj eklezioj de la nacianoj;"],[16,5,"kaj salutu la eklezion en ilia domo. Salutu mian amatan Epajneton, kiu estas la unuaaĵo de Azio por Kristo.","kaj salutu la eklezion en ilia domo. Salutu mian amatan Epajneton, kiu estas la unuaaĵo de Azio por Kristo."],[16,6,"Salutu Marian, kiu multe laboris por vi.","Salutu Marian, kiu multe laboris por vi."],[16,7,"Salutu Andronikon kaj Junion, miajn parencojn kaj miajn kunkaptitojn, kiuj estas konataj inter la apostoloj, kaj ankaŭ estis en Kristo antaŭ ol mi.","Salutu Andronikon kaj Junion, miajn parencojn kaj miajn kunkaptitojn, kiuj estas konataj inter la apostoloj, kaj ankaŭ estis en Kristo antaŭ ol mi."],[16,8,"Salutu Ampliason, mian amaton en la Sinjoro.","Salutu Ampliason, mian amaton en la Sinjoro."],[16,9,"Salutu Urbanon, nian kunlaboranton por Kristo, kaj mian amatan Staĥison.","Salutu Urbanon, nian kunlaboranton por Kristo, kaj mian amatan Staĥison."],[16,10,"Salutu Apeleson, la aprobitan en Kristo. Salutu tiujn, kiuj estas ĉe Aristobulo.","Salutu Apeleson, la aprobitan en Kristo. Salutu tiujn, kiuj estas ĉe Aristobulo."],[16,11,"Salutu mian parencon Herodion. Salutu tiujn ĉe Narkiso, kiuj estas en la Sinjoro.","Salutu mian parencon Herodion. Salutu tiujn ĉe Narkiso, kiuj estas en la Sinjoro."],[16,12,"Salutu Trifajnan kaj Trifosan, kiuj laboras en la Sinjoro. Salutu Persison, la virinon amatan, kiu multe laboris en la Sinjoro.","Salutu Trifajnan kaj Trifosan, kiuj laboras en la Sinjoro. Salutu Persison, la virinon amatan, kiu multe laboris en la Sinjoro."],[16,13,"Salutu Rufon, elektitan de la Sinjoro, kaj lian kaj mian patrinon.","Salutu Rufon, elektitan de la Sinjoro, kaj lian kaj mian patrinon."],[16,14,"Salutu Asinkriton, Flegonon, Hermeson, Patrobason, Hermason, kaj la fratojn ĉe ili.","Salutu Asinkriton, Flegonon, Hermeson, Patrobason, Hermason, kaj la fratojn ĉe ili."],[16,15,"Salutu Filologon kaj Julian, Nereon kaj lian fratinon, kaj Olimpason, kaj ĉiujn sanktulojn kun ili.","Salutu Filologon kaj Julian, Nereon kaj lian fratinon, kaj Olimpason, kaj ĉiujn sanktulojn kun ili."],[16,16,"Salutu unu la alian per sankta kiso. Ĉiuj eklezioj de Kristo vin salutas.","Salutu unu la alian per sankta kiso. Ĉiuj eklezioj de Kristo vin salutas."],[16,17,"Nun mi vin petas, fratoj, observi tiujn, kiuj kaŭzas la malkonsentojn kaj ofendojn kontraŭ la instruado, kiun vi lernis; kaj forturni vin de ili.","Nun mi vin petas, fratoj, observi tiujn, kiuj kaŭzas la malkonsentojn kaj ofendojn kontraŭ la instruado, kiun vi lernis; kaj forturni vin de ili."],[16,18,"Ĉar tiaj homoj servas ne al nia Sinjoro Kristo, sed al sia ventro; kaj per siaj belaj kaj flataj vortoj ili trompas la korojn de la naivuloj.","Ĉar tiaj homoj servas ne al nia Sinjoro Kristo, sed al sia ventro; kaj per siaj belaj kaj flataj vortoj ili trompas la korojn de la naivuloj."],[16,19,"Ĉar via obeemeco estas sciigita al ĉiuj homoj. Tial mi ĝojas pro vi; sed mi deziras, ke vi estu saĝaj rilate la bonon kaj malkleraj rilate la malbonon.","Ĉar via obeemeco estas sciigita al ĉiuj homoj. Tial mi ĝojas pro vi; sed mi deziras, ke vi estu saĝaj rilate la bonon kaj malkleraj rilate la malbonon."],[16,20,"Kaj la Dio de paco baldaŭ subpremos Satanon sub viaj piedoj. La graco de nia Sinjoro Jesuo Kristo estu kun vi.","Kaj la Dio de paco baldaŭ subpremos Satanon sub viaj piedoj. La graco de nia Sinjoro Jesuo Kristo estu kun vi."],[16,21,"Salutas vin Timoteo, mia kunlaboranto, kaj Lucio kaj Jason kaj Sosipatro, miaj parencoj.","Salutas vin Timoteo, mia kunlaboranto, kaj Lucio kaj Jason kaj Sosipatro, miaj parencoj."],[16,22,"Mi, Tertio, kiu skribis ĉi tiun epistolon, salutas vin en la Sinjoro.","Mi, Tertio, kiu skribis ĉi tiun epistolon, salutas vin en la Sinjoro."],[16,23,"Vin salutas Gajo, la gastiganto de mi kaj de la tuta eklezio. Vin salutas Erasto, la ekonomo de la urbo, kaj Kvarto, la frato.","Vin salutas Gajo, la gastiganto de mi kaj de la tuta eklezio. Vin salutas Erasto, la ekonomo de la urbo, kaj Kvarto, la frato."],[16,24,"La graco de nia Sinjoro Jesuo Kristo estu kun vi ĉiuj. Amen.","La graco de nia Sinjoro Jesuo Kristo estu kun vi ĉiuj. Amen."],[16,25,"Al Tiu, kiu povas fortikigi vin, laŭ mia evangelio kaj la predikado de Jesuo Kristo, laŭ la malkaŝo de la mistero, silentigita tra eternaj tempoj,","Al Tiu, kiu povas fortikigi vin, laŭ mia evangelio kaj la predikado de Jesuo Kristo, laŭ la malkaŝo de la mistero, silentigita tra eternaj tempoj,"],[16,26,"sed nun elmontrita, kaj per la profetaj skriboj laŭ la ordono de la eterna Dio sciigita al ĉiuj nacioj por obeado de fido;","sed nun elmontrita, kaj per la profetaj skriboj laŭ la ordono de la eterna Dio sciigita al ĉiuj nacioj por obeado de fido;"],[16,27,"al la sola saĝa Dio, per Jesuo Kristo estu la gloro por ĉiam kaj eterne. Amen.","al la sola saĝa Dio, per Jesuo Kristo estu la gloro por ĉiam kaj eterne. Amen."]]}};